/// Compact progress snapshot from the last direct HT cleanup traversal.
///
/// This is intentionally narrower than the internal HT parser progress type:
/// it exposes the fields useful to benchmark parser and dispatch provenance
/// without committing the public codestream workspace API to every temporary
/// parser detail.
#[cfg(feature = "std")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HtCodestreamVlcCleanupProgressSnapshot {
    pub line_pair_count: usize,
    pub step_count: usize,
    pub symbol_count: usize,
    pub side_input_quad_side_bits_consumed: usize,
    pub side_input_odd_tail_u_values_consumed: usize,
    pub side_input_quad_side_bits_remaining: usize,
    pub side_input_odd_tail_u_values_remaining: usize,
}

#[cfg(feature = "std")]
impl HtCodestreamVlcCleanupProgressSnapshot {
    fn from_progress(progress: ht::HtVlcBlockCleanupSegmentProgress) -> Self {
        Self {
            line_pair_count: progress.decode.line_pair_count,
            step_count: progress.decode.step_count,
            symbol_count: progress.decode.symbol_count,
            side_input_quad_side_bits_consumed: progress.side_input_consumed.quad_side_bits,
            side_input_odd_tail_u_values_consumed: progress.side_input_consumed.odd_tail_u_values,
            side_input_quad_side_bits_remaining: progress.side_input_remaining.quad_side_bits,
            side_input_odd_tail_u_values_remaining: progress.side_input_remaining.odd_tail_u_values,
        }
    }
}

