/// Codestream-level class used for the last reusable HT code-block dispatch.
#[cfg(feature = "std")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HtCodestreamCodeBlockDecodeRequestClass {
    /// Request entered the implemented direct cleanup-group decoder.
    DirectCleanupGroups,
    /// Request entered direct cleanup followed by scalar HT refinement.
    DirectRefinementPasses,
    /// Request is structurally admitted but still needs real HT block decoding.
    PendingBlockDecode,
}

/// Compact provenance snapshot from the last reusable HT code-block dispatch.
#[cfg(feature = "std")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
