#[cfg(feature = "std")]
impl From<ht::HtCodeBlockDecodeRequestClass> for HtCodestreamCodeBlockDecodeRequestClass {
    fn from(request_class: ht::HtCodeBlockDecodeRequestClass) -> Self {
        match request_class {
            ht::HtCodeBlockDecodeRequestClass::DirectCleanupGroups => Self::DirectCleanupGroups,
            ht::HtCodeBlockDecodeRequestClass::DirectRefinementPasses => {
                Self::DirectRefinementPasses
            }
            ht::HtCodeBlockDecodeRequestClass::PendingBlockDecode => Self::PendingBlockDecode,
        }
    }
}

#[cfg(feature = "std")]
impl HtCodestreamCodeBlockDispatchProgressSnapshot {
    fn from_progress(progress: ht::HtCodeBlockDecodeDispatchProgress) -> Self {
        let materialization = progress.materialization_progress;
        Self {
            request_class: progress.request_class.into(),
            used_standard_vlc_cleanup_tables: progress.used_standard_vlc_cleanup_tables(),
            cleanup_segment_bit_progress: progress
                .cleanup_segment_progress
                .map(HtCodestreamVlcCleanupSegmentBitProgressSnapshot::from_progress),
            materialized_coefficients: progress.materialized_coefficients(),
            materialized_output_count: materialization.map(|progress| progress.output_count),
            materialized_coefficient_count: materialization
                .map(|progress| progress.coefficient_count),
            materialized_cleanup_bitplane: materialization
                .map(|progress| progress.cleanup_bitplane),
        }
    }
}

