    fn decode_code_block_input_into_with_progress<'out>(
        &mut self,
        code_block_input: HtCodestreamCodeBlockInput<'_>,
        output: &'out mut [i32],
    ) -> Result<(
        Option<HtCodestreamDecodedCodeBlockView<'out>>,
        ht::HtCodeBlockDecodeDispatchProgress,
    )> {
        let expected_len = code_block_input.coefficient_count();
        let request = code_block_input.decode_request();
        match self
            .scratch
            .decode_code_block_request_into_with_dispatch_progress(request, output)
        {
            Ok((ht::HtCodeBlockDecodeOutcome::Decoded(decoded), progress)) => {
                let decoded_len = decoded.coefficients.len();
                if decoded_len != expected_len {
                    return Err(CodestreamError::SizeOverflow);
                }
                Ok((
                    Some(HtCodestreamDecodedCodeBlockView {
                        active_dimensions: decoded.active_dimensions,
                        coefficients: decoded.coefficients,
                    }),
                    progress,
                ))
            }
            Ok((ht::HtCodeBlockDecodeOutcome::PendingBlockDecode, progress)) => {
                Ok((None, progress))
            }
            Err(error) => Err(ht_decode_error(error)),
        }
    }

