/// Component samples reconstructed by the narrow repo-owned baseline path.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DecodedComponent {
    pub samples: Vec<u8>,
}

/// Caller-owned packed rows for one selected decoded component.
#[derive(Debug)]
pub struct ComponentPlaneMut<'a> {
    pub samples: &'a mut [u8],
    pub stride_bytes: usize,
}

/// Reusable scratch for selective Part 1 component reconstruction.
///
/// One workspace is intended per decode worker. It retains the largest classic
/// Tier-1 state, coefficient block, and fragmented code-block byte buffer seen
/// across calls without retaining input or output references.
#[derive(Default)]
pub struct Part1ComponentDecodeWorkspace {
    coefficient_scratch: Vec<i32>,
    tier1_scratch: tier1::CodeBlockDecodeScratch,
    segment_scratch: Vec<u8>,
    transform_scratch: Vec<i32>,
    irreversible_transform_scratch: Vec<f32>,
    reversible_window_coefficients: Option<transform::WindowCoefficientPlane<i32>>,
    irreversible_window_coefficients: Option<transform::WindowCoefficientPlane<f32>>,
    reversible_window_synthesis: transform::WindowSynthesisWorkspace<i32>,
    irreversible_window_synthesis: transform::WindowSynthesisWorkspace<f32>,
    reversible_full_coefficients: Vec<i32>,
    irreversible_full_coefficients: Vec<f32>,
    reversible_full_synthesis: transform::FullSynthesisWorkspace<i32>,
    irreversible_full_synthesis: transform::FullSynthesisWorkspace<f32>,
    #[cfg(feature = "parallel")]
    parallel_workers: Vec<Part1ComponentDecodeWorkspace>,
    #[cfg(feature = "parallel")]
    parallel_decoded_blocks: Vec<Part1ParallelDecodedCodeBlock>,
}

impl Part1ComponentDecodeWorkspace {
    pub fn new() -> Self {
        Self::default()
    }

    /// Coefficient slots retained for the largest selected code block.
    pub fn coefficient_capacity(&self) -> usize {
        let capacity = self.coefficient_scratch.capacity();
        #[cfg(feature = "parallel")]
        {
            let capacity = self
                .parallel_workers
                .iter()
                .fold(capacity, |largest, worker| {
                    largest.max(worker.coefficient_capacity())
                });
            self.parallel_decoded_blocks
                .iter()
                .fold(capacity, |largest, block| {
                    largest.max(block.coefficients.capacity())
                })
        }
        #[cfg(not(feature = "parallel"))]
        capacity
    }

    /// Byte capacity retained for physically fragmented code-block segments.
    pub fn segment_capacity(&self) -> usize {
        let capacity = self.segment_scratch.capacity();
        #[cfg(feature = "parallel")]
        {
            self.parallel_workers
                .iter()
                .fold(capacity, |largest, worker| {
                    largest.max(worker.segment_capacity())
                })
        }
        #[cfg(not(feature = "parallel"))]
        capacity
    }

    /// Transform scratch slots retained for the largest selected tile axis.
    pub fn transform_capacity(&self) -> usize {
        let capacity = self
            .transform_scratch
            .capacity()
            .max(self.irreversible_transform_scratch.capacity());
        #[cfg(feature = "parallel")]
        {
            self.parallel_workers
                .iter()
                .fold(capacity, |largest, worker| {
                    largest.max(worker.transform_capacity())
                })
        }
        #[cfg(not(feature = "parallel"))]
        capacity
    }

    /// Bytes retained by direct bounded transform workspaces.
    pub fn window_transform_retained_heap_bytes(&self) -> u64 {
        self.reversible_window_synthesis
            .retained_heap_bytes()
            .saturating_add(self.irreversible_window_synthesis.retained_heap_bytes())
    }

    /// Bytes retained by compact bounded coefficient planes.
    pub fn window_coefficient_retained_heap_bytes(&self) -> u64 {
        self.reversible_window_coefficients
            .as_ref()
            .map_or(0, transform::WindowCoefficientPlane::retained_heap_bytes)
            .saturating_add(
                self.irreversible_window_coefficients
                    .as_ref()
                    .map_or(0, transform::WindowCoefficientPlane::retained_heap_bytes),
            )
    }

    /// Largest retained full coefficient-plane capacity, in samples.
    pub fn full_coefficient_plane_capacity(&self) -> usize {
        let capacity = self
            .reversible_full_coefficients
            .capacity()
            .max(self.irreversible_full_coefficients.capacity());
        #[cfg(feature = "parallel")]
        {
            self.parallel_workers
                .iter()
                .fold(capacity, |largest, worker| {
                    largest.max(worker.full_coefficient_plane_capacity())
                })
        }
        #[cfg(not(feature = "parallel"))]
        capacity
    }

    /// Largest retained full-transform workspace capacity, in samples.
    pub fn full_transform_scratch_capacity(&self) -> usize {
        let capacity = self
            .reversible_full_synthesis
            .capacity_samples()
            .max(self.irreversible_full_synthesis.capacity_samples());
        #[cfg(feature = "parallel")]
        {
            self.parallel_workers
                .iter()
                .fold(capacity, |largest, worker| {
                    largest.max(worker.full_transform_scratch_capacity())
                })
        }
        #[cfg(not(feature = "parallel"))]
        capacity
    }

    /// Clear current logical lengths while preserving allocation capacity.
    pub fn clear(&mut self) {
        self.coefficient_scratch.clear();
        self.tier1_scratch.clear();
        self.segment_scratch.clear();
        self.transform_scratch.clear();
        self.irreversible_transform_scratch.clear();
        if let Some(coefficients) = &mut self.reversible_window_coefficients {
            coefficients.clear();
        }
        if let Some(coefficients) = &mut self.irreversible_window_coefficients {
            coefficients.clear();
        }
        self.reversible_window_synthesis.clear();
        self.irreversible_window_synthesis.clear();
        self.reversible_full_coefficients.clear();
        self.irreversible_full_coefficients.clear();
        self.reversible_full_synthesis.clear();
        self.irreversible_full_synthesis.clear();
        #[cfg(feature = "parallel")]
        for worker in &mut self.parallel_workers {
            worker.clear();
        }
        #[cfg(feature = "parallel")]
        for block in &mut self.parallel_decoded_blocks {
            block.coefficients.clear();
        }
    }

    /// Worker workspaces retained by the adaptive prepared-plan executor.
    pub fn parallel_worker_capacity(&self) -> usize {
        #[cfg(feature = "parallel")]
        {
            self.parallel_workers.capacity()
        }
        #[cfg(not(feature = "parallel"))]
        0
    }

    /// Capacity-based heap bytes retained by this workspace and its private
    /// prepared-execution workers. Allocator metadata is excluded.
    pub fn retained_heap_bytes(&self) -> u64 {
        let capacity_bytes = |capacity: usize, element_bytes: usize| {
            u64::try_from(capacity)
                .unwrap_or(u64::MAX)
                .saturating_mul(u64::try_from(element_bytes).unwrap_or(u64::MAX))
        };
        let retained = capacity_bytes(self.coefficient_scratch.capacity(), size_of::<i32>())
            .saturating_add(self.tier1_scratch.retained_heap_bytes())
            .saturating_add(capacity_bytes(
                self.segment_scratch.capacity(),
                size_of::<u8>(),
            ))
            .saturating_add(capacity_bytes(
                self.transform_scratch.capacity(),
                size_of::<i32>(),
            ))
            .saturating_add(capacity_bytes(
                self.irreversible_transform_scratch.capacity(),
                size_of::<f32>(),
            ))
            .saturating_add(self.window_coefficient_retained_heap_bytes())
            .saturating_add(self.window_transform_retained_heap_bytes())
            .saturating_add(capacity_bytes(
                self.reversible_full_coefficients.capacity(),
                size_of::<i32>(),
            ))
            .saturating_add(capacity_bytes(
                self.irreversible_full_coefficients.capacity(),
                size_of::<f32>(),
            ))
            .saturating_add(self.reversible_full_synthesis.retained_heap_bytes())
            .saturating_add(self.irreversible_full_synthesis.retained_heap_bytes());
        #[cfg(feature = "parallel")]
        {
            let worker_storage = capacity_bytes(
                self.parallel_workers.capacity(),
                size_of::<Part1ComponentDecodeWorkspace>(),
            );
            let worker_heaps = self.parallel_workers.iter().fold(0_u64, |total, worker| {
                total.saturating_add(worker.retained_heap_bytes())
            });
            let block_storage = capacity_bytes(
                self.parallel_decoded_blocks.capacity(),
                size_of::<Part1ParallelDecodedCodeBlock>(),
            );
            let block_heaps = self
                .parallel_decoded_blocks
                .iter()
                .fold(0_u64, |total, block| {
                    total.saturating_add(capacity_bytes(
                        block.coefficients.capacity(),
                        size_of::<i32>(),
                    ))
                });
            retained
                .saturating_add(worker_storage)
                .saturating_add(worker_heaps)
                .saturating_add(block_storage)
                .saturating_add(block_heaps)
        }
        #[cfg(not(feature = "parallel"))]
        retained
    }
}

