/// Instrumentation policy for prepared selective Part 1 execution.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum DecodeInstrumentation {
    /// Production fast path: retain preparation provenance and final output
    /// geometry without collecting execution-stage work counters.
    #[default]
    None,
    /// Collect cheap execution work counters in plain worker-local values.
    WorkCounters,
    /// Collect coarse preparation and execution stage timings without taking
    /// a clock around every Tier-1 code block.
    StageTimings,
    /// Opt in to detailed per-code-block Tier-1 timings and optional Tier-1
    /// work counters. This mode deliberately accepts profiling overhead.
    DetailedProfile,
}

/// Options controlling one execution of a prepared selective Part 1 plan.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct PreparedPart1ExecutionOptions {
    pub instrumentation: DecodeInstrumentation,
    pub collect_tier1_work_counters: bool,
    /// Bound how much parallel work this execution contributes to the current
    /// Rayon pool. This never constructs a nested pool.
    pub parallelism: DecodeExecutionParallelism,
    /// Maximum retained bytes for the active full coefficient plane and its
    /// selected transform workspace. `None` uses the documented default.
    pub retained_memory_limit: Option<u64>,
    /// Adaptive large full-plane latency-versus-memory preference.
    pub latency_policy: DecodeLatencyPolicy,
    /// Force a full-plane backend for differential validation and focused
    /// qualification. This does not manufacture a transform for LL-only
    /// requests after all decomposition levels have been discarded.
    pub full_synthesis_backend: Option<FullSynthesisBackend>,
    /// Force equal-count or cost-weighted contiguous Tier-1 shards. `None`
    /// uses the adaptive production policy.
    pub tier1_shard_strategy: Option<Tier1ShardStrategy>,
    /// Force split or fused segment acquisition and Tier-1. `None` uses the
    /// fused production route.
    pub tier1_acquisition_route: Option<Tier1AcquisitionRoute>,
    /// Force independent phase worker counts for differential qualification.
    /// `None` uses the adaptive plan within `parallelism`'s caller budget.
    pub phase_worker_plan: Option<PhaseWorkerPlan>,
    /// Force bounded-window or full-plane synthesis for cropped differential
    /// qualification. `None` uses the dependency-aware crossover policy.
    pub synthesis_crossover_route: Option<SynthesisCrossoverRoute>,
}

pub use transform::{FullSynthesisBackend, FullSynthesisEstimate};

/// Cached architecture kernel used by parallel-transpose full synthesis.
pub fn full_transpose_backend_name() -> &'static str {
    transform::full_transpose_backend_name()
}

/// Performance preference used by adaptive large full-plane synthesis.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum DecodeLatencyPolicy {
    /// Prefer the measured throughput route within the default memory ceiling.
    #[default]
    Balanced,
    /// Prefer the transpose backend whenever it satisfies the memory limit.
    Throughput,
    /// Prefer bounded striped scratch and retain legacy as the final fallback.
    LowMemory,
}

/// Optional policy for large full-plane inverse synthesis.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct FullSynthesisExecutionOptions {
    /// Maximum retained bytes for the coefficient plane and selected full
    /// transform workspace. `None` uses the documented 640 MiB ceiling.
    pub retained_memory_limit: Option<u64>,
    pub latency_policy: DecodeLatencyPolicy,
    /// Force one backend for differential tests and focused qualification.
    pub backend: Option<FullSynthesisBackend>,
}

impl From<PreparedPart1ExecutionOptions> for FullSynthesisExecutionOptions {
    fn from(options: PreparedPart1ExecutionOptions) -> Self {
        Self {
            retained_memory_limit: options.retained_memory_limit,
            latency_policy: options.latency_policy,
            backend: options.full_synthesis_backend,
        }
    }
}

/// Caller policy for prepared Part 1 execution inside the current Rayon pool.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum DecodeExecutionParallelism {
    /// Let the adaptive scheduler use the current pool's available workers.
    #[default]
    Adaptive,
    /// Execute without interacting with Rayon even when the feature and a pool
    /// are available.
    Serial,
    /// Limit the scheduler to at most this many independent work chunks. Zero
    /// is invalid and is rejected before output mutation.
    MaxWorkers(usize),
}

/// Capacity-based accounting for heap storage retained by a prepared plan.
///
/// Allocator metadata and the borrowed compressed bytes are deliberately not
/// included. `retained_heap_bytes` counts the byte capacity of every owned
/// vector/box reachable from the plan.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct PreparedPart1PlanMemory {
    pub retained_heap_bytes: u64,
    pub prepared_packet_count: u64,
    pub prepared_code_block_count: u64,
    pub prepared_range_count: u64,
    pub bytes_per_prepared_packet: u64,
    pub bytes_per_prepared_code_block: u64,
}

