/// Raw marker segment record retained for diagnostics and future parser passes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MarkerSegment {
    pub marker: Marker,
    pub offset: usize,
    pub data_offset: usize,
    pub data_len: usize,
}

/// JPEG 2000 marker codes recognized by the metadata parser.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Marker {
    Soc,
    Sot,
    Sod,
    Eoc,
    Siz,
    Cod,
    Coc,
    Rgn,
    Qcd,
    Qcc,
    Poc,
    Tlm,
    Plm,
    Plt,
    Ppm,
    Ppt,
    Sop,
    Eph,
    Cap,
    Com,
    Unknown(u16),
}

impl Marker {
    pub fn code(self) -> u16 {
        match self {
            Self::Soc => 0xff4f,
            Self::Sot => 0xff90,
            Self::Sod => 0xff93,
            Self::Eoc => 0xffd9,
            Self::Siz => 0xff51,
            Self::Cod => 0xff52,
            Self::Coc => 0xff53,
            Self::Rgn => 0xff5e,
            Self::Qcd => 0xff5c,
            Self::Qcc => 0xff5d,
            Self::Poc => 0xff5f,
            Self::Tlm => 0xff55,
            Self::Plm => 0xff57,
            Self::Plt => 0xff58,
            Self::Ppm => 0xff60,
            Self::Ppt => 0xff61,
            Self::Sop => 0xff91,
            Self::Eph => 0xff92,
            Self::Cap => 0xff50,
            Self::Com => 0xff64,
            Self::Unknown(code) => code,
        }
    }

    pub fn from_code(code: u16) -> Self {
        match code {
            0xff4f => Self::Soc,
            0xff90 => Self::Sot,
            0xff93 => Self::Sod,
            0xffd9 => Self::Eoc,
            0xff51 => Self::Siz,
            0xff52 => Self::Cod,
            0xff53 => Self::Coc,
            0xff5e => Self::Rgn,
            0xff5c => Self::Qcd,
            0xff5d => Self::Qcc,
            0xff5f => Self::Poc,
            0xff55 => Self::Tlm,
            0xff57 => Self::Plm,
            0xff58 => Self::Plt,
            0xff60 => Self::Ppm,
            0xff61 => Self::Ppt,
            0xff91 => Self::Sop,
            0xff92 => Self::Eph,
            0xff50 => Self::Cap,
            0xff64 => Self::Com,
            value => Self::Unknown(value),
        }
    }

    fn has_segment(self) -> bool {
        !matches!(self, Self::Soc | Self::Sod | Self::Eoc | Self::Eph)
            && !self.is_reserved_parameterless()
    }

    fn is_reserved_parameterless(self) -> bool {
        matches!(self, Self::Unknown(0xff30..=0xff3f))
    }
}

impl fmt::Display for Marker {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unknown(code) => write!(f, "0x{code:04x}"),
            marker => write!(f, "{marker:?}"),
        }
    }
}

/// Codestream parser and classifier error.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CodestreamError {
    Source {
        offset: u64,
        requested: u64,
        available: u64,
        message: String,
    },
    TruncatedInput {
        offset: usize,
        needed: usize,
        remaining: usize,
    },
    InvalidMarker {
        offset: Option<usize>,
        marker: Option<Marker>,
        message: &'static str,
    },
    Unsupported {
        offset: Option<usize>,
        marker: Option<Marker>,
        construct: UnsupportedConstruct,
        message: &'static str,
    },
    SizeOverflow,
}

/// Unsupported codestream constructs reported before decode is attempted.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UnsupportedConstruct {
    MarkerSegment,
    ProgressionOrder,
    WaveletTransform,
    EntropyCoder,
    SamplePrecision,
    ComponentCount,
    ComponentSampling,
    MultipleTiles,
    Part2Capabilities,
    HtBlockDecode,
    PacketDecode,
    Tier1Decode,
    Transform,
}

impl fmt::Display for CodestreamError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Source {
                offset,
                requested,
                available,
                message,
            } => write!(
                f,
                "codestream source failure at byte {offset}: requested {requested} bytes, available {available} ({message})"
            ),
            Self::TruncatedInput {
                offset,
                needed,
                remaining,
            } => write!(
                f,
                "truncated codestream input at byte {offset}: needed {needed} bytes, had {remaining}"
            ),
            Self::InvalidMarker {
                offset,
                marker,
                message,
            } => match (offset, marker) {
                (Some(offset), Some(marker)) => {
                    write!(f, "invalid {marker} marker at byte {offset}: {message}")
                }
                (Some(offset), None) => write!(f, "invalid marker at byte {offset}: {message}"),
                (None, Some(marker)) => write!(f, "invalid {marker} marker: {message}"),
                (None, None) => write!(f, "invalid marker: {message}"),
            },
            Self::Unsupported {
                offset,
                marker,
                construct,
                message,
            } => match (offset, marker) {
                (Some(offset), Some(marker)) => write!(
                    f,
                    "unsupported {construct:?} in {marker} marker at byte {offset}: {message}"
                ),
                (Some(offset), None) => {
                    write!(f, "unsupported {construct:?} at byte {offset}: {message}")
                }
                (None, Some(marker)) => {
                    write!(f, "unsupported {construct:?} in {marker} marker: {message}")
                }
                (None, None) => write!(f, "unsupported {construct:?}: {message}"),
            },
            Self::SizeOverflow => f.write_str("codestream size overflowed usize"),
        }
    }
}

#[cfg(feature = "std")]
impl std::error::Error for CodestreamError {}

/// Convenient result alias for codestream operations.
pub type Result<T> = core::result::Result<T, CodestreamError>;

impl From<source::SourceError> for CodestreamError {
    fn from(error: source::SourceError) -> Self {
        Self::Source {
            offset: error.offset,
            requested: error.requested,
            available: error.available,
            message: error.message,
        }
    }
}

impl From<transform::TransformError> for CodestreamError {
    fn from(_error: transform::TransformError) -> Self {
        Self::SizeOverflow
    }
}

fn source_error_in_phase(error: source::SourceError, phase: &'static str) -> CodestreamError {
    CodestreamError::Source {
        offset: error.offset,
        requested: error.requested,
        available: error.available,
        message: format!("{phase}: {}", error.message),
    }
}

/// Boundary marker for future marker parser state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CodestreamBoundary {
    pub kind: CodestreamKind,
}

/// Parse marker-level codestream metadata from a byte slice.
pub fn parse(input: &[u8]) -> Result<Codestream> {
    parse_with_selected_region(input, None).map(|(codestream, _)| codestream)
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct TilePartParseWork {
    tile_parts_skipped_via_tlm: u64,
    tile_part_bytes_skipped_via_tlm: u64,
}

struct SourceHeaderScan {
    marker_bytes: Vec<u8>,
    codestream: Codestream,
    payload_spans: BTreeMap<u16, Vec<SourcePayloadSpan>>,
    work: TilePartParseWork,
}

fn source_marker(source: &dyn source::CodestreamSource, offset: u64) -> Result<Marker> {
    let mut bytes = [0_u8; 2];
    source.read_exact_at(offset, &mut bytes)?;
    if bytes[0] != 0xff {
        return Err(CodestreamError::Source {
            offset,
            requested: 2,
            available: 2,
            message: String::from("expected a JPEG 2000 marker prefix"),
        });
    }
    Ok(Marker::from_code(u16::from_be_bytes(bytes)))
}

fn scan_part1_source_headers(
    source: &dyn source::CodestreamSource,
    selected_region: TileRegionRequest,
) -> Result<SourceHeaderScan> {
    // Two-byte marker windows avoid speculatively pulling packet bodies across
    // SOT/SOD while segment payloads are still coalesced into exact reads.
    const HEADER_WINDOW_BYTES: usize = 2;

    let mut cursor = source::BufferedSourceCursor::new(source, 0, HEADER_WINDOW_BYTES)?;
    let mut marker_bytes = Vec::new();
    let mut marker_code = [0_u8; 2];
    cursor.read_exact(&mut marker_code)?;
    marker_bytes.extend_from_slice(&marker_code);
    if Marker::from_code(u16::from_be_bytes(marker_code)) != Marker::Soc {
        return Err(invalid(
            Some(0),
            Some(Marker::from_code(u16::from_be_bytes(marker_code))),
            "codestream source must start with SOC marker",
        ));
    }

    let mut siz = None;
    let mut coding_style = None;
    let mut capability = None;
    let mut markers = Vec::new();
    let first_sot_source_offset = loop {
        let source_offset = cursor.position();
        cursor.read_exact(&mut marker_code)?;
        let marker = Marker::from_code(u16::from_be_bytes(marker_code));
        if marker == Marker::Sot {
            cursor.seek(source_offset)?;
            break source_offset;
        }
        let marker_offset = marker_bytes.len();
        marker_bytes.extend_from_slice(&marker_code);
        if !marker.has_segment() {
            markers.push(MarkerSegment {
                marker,
                offset: marker_offset,
                data_offset: marker_bytes.len(),
                data_len: 0,
            });
            if marker.is_reserved_parameterless() {
                continue;
            }
            return Err(invalid(
                usize::try_from(source_offset).ok(),
                Some(marker),
                "source main header ended before SOT",
            ));
        }
        let mut length_bytes = [0_u8; 2];
        cursor.read_exact(&mut length_bytes)?;
        marker_bytes.extend_from_slice(&length_bytes);
        let segment_len = usize::from(u16::from_be_bytes(length_bytes));
        if segment_len < 2 {
            return Err(invalid(
                Some(marker_offset),
                Some(marker),
                "marker segment length must include its length field",
            ));
        }
        let data_offset = marker_bytes.len();
        let data_len = segment_len - 2;
        let old_len = marker_bytes.len();
        marker_bytes.resize(
            old_len
                .checked_add(data_len)
                .ok_or(CodestreamError::SizeOverflow)?,
            0,
        );
        cursor.read_exact(&mut marker_bytes[old_len..])?;
        let segment = &marker_bytes[data_offset..data_offset + data_len];
        markers.push(MarkerSegment {
            marker,
            offset: marker_offset,
            data_offset,
            data_len,
        });
        match marker {
            Marker::Siz => siz = Some(parse_siz(segment, marker_offset)?),
            Marker::Cod => coding_style = Some(parse_cod(segment, marker_offset)?),
            Marker::Cap => capability = Some(parse_cap(segment, marker_offset)?),
            _ => {}
        }
    };

    let siz = siz.ok_or(CodestreamError::InvalidMarker {
        offset: None,
        marker: Some(Marker::Siz),
        message: "codestream main header must contain SIZ marker",
    })?;
    validate_siz(&siz)?;
    let declared =
        parse_declared_tile_part_lengths(&marker_bytes, &siz, &markers, marker_bytes.len())?;
    let tile_rects = tile_rects_for_siz(&siz)?;
    let mut selected_tiles = alloc::vec![false; tile_rects.len()];
    for tile in &tile_rects {
        if tile_intersects_region(*tile, selected_region) {
            *selected_tiles
                .get_mut(usize::from(tile.tile_index))
                .ok_or(CodestreamError::SizeOverflow)? = true;
        }
    }

    let mut all_tiles = Vec::new();
    let mut selected_tile_states = Vec::new();
    let mut payload_spans = BTreeMap::<u16, Vec<SourcePayloadSpan>>::new();
    let mut work = TilePartParseWork::default();
    let mut next_source_offset = first_sot_source_offset;
    let mut declared_index = 0_usize;
    loop {
        if let Some(declared) = declared.as_ref() {
            if declared_index == declared.len() {
                if source_marker(source, next_source_offset)? != Marker::Eoc {
                    return Err(invalid(
                        declared.last().map(|entry| entry.marker_offset),
                        Some(Marker::Tlm),
                        "complete source TLM coverage must end at EOC",
                    ));
                }
                break;
            }
        } else if source_marker(source, next_source_offset)? == Marker::Eoc {
            break;
        }

        let mut sot_bytes = [0_u8; 12];
        source.read_exact_at(next_source_offset, &mut sot_bytes)?;
        if Marker::from_code(u16::from_be_bytes([sot_bytes[0], sot_bytes[1]])) != Marker::Sot
            || u16::from_be_bytes([sot_bytes[2], sot_bytes[3]]) != 10
        {
            return Err(CodestreamError::Source {
                offset: next_source_offset,
                requested: 12,
                available: 12,
                message: String::from("tile-part index does not point to a valid SOT segment"),
            });
        }
        let tile = parse_sot(
            &sot_bytes[4..],
            usize::try_from(next_source_offset).unwrap_or(0),
        )?;
        let psot = tile.tile_part_length.ok_or_else(|| {
            unsupported(
                usize::try_from(next_source_offset).ok(),
                Some(Marker::Sot),
                UnsupportedConstruct::MarkerSegment,
                "source-backed scanning requires a bounded SOT Psot length",
            )
        })?;
        if let Some(declared) = declared.as_ref() {
            let entry = declared
                .get(declared_index)
                .ok_or(CodestreamError::SizeOverflow)?;
            if entry.tile_index != tile.tile_index || entry.tile_part_length != psot {
                return Err(invalid(
                    Some(entry.marker_offset),
                    Some(Marker::Tlm),
                    "source TLM entry disagrees with SOT Isot/Psot",
                ));
            }
        }
        all_tiles.push(tile);
        let selected = selected_tiles
            .get(usize::from(tile.tile_index))
            .copied()
            .unwrap_or(false);
        if selected {
            let (selected_tile, span) = scan_selected_source_tile_part_header(
                source,
                next_source_offset,
                psot,
                &mut marker_bytes,
                &mut markers,
            )?;
            selected_tile_states.push(selected_tile);
            payload_spans.entry(tile.tile_index).or_default().push(span);
        } else {
            let unread = u64::from(psot).saturating_sub(sot_bytes.len() as u64);
            source.record_bytes_not_read(unread, 0);
            if declared.is_some() {
                work.tile_parts_skipped_via_tlm = work.tile_parts_skipped_via_tlm.saturating_add(1);
                work.tile_part_bytes_skipped_via_tlm = work
                    .tile_part_bytes_skipped_via_tlm
                    .saturating_add(u64::from(psot));
            } else {
                // Psot scanning observed and sequence-validates every SOT while
                // leaving unselected optional headers/bodies unread. Retain a
                // metadata-only tile state so the existing profile validator
                // can prove full SIZ tile coverage; regional planning never
                // asks the payload factory for this tile.
                let mut metadata_only = tile;
                metadata_only.payload_offset = Some(0);
                metadata_only.payload_len =
                    Some(usize::try_from(psot).map_err(|_| CodestreamError::SizeOverflow)?);
                selected_tile_states.push(metadata_only);
            }
        }
        next_source_offset = next_source_offset
            .checked_add(u64::from(psot))
            .ok_or(CodestreamError::SizeOverflow)?;
        declared_index += 1;
    }
    validate_indexed_tile_part_sequence(&siz, &all_tiles)?;

    let eoc_offset = marker_bytes.len();
    marker_bytes.extend_from_slice(&Marker::Eoc.code().to_be_bytes());
    markers.push(MarkerSegment {
        marker: Marker::Eoc,
        offset: eoc_offset,
        data_offset: eoc_offset + 2,
        data_len: 0,
    });
    let kind = if capability.is_some() {
        CodestreamKind::Htj2k
    } else {
        CodestreamKind::J2k
    };
    if kind == CodestreamKind::Htj2k
        && let Some(style) = &mut coding_style
    {
        style.entropy_coder = EntropyCoder::HtBlockCoding;
    }
    let progression = ProgressionState {
        order: coding_style.map(|style| style.progression_order),
        layers: coding_style.map(|style| style.layers),
        next_packet: PacketCursor::default(),
    };
    let tile_part_lengths = declared.as_ref().map(|declared| TilePartLengthTable {
        entries: declared
            .iter()
            .map(|entry| TilePartLengthEntry {
                tile_index: entry.tile_index,
                tile_part_length: entry.tile_part_length,
                // Source-backed prepared topology retains the authoritative
                // physical `u64` offsets in `SourcePayloadSpan`; these compact
                // entries exist only to preserve complete-TLM validation state.
                sot_offset: 0,
                marker_offset: entry.marker_offset,
            })
            .collect(),
        fully_covers_codestream: true,
    });
    Ok(SourceHeaderScan {
        marker_bytes,
        codestream: Codestream {
            kind,
            siz,
            coding_style,
            capability,
            tile_part_lengths,
            markers,
            tiles: selected_tile_states,
            progression,
        },
        payload_spans,
        work,
    })
}

fn scan_selected_source_tile_part_header(
    source: &dyn source::CodestreamSource,
    sot_source_offset: u64,
    psot: u32,
    marker_bytes: &mut Vec<u8>,
    markers: &mut Vec<MarkerSegment>,
) -> Result<(TilePartState, SourcePayloadSpan)> {
    const TILE_HEADER_WINDOW_BYTES: usize = 2;
    let mut cursor =
        source::BufferedSourceCursor::new(source, sot_source_offset, TILE_HEADER_WINDOW_BYTES)?;
    let mut parsed_tile: Option<TilePartState> = None;
    loop {
        let marker_source_offset = cursor.position();
        let marker_offset = marker_bytes.len();
        let mut code = [0_u8; 2];
        cursor.read_exact(&mut code)?;
        marker_bytes.extend_from_slice(&code);
        let marker = Marker::from_code(u16::from_be_bytes(code));
        if !marker.has_segment() {
            markers.push(MarkerSegment {
                marker,
                offset: marker_offset,
                data_offset: marker_bytes.len(),
                data_len: 0,
            });
            if marker.is_reserved_parameterless() {
                continue;
            }
            if marker != Marker::Sod {
                return Err(invalid(
                    Some(marker_offset),
                    Some(marker),
                    "selected source tile header ended before SOD",
                ));
            }
            let payload_source_offset = cursor.position();
            let header_len = payload_source_offset
                .checked_sub(sot_source_offset)
                .ok_or(CodestreamError::SizeOverflow)?;
            let payload_len = u64::from(psot).checked_sub(header_len).ok_or_else(|| {
                invalid(
                    Some(marker_offset),
                    Some(Marker::Sot),
                    "SOT Psot ends before the selected SOD payload",
                )
            })?;
            let mut tile = parsed_tile.ok_or(CodestreamError::SizeOverflow)?;
            tile.payload_offset = Some(marker_bytes.len());
            tile.payload_len =
                Some(usize::try_from(payload_len).map_err(|_| CodestreamError::SizeOverflow)?);
            return Ok((
                tile,
                SourcePayloadSpan {
                    logical_offset: 0,
                    source_offset: payload_source_offset,
                    len: usize::try_from(payload_len).map_err(|_| CodestreamError::SizeOverflow)?,
                },
            ));
        }

        let mut length_bytes = [0_u8; 2];
        cursor.read_exact(&mut length_bytes)?;
        marker_bytes.extend_from_slice(&length_bytes);
        let segment_len = usize::from(u16::from_be_bytes(length_bytes));
        if segment_len < 2 {
            return Err(invalid(
                Some(marker_offset),
                Some(marker),
                "tile marker segment length must include its length field",
            ));
        }
        let data_offset = marker_bytes.len();
        let data_len = segment_len - 2;
        let old_len = marker_bytes.len();
        marker_bytes.resize(
            old_len
                .checked_add(data_len)
                .ok_or(CodestreamError::SizeOverflow)?,
            0,
        );
        cursor.read_exact(&mut marker_bytes[old_len..])?;
        markers.push(MarkerSegment {
            marker,
            offset: marker_offset,
            data_offset,
            data_len,
        });
        if marker == Marker::Sot {
            if marker_source_offset != sot_source_offset || segment_len != 10 {
                return Err(invalid(
                    Some(marker_offset),
                    Some(Marker::Sot),
                    "selected tile-part must begin with a ten-byte SOT segment",
                ));
            }
            let tile = parse_sot(
                &marker_bytes[data_offset..data_offset + data_len],
                marker_offset,
            )?;
            if tile.tile_part_length != Some(psot) {
                return Err(invalid(
                    Some(marker_offset),
                    Some(Marker::Sot),
                    "selected SOT Psot changed during header scanning",
                ));
            }
            parsed_tile = Some(tile);
        }
        if cursor.position().saturating_sub(sot_source_offset) >= u64::from(psot) {
            return Err(invalid(
                Some(marker_offset),
                Some(Marker::Sot),
                "selected tile header reaches Psot before SOD",
            ));
        }
    }
}

fn parse_with_selected_region(
    input: &[u8],
    selected_region: Option<TileRegionRequest>,
) -> Result<(Codestream, TilePartParseWork)> {
    if input.is_empty() {
        return Err(CodestreamError::TruncatedInput {
            offset: 0,
            needed: 2,
            remaining: 0,
        });
    }

    let mut offset = 0;
    let soc = read_marker(input, offset)?;
    if soc != Marker::Soc {
        return Err(invalid(
            Some(offset),
            Some(soc),
            "codestream must start with SOC marker",
        ));
    }
    offset += 2;

    let mut siz = None;
    let mut coding_style = None;
    let mut capability = None;
    let mut markers = Vec::new();
    let mut tiles = Vec::new();
    let mut saw_payload_boundary = false;
    let mut tile_part_lengths_override = None;
    let mut parse_work = TilePartParseWork::default();

    while offset < input.len() {
        let marker_offset = offset;
        let marker = read_marker(input, marker_offset)?;
        offset += 2;

        if !marker.has_segment() {
            markers.push(MarkerSegment {
                marker,
                offset: marker_offset,
                data_offset: offset,
                data_len: 0,
            });
            if matches!(marker, Marker::Sod | Marker::Eoc) {
                saw_payload_boundary = true;
                break;
            }
            continue;
        }

        let segment_len = read_u16(input, offset)? as usize;
        if segment_len < 2 {
            return Err(invalid(
                Some(marker_offset),
                Some(marker),
                "marker segment length must include the two-byte length field",
            ));
        }
        let data_offset = offset + 2;
        let data_len = segment_len - 2;
        require(input, data_offset, data_len)?;
        let segment = checked_slice(input, data_offset, data_len)?;
        if marker == Marker::Sot
            && tiles.is_empty()
            && let (Some(region), Some(siz)) = (selected_region, siz.as_ref())
            && let Some(indexed) =
                parse_selected_tile_parts_from_tlm(input, siz, &markers, marker_offset, region)?
        {
            markers.extend(indexed.markers);
            tiles = indexed.tiles;
            tile_part_lengths_override = Some(indexed.tile_part_lengths);
            parse_work = indexed.work;
            saw_payload_boundary = true;
            break;
        }
        markers.push(MarkerSegment {
            marker,
            offset: marker_offset,
            data_offset,
            data_len,
        });

        match marker {
            Marker::Siz => siz = Some(parse_siz(segment, marker_offset)?),
            Marker::Cod => coding_style = Some(parse_cod(segment, marker_offset)?),
            Marker::Cap => capability = Some(parse_cap(segment, marker_offset)?),
            Marker::Sot => {
                let mut tile = parse_sot(segment, marker_offset)?;
                offset = data_offset
                    .checked_add(data_len)
                    .ok_or(CodestreamError::SizeOverflow)?;
                offset = retain_tile_part_header_markers(input, offset, &mut markers)?;
                let payload_len =
                    tile_payload_len(input, marker_offset, offset, tile.tile_part_length)?;
                tile.payload_offset = Some(offset);
                tile.payload_len = Some(payload_len);
                tiles.push(tile);
                saw_payload_boundary = true;
                if tile.tile_part_length.is_none() {
                    break;
                }
                offset = offset
                    .checked_add(payload_len)
                    .ok_or(CodestreamError::SizeOverflow)?;
                continue;
            }
            _ => {}
        }

        offset = data_offset
            .checked_add(data_len)
            .ok_or(CodestreamError::SizeOverflow)?;
    }

    let siz = siz.ok_or(CodestreamError::InvalidMarker {
        offset: None,
        marker: Some(Marker::Siz),
        message: "codestream main header must contain SIZ marker",
    })?;
    validate_siz(&siz)?;
    let tile_part_lengths = match tile_part_lengths_override {
        Some(table) => Some(table),
        None => parse_tile_part_length_table(input, &siz, &markers, &tiles)?,
    };

    let kind = if capability.is_some() {
        CodestreamKind::Htj2k
    } else {
        CodestreamKind::J2k
    };
    if kind == CodestreamKind::Htj2k
        && let Some(coding_style) = &mut coding_style
    {
        coding_style.entropy_coder = EntropyCoder::HtBlockCoding;
    }
    let progression = ProgressionState {
        order: coding_style.map(|cod| cod.progression_order),
        layers: coding_style.map(|cod| cod.layers),
        next_packet: PacketCursor::default(),
    };

    if !saw_payload_boundary && input.last().copied() != Some(0xd9) {
        return Err(invalid(
            None,
            None,
            "codestream ended before SOT, SOD, or EOC marker",
        ));
    }

    Ok((
        Codestream {
            kind,
            siz,
            coding_style,
            capability,
            tile_part_lengths,
            markers,
            tiles,
            progression,
        },
        parse_work,
    ))
}

struct SelectedTilePartParse {
    markers: Vec<MarkerSegment>,
    tiles: Vec<TilePartState>,
    tile_part_lengths: TilePartLengthTable,
    work: TilePartParseWork,
}

fn parse_selected_tile_parts_from_tlm(
    input: &[u8],
    siz: &SizMarker,
    main_header_markers: &[MarkerSegment],
    first_sot_offset: usize,
    selected_region: TileRegionRequest,
) -> Result<Option<SelectedTilePartParse>> {
    let Some(declared) =
        parse_declared_tile_part_lengths(input, siz, main_header_markers, first_sot_offset)?
    else {
        return Ok(None);
    };
    let tile_count = siz
        .tile_count_x()?
        .checked_mul(siz.tile_count_y()?)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut selected_tiles = alloc::vec![false; usize::try_from(tile_count)
        .map_err(|_| CodestreamError::SizeOverflow)?];
    let mut selected_tile_count = 0_usize;
    for tile in tile_rects_for_siz(siz)? {
        if tile_intersects_region(tile, selected_region) {
            let selected = selected_tiles
                .get_mut(usize::from(tile.tile_index))
                .ok_or(CodestreamError::SizeOverflow)?;
            selected_tile_count += usize::from(!*selected);
            *selected = true;
        }
    }
    if selected_tile_count == 0 {
        return Ok(None);
    }

    let mut offset = first_sot_offset;
    let mut entries = Vec::with_capacity(declared.len());
    let mut markers = Vec::new();
    let mut tiles = Vec::new();
    let mut observed_sots = Vec::with_capacity(declared.len());
    let mut work = TilePartParseWork::default();
    for declared in &declared {
        if read_marker(input, offset)? != Marker::Sot {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile-part offset does not point to SOT",
            ));
        }
        let segment_len = usize::from(read_u16(input, offset + 2)?);
        if segment_len != 10 {
            return Err(invalid(
                Some(offset),
                Some(Marker::Sot),
                "SOT marker segment length must be ten bytes",
            ));
        }
        let data_offset = offset.checked_add(4).ok_or(CodestreamError::SizeOverflow)?;
        let segment = checked_slice(input, data_offset, 8)?;
        let mut tile = parse_sot(segment, offset)?;
        if tile.tile_index != declared.tile_index {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile index disagrees with SOT Isot",
            ));
        }
        let Some(psot) = tile.tile_part_length else {
            return Ok(None);
        };
        if psot != declared.tile_part_length {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile-part length disagrees with SOT Psot",
            ));
        }
        let tile_part_len = usize::try_from(psot).map_err(|_| CodestreamError::SizeOverflow)?;
        require(input, offset, tile_part_len)?;
        observed_sots.push(tile);
        entries.push(TilePartLengthEntry {
            tile_index: declared.tile_index,
            tile_part_length: declared.tile_part_length,
            sot_offset: offset,
            marker_offset: declared.marker_offset,
        });

        if selected_tiles
            .get(usize::from(tile.tile_index))
            .copied()
            .unwrap_or(false)
        {
            markers.push(MarkerSegment {
                marker: Marker::Sot,
                offset,
                data_offset,
                data_len: 8,
            });
            let payload_offset = retain_tile_part_header_markers(
                input,
                data_offset
                    .checked_add(8)
                    .ok_or(CodestreamError::SizeOverflow)?,
                &mut markers,
            )?;
            let tile_part_end = offset
                .checked_add(tile_part_len)
                .ok_or(CodestreamError::SizeOverflow)?;
            if payload_offset > tile_part_end {
                return Err(invalid(
                    Some(offset),
                    Some(Marker::Sot),
                    "SOT tile-part length ends before selected SOD payload",
                ));
            }
            tile.payload_offset = Some(payload_offset);
            tile.payload_len = Some(tile_part_end - payload_offset);
            tiles.push(tile);
        } else {
            work.tile_parts_skipped_via_tlm = work.tile_parts_skipped_via_tlm.saturating_add(1);
            work.tile_part_bytes_skipped_via_tlm = work
                .tile_part_bytes_skipped_via_tlm
                .saturating_add(u64::from(psot));
        }
        offset = offset
            .checked_add(tile_part_len)
            .ok_or(CodestreamError::SizeOverflow)?;
    }

    if read_marker(input, offset)? != Marker::Eoc {
        return Ok(None);
    }
    validate_indexed_tile_part_sequence(siz, &observed_sots)?;
    markers.push(MarkerSegment {
        marker: Marker::Eoc,
        offset,
        data_offset: offset + 2,
        data_len: 0,
    });
    Ok(Some(SelectedTilePartParse {
        markers,
        tiles,
        tile_part_lengths: TilePartLengthTable {
            entries,
            fully_covers_codestream: true,
        },
        work,
    }))
}

fn validate_indexed_tile_part_sequence(siz: &SizMarker, tiles: &[TilePartState]) -> Result<()> {
    let tile_count = siz
        .tile_count_x()?
        .checked_mul(siz.tile_count_y()?)
        .ok_or(CodestreamError::SizeOverflow)?;
    #[derive(Clone, Copy, Default)]
    struct TilePartSequenceState {
        observed: usize,
        declared_total: Option<u8>,
    }

    let mut states = alloc::vec![
        TilePartSequenceState::default();
        usize::try_from(tile_count).map_err(|_| CodestreamError::SizeOverflow)?
    ];
    for tile in tiles {
        let state = states
            .get_mut(usize::from(tile.tile_index))
            .ok_or_else(|| {
                invalid(
                    None,
                    Some(Marker::Sot),
                    "TLM-indexed tile part is outside the SIZ tile grid",
                )
            })?;
        if usize::from(tile.tile_part_index) != state.observed {
            return Err(invalid(
                None,
                Some(Marker::Sot),
                "TLM-indexed tile parts require dense TPsot values per tile",
            ));
        }
        state.observed = state
            .observed
            .checked_add(1)
            .ok_or(CodestreamError::SizeOverflow)?;
        if let Some(count) = tile.tile_part_count {
            if state
                .declared_total
                .is_some_and(|declared| declared != count)
            {
                return Err(invalid(
                    None,
                    Some(Marker::Sot),
                    "TLM-indexed TNsot must be consistent for every tile part",
                ));
            }
            state.declared_total = Some(count);
        }
    }

    for state in states {
        if state.observed == 0 {
            return Err(unsupported(
                None,
                Some(Marker::Tlm),
                UnsupportedConstruct::MarkerSegment,
                "complete TLM coverage requires at least one tile part for every SIZ tile",
            ));
        }
        if state
            .declared_total
            .is_some_and(|count| usize::from(count) != state.observed)
        {
            return Err(invalid(
                None,
                Some(Marker::Sot),
                "TLM-indexed TNsot must match the observed tile-part count",
            ));
        }
    }
    Ok(())
}

fn tile_intersects_region(tile: TileRect, region: TileRegionRequest) -> bool {
    let Some(region_end_x) = region.x.checked_add(region.width) else {
        return false;
    };
    let Some(region_end_y) = region.y.checked_add(region.height) else {
        return false;
    };
    let Some(tile_end_x) = tile.x.checked_add(tile.width) else {
        return false;
    };
    let Some(tile_end_y) = tile.y.checked_add(tile.height) else {
        return false;
    };
    region.width != 0
        && region.height != 0
        && region.x < tile_end_x
        && tile.x < region_end_x
        && region.y < tile_end_y
        && tile.y < region_end_y
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DeclaredTilePartLength {
    tile_index: u16,
    tile_part_length: u32,
    marker_offset: usize,
}

fn parse_declared_tile_part_lengths(
    input: &[u8],
    siz: &SizMarker,
    markers: &[MarkerSegment],
    main_header_end: usize,
) -> Result<Option<Vec<DeclaredTilePartLength>>> {
    let tlm_segments = markers
        .iter()
        .filter(|segment| segment.marker == Marker::Tlm && segment.offset < main_header_end)
        .collect::<Vec<_>>();
    if tlm_segments.is_empty() {
        return Ok(None);
    }

    let tile_count = siz
        .tile_count_x()?
        .checked_mul(siz.tile_count_y()?)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut declared = Vec::new();
    for (expected_index, marker) in tlm_segments.iter().enumerate() {
        let data = checked_slice(input, marker.data_offset, marker.data_len)?;
        if data.len() < 2 {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM marker payload must contain Ztlm and Stlm",
            ));
        }
        if usize::from(data[0]) != expected_index {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM marker indexes must start at zero and increase consecutively",
            ));
        }
        let stlm = data[1];
        if stlm & !0x70 != 0 {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM Stlm reserved bits must be zero",
            ));
        }
        let tile_index_bytes = usize::from((stlm >> 4) & 0x03);
        if tile_index_bytes == 3 {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM Stlm tile-index width three is reserved",
            ));
        }
        let tile_part_length_bytes = if stlm & 0x40 == 0 { 2 } else { 4 };
        let entry_len = tile_index_bytes
            .checked_add(tile_part_length_bytes)
            .ok_or(CodestreamError::SizeOverflow)?;
        let entries = &data[2..];
        if entries.is_empty() || entries.len() % entry_len != 0 {
            return Err(invalid(
                Some(marker.offset),
                Some(Marker::Tlm),
                "TLM entry bytes must contain complete tile/length records",
            ));
        }

        for entry in entries.chunks_exact(entry_len) {
            let tile_index = match tile_index_bytes {
                0 => u32::try_from(declared.len()).map_err(|_| CodestreamError::SizeOverflow)?,
                1 => u32::from(entry[0]),
                2 => u32::from(read_u16(entry, 0)?),
                _ => return Err(CodestreamError::SizeOverflow),
            };
            if tile_index >= tile_count || tile_index > u32::from(u16::MAX) {
                return Err(invalid(
                    Some(marker.offset),
                    Some(Marker::Tlm),
                    "TLM tile index is outside the SIZ tile grid",
                ));
            }
            let length_offset = tile_index_bytes;
            let tile_part_length = if tile_part_length_bytes == 2 {
                u32::from(read_u16(entry, length_offset)?)
            } else {
                read_u32(entry, length_offset)?
            };
            if tile_part_length < 14 {
                return Err(invalid(
                    Some(marker.offset),
                    Some(Marker::Tlm),
                    "TLM tile-part length is shorter than SOT and SOD syntax",
                ));
            }
            declared.push(DeclaredTilePartLength {
                tile_index: u16::try_from(tile_index).map_err(|_| CodestreamError::SizeOverflow)?,
                tile_part_length,
                marker_offset: marker.offset,
            });
        }
    }

    Ok(Some(declared))
}

fn parse_tile_part_length_table(
    input: &[u8],
    siz: &SizMarker,
    markers: &[MarkerSegment],
    tiles: &[TilePartState],
) -> Result<Option<TilePartLengthTable>> {
    let first_sot_offset = markers
        .iter()
        .find(|segment| segment.marker == Marker::Sot)
        .map_or(input.len(), |segment| segment.offset);
    let Some(declared) = parse_declared_tile_part_lengths(input, siz, markers, first_sot_offset)?
    else {
        return Ok(None);
    };

    let sot_markers = markers
        .iter()
        .filter(|segment| segment.marker == Marker::Sot)
        .collect::<Vec<_>>();
    if declared.len() > tiles.len() || sot_markers.len() != tiles.len() {
        return Err(invalid(
            declared.first().map(|entry| entry.marker_offset),
            Some(Marker::Tlm),
            "TLM contains entries outside the observed tile-part progression",
        ));
    }

    let mut entries: Vec<TilePartLengthEntry> = Vec::with_capacity(declared.len());
    for (entry_index, (declared, tile)) in declared.iter().zip(tiles).enumerate() {
        let sot_offset = sot_markers[entry_index].offset;
        if tile.tile_index != declared.tile_index {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile index disagrees with SOT Isot",
            ));
        }
        let observed_length = if let Some(observed) = tile.tile_part_length {
            observed
        } else {
            let tile_part_end = find_marker(
                input,
                tile.payload_offset.ok_or(CodestreamError::SizeOverflow)?,
                Marker::Eoc,
            )
            .ok_or_else(|| {
                invalid(
                    Some(sot_offset),
                    Some(Marker::Tlm),
                    "TLM cannot resolve an open-ended final tile part without EOC",
                )
            })?;
            u32::try_from(
                tile_part_end
                    .checked_sub(sot_offset)
                    .ok_or(CodestreamError::SizeOverflow)?,
            )
            .map_err(|_| CodestreamError::SizeOverflow)?
        };
        if observed_length != declared.tile_part_length {
            return Err(invalid(
                Some(declared.marker_offset),
                Some(Marker::Tlm),
                "TLM tile-part length disagrees with SOT Psot",
            ));
        }
        if let Some(previous) = entries.last() {
            let expected_offset = previous
                .sot_offset
                .checked_add(
                    usize::try_from(previous.tile_part_length)
                        .map_err(|_| CodestreamError::SizeOverflow)?,
                )
                .ok_or(CodestreamError::SizeOverflow)?;
            if sot_offset != expected_offset {
                return Err(invalid(
                    Some(declared.marker_offset),
                    Some(Marker::Tlm),
                    "TLM tile-part lengths do not follow the observed SOT progression",
                ));
            }
        }
        entries.push(TilePartLengthEntry {
            tile_index: declared.tile_index,
            tile_part_length: declared.tile_part_length,
            sot_offset,
            marker_offset: declared.marker_offset,
        });
    }

    let fully_covers_codestream = if entries.len() == tiles.len() {
        let last = entries.last().ok_or(CodestreamError::SizeOverflow)?;
        let eoc_offset = last
            .sot_offset
            .checked_add(
                usize::try_from(last.tile_part_length)
                    .map_err(|_| CodestreamError::SizeOverflow)?,
            )
            .ok_or(CodestreamError::SizeOverflow)?;
        read_marker(input, eoc_offset).map_err(|_| {
            invalid(
                Some(last.marker_offset),
                Some(Marker::Tlm),
                "complete TLM coverage must end at EOC",
            )
        })? == Marker::Eoc
    } else {
        false
    };
    if entries.len() == tiles.len() && !fully_covers_codestream {
        return Err(invalid(
            entries.last().map(|entry| entry.marker_offset),
            Some(Marker::Tlm),
            "complete TLM coverage must end at EOC",
        ));
    }

    Ok(Some(TilePartLengthTable {
        entries,
        fully_covers_codestream,
    }))
}

