/// Build a deterministic planar unsigned 8-bit fixture for cross-crate
/// component-selection tests.
///
/// This is not a general encode API. It deliberately exposes the existing
/// no-decomposition test profile so higher API layers can verify component
/// counts that image-oriented grayscale/RGB encoders cannot express.
#[doc(hidden)]
pub fn encode_planar_u8_no_decomp_test_fixture(
    width: u32,
    height: u32,
    component_planes: &[&[u8]],
) -> Result<Vec<u8>> {
    if component_planes.is_empty() || component_planes.len() > usize::from(u8::MAX) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "planar test fixture requires one to 255 components",
        ));
    }
    let sample_count = checked_component_sample_count(width, height)?;
    let components = component_planes
        .iter()
        .map(|samples| {
            if samples.len() != sample_count {
                return Err(CodestreamError::SizeOverflow);
            }
            Ok(NativeNoDecompComponent {
                coefficients: samples
                    .iter()
                    .map(|sample| i32::from(*sample) - 128)
                    .collect(),
                available_bitplanes: 8,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    encode_native_no_decomp(NativeNoDecompEncode {
        width,
        height,
        bits_per_sample: 8,
        components: &components,
        multiple_component_transform: false,
    })
}

#[cfg(test)]
#[test]
fn reserved_parameterless_markers_are_skipped_in_main_and_tile_headers() {
    let samples = (0_u8..16).collect::<Vec<_>>();
    let mut codestream =
        encode_planar_u8_no_decomp_test_fixture(4, 4, &[&samples]).expect("fixture encodes");
    let sot = find_marker(&codestream, 0, Marker::Sot).expect("fixture has SOT");
    codestream.splice(sot..sot, [0xff, 0x30]);

    let shifted_sot = sot + 2;
    let sod = find_marker(&codestream, shifted_sot, Marker::Sod).expect("fixture has SOD");
    codestream.splice(sod..sod, [0xff, 0x3f]);
    let psot = read_u32(&codestream, shifted_sot + 6).expect("fixture has Psot");
    codestream[shifted_sot + 6..shifted_sot + 10].copy_from_slice(&(psot + 2).to_be_bytes());

    let parsed = parse(&codestream).expect("slice parser skips reserved markers");
    let reserved = parsed
        .markers
        .iter()
        .filter(|segment| segment.marker.is_reserved_parameterless())
        .collect::<Vec<_>>();
    assert_eq!(reserved.len(), 2);
    assert!(reserved.iter().all(|segment| segment.data_len == 0));
    assert!(is_supported_no_decomposition_encode_compatible_profile(
        &parsed
    ));

    let source = source::SliceSource::new(&codestream);
    let components = [0_u16];
    let prepared = prepare_part1_component_decode_from_source(
        &source,
        Part1ComponentDecodeRequest {
            component_indices: &components,
            region: TileRegionRequest {
                x: 0,
                y: 0,
                width: 4,
                height: 4,
            },
            discard_levels: 0,
            max_layers: None,
        },
    )
    .expect("source parser skips reserved markers");
    assert_eq!(prepared.output_dimensions(), (4, 4));
}

/// Build a deterministic no-decomposition CPRL fixture with a 2x2 grid of
/// 64x64 precincts.
///
/// This is test infrastructure for packet-grid interoperability, not a public
/// general-purpose precinct encoder.
#[doc(hidden)]
pub fn encode_grayscale_u8_cprl_precinct_test_fixture(
    input: GrayscaleU8Encode<'_>,
) -> Result<Vec<u8>> {
    validate_grayscale_u8_encode(input)?;
    if input.width != 128 || input.height != 128 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "CPRL precinct test fixture requires an exact 128x128 image",
        ));
    }
    let component = level_shift_grayscale_component(input)?;
    let mut segments = Vec::new();
    let mut scratch = tier1::CodeBlockEncodeScratch::new();
    let code_blocks = encode_no_decomp_component_blocks(
        input.width,
        input.height,
        &component,
        2,
        2,
        &mut segments,
        &mut scratch,
    )?;
    if code_blocks.len() != 4 {
        return Err(CodestreamError::SizeOverflow);
    }

    let mut packets = Vec::new();
    for block in code_blocks {
        let mut local_block = block;
        local_block.x = 0;
        local_block.y = 0;
        let mut writer = PacketBitWriter::new();
        writer.write_bit(u32::from(local_block.included))?;
        if local_block.included {
            write_component_packet_header(&mut writer, 1, 1, core::slice::from_ref(&local_block))?;
        }
        writer.align();
        packets.extend_from_slice(writer.bytes());
        if local_block.included {
            packets.extend_from_slice(checked_slice(
                &segments,
                local_block.segment_offset,
                local_block.segment_len,
            )?);
        }
    }

    let mut codestream = Vec::new();
    write_native_part1_main_header(
        &mut codestream,
        input.width,
        input.height,
        input.width,
        input.height,
        8,
        1,
        false,
        0,
        &[8],
    )?;
    let cod = codestream
        .windows(2)
        .position(|bytes| bytes == [0xff, 0x52])
        .ok_or(CodestreamError::SizeOverflow)?;
    let segment_len = u16::from_be_bytes([codestream[cod + 2], codestream[cod + 3]]);
    codestream[cod + 2..cod + 4].copy_from_slice(
        &segment_len
            .checked_add(1)
            .ok_or(CodestreamError::SizeOverflow)?
            .to_be_bytes(),
    );
    codestream[cod + 4] |= 0x01;
    codestream[cod + 5] = 4;
    codestream.insert(cod + 2 + usize::from(segment_len), 0x66);
    write_tile_part(&mut codestream, 0, &packets, true)?;
    Ok(codestream)
}

/// Build a deterministic one-decomposition CPRL fixture whose two resolution
/// levels share a 2x2 precinct lattice in the image reference grid.
///
/// This is test infrastructure for decomposed packet-grid interoperability,
/// not a public general-purpose precinct encoder.
#[doc(hidden)]
pub fn encode_grayscale_u8_one_decomp_cprl_precinct_test_fixture(
    input: GrayscaleU8Encode<'_>,
) -> Result<Vec<u8>> {
    validate_grayscale_u8_encode(input)?;
    if input.width != 256 || input.height != 192 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "decomposed CPRL precinct test fixture requires an exact 256x192 image",
        ));
    }

    let mut coefficients = level_shift_grayscale_plane(input)?;
    forward_reversible_5_3_levels(
        input.width,
        input.height,
        &mut coefficients,
        1,
        "forward reversible 5/3 transform failed for decomposed CPRL test fixture",
    )?;
    let subband_specs = decomp_subband_specs(input.width, input.height, 1)?;
    let component_planes = [coefficients.as_slice()];
    let qcd_exponents = subband_specs
        .iter()
        .map(|spec| {
            max_component_subband_available_bitplanes(input.width, &component_planes, *spec)
        })
        .collect::<Result<Vec<_>>>()?;
    let mut segments = Vec::new();
    let mut component_subbands = Vec::new();
    encode_decomp_components_sequential(
        input.width,
        &component_planes,
        &subband_specs,
        &qcd_exponents,
        &mut component_subbands,
        &mut segments,
    )?;
    let subbands = component_subbands
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    if subbands.iter().any(|subband| {
        subband.code_block_cols != 2
            || subband.code_block_rows != 2
            || subband.code_blocks.len() != 4
    }) {
        return Err(CodestreamError::SizeOverflow);
    }

    let mut packets = Vec::new();
    for precinct in 0..4_u16 {
        let precinct_x = precinct % 2;
        let precinct_y = precinct / 2;
        for resolution in 0..=1 {
            let packet_subbands = subbands
                .iter()
                .filter(|subband| subband.resolution == resolution)
                .collect::<Vec<_>>();
            let mut local_blocks = Vec::with_capacity(packet_subbands.len());
            for subband in &packet_subbands {
                let block_index = usize::from(precinct_y)
                    .checked_mul(usize::from(subband.code_block_cols))
                    .and_then(|offset| offset.checked_add(usize::from(precinct_x)))
                    .ok_or(CodestreamError::SizeOverflow)?;
                let mut block = subband
                    .code_blocks
                    .get(block_index)
                    .cloned()
                    .ok_or(CodestreamError::SizeOverflow)?;
                block.x = 0;
                block.y = 0;
                local_blocks.push(block);
            }

            let has_contribution = local_blocks.iter().any(|block| block.included);
            let mut writer = PacketBitWriter::new();
            writer.write_bit(u32::from(has_contribution))?;
            if has_contribution {
                for block in &local_blocks {
                    write_component_packet_header(&mut writer, 1, 1, core::slice::from_ref(block))?;
                }
            }
            writer.align();
            packets.extend_from_slice(writer.bytes());
            for block in local_blocks.iter().filter(|block| block.included) {
                packets.extend_from_slice(checked_slice(
                    &segments,
                    block.segment_offset,
                    block.segment_len,
                )?);
            }
        }
    }

    let mut codestream = Vec::new();
    write_native_part1_main_header(
        &mut codestream,
        input.width,
        input.height,
        input.width,
        input.height,
        8,
        1,
        false,
        1,
        &qcd_exponents,
    )?;
    let cod = codestream
        .windows(2)
        .position(|bytes| bytes == [0xff, 0x52])
        .ok_or(CodestreamError::SizeOverflow)?;
    let segment_len = u16::from_be_bytes([codestream[cod + 2], codestream[cod + 3]]);
    codestream[cod + 2..cod + 4].copy_from_slice(
        &segment_len
            .checked_add(2)
            .ok_or(CodestreamError::SizeOverflow)?
            .to_be_bytes(),
    );
    codestream[cod + 4] |= 0x01;
    codestream[cod + 5] = 4;
    let precinct_offset = cod
        .checked_add(2 + usize::from(segment_len))
        .ok_or(CodestreamError::SizeOverflow)?;
    codestream.splice(precinct_offset..precinct_offset, [0x66, 0x77]);
    write_tile_part(&mut codestream, 0, &packets, true)?;
    Ok(codestream)
}

