/// Encode a single-tile unsigned 8-bit RGB Part 1 codestream using the
/// repo-owned no-decomposition baseline slice and forward reversible color
/// transform.
pub fn encode_rgb_u8_no_decomp(input: RgbU8Encode<'_>) -> Result<Vec<u8>> {
    validate_rgb_u8_encode(input)?;
    let components = forward_rct_rgb_components(input)?;
    encode_native_no_decomp(NativeNoDecompEncode {
        width: input.width,
        height: input.height,
        bits_per_sample: 8,
        components: &components,
        multiple_component_transform: true,
    })
}

/// Encode a single-tile unsigned 8-bit RGB cleanup-only HTJ2K codestream with
/// no wavelet decomposition or multiple-component transform.
pub fn encode_htj2k_rgb_u8_no_decomp(input: RgbU8Encode<'_>) -> Result<Vec<u8>> {
    validate_rgb_u8_encode(input)?;
    let components = level_shift_rgb_u8_components(input)?;
    encode_native_ht_no_decomp(NativeNoDecompEncode {
        width: input.width,
        height: input.height,
        bits_per_sample: 8,
        components: &components,
        multiple_component_transform: false,
    })
}

/// Encode a single-tile unsigned 8-bit RGB Part 1 codestream using the
/// repo-owned one-decomposition reversible 5/3 slice and forward reversible
/// color transform.
pub fn encode_rgb_u8_one_decomp(input: RgbU8Encode<'_>) -> Result<Vec<u8>> {
    validate_rgb_u8_encode(input)?;
    let [mut y, mut db, mut dr] =
        forward_rct_rgb_components(input)?.map(|component| component.coefficients);
    forward_reversible_5_3_rgb_components(
        input.width,
        input.height,
        &mut y,
        &mut db,
        &mut dr,
        1,
        "forward reversible 5/3 transform failed for native RGB encode",
    )?;
    encode_native_decomp_transformed(
        input.width,
        input.height,
        8,
        1,
        &[y.as_slice(), db.as_slice(), dr.as_slice()],
        true,
    )
}

