struct NativeNoDecompEncode<'a> {
    width: u32,
    height: u32,
    bits_per_sample: u8,
    components: &'a [NativeNoDecompComponent],
    multiple_component_transform: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeDecompTile {
    tile_rect: TileRect,
    component_planes: Vec<Vec<i32>>,
}

fn encode_native_no_decomp(input: NativeNoDecompEncode<'_>) -> Result<Vec<u8>> {
    if input.components.is_empty() || input.components.len() > usize::from(u8::MAX) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native no-decomposition encode supports one to 255 components",
        ));
    }
    if !matches!(input.bits_per_sample, 8 | 16) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native no-decomposition encode supports unsigned 8-bit or 16-bit precision",
        ));
    }
    let component_samples = checked_component_sample_count(input.width, input.height)?;
    for component in input.components {
        if component.coefficients.len() != component_samples {
            return Err(CodestreamError::SizeOverflow);
        }
        if component.available_bitplanes == 0 {
            return Err(CodestreamError::SizeOverflow);
        }
    }
    let mut code_blocks = Vec::new();
    let mut segments = Vec::new();
    let code_block_cols =
        u16::try_from(ceil_div(input.width, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
    let code_block_rows =
        u16::try_from(ceil_div(input.height, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
    let blocks_per_component = usize::from(code_block_cols)
        .checked_mul(usize::from(code_block_rows))
        .ok_or(CodestreamError::SizeOverflow)?;
    if blocks_per_component == 0 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "image contains no code-blocks",
        ));
    }
    code_blocks.reserve(input.components.len());

    #[cfg(feature = "parallel")]
    {
        if input.components.len() == 1
            && should_parallel_encode_no_decomp_blocks(
                input.width,
                input.height,
                blocks_per_component,
            )
        {
            let component_blocks = encode_no_decomp_component_blocks_parallel(
                input.width,
                input.height,
                &input.components[0],
                code_block_cols,
                code_block_rows,
                &mut segments,
                true,
            )?;
            code_blocks.push(component_blocks);
        } else if should_parallel_encode_no_decomp_components(
            input.width,
            input.height,
            input.components.len(),
            blocks_per_component,
        ) {
            let encoded_components = encode_no_decomp_components_parallel(
                input.width,
                input.height,
                input.components,
                code_block_cols,
                code_block_rows,
            )?;
            reserve_encoded_no_decomp_component_segments(&mut segments, &encoded_components)?;
            for component in encoded_components {
                push_encoded_no_decomp_component(component, &mut code_blocks, &mut segments)?;
            }
        } else {
            let mut tier1_encode_scratch = tier1::CodeBlockEncodeScratch::new();
            for component in input.components {
                let component_blocks = encode_no_decomp_component_blocks(
                    input.width,
                    input.height,
                    component,
                    code_block_cols,
                    code_block_rows,
                    &mut segments,
                    &mut tier1_encode_scratch,
                )?;
                code_blocks.push(component_blocks);
            }
        }
    }
    #[cfg(not(feature = "parallel"))]
    {
        let mut tier1_encode_scratch = tier1::CodeBlockEncodeScratch::new();
        for component in input.components {
            let component_blocks = encode_no_decomp_component_blocks(
                input.width,
                input.height,
                component,
                code_block_cols,
                code_block_rows,
                &mut segments,
                &mut tier1_encode_scratch,
            )?;
            code_blocks.push(component_blocks);
        }
    }

    let mut packet = Vec::with_capacity(native_no_decomp_packet_capacity_hint(
        &code_blocks,
        &segments,
    )?);
    write_native_no_decomp_packets(
        &mut packet,
        code_block_cols,
        code_block_rows,
        &code_blocks,
        &segments,
    )?;

    let mut codestream = Vec::with_capacity(native_single_tile_codestream_capacity_hint(
        packet.len(),
        input.components.len(),
        1,
    )?);
    write_native_part1_main_header(
        &mut codestream,
        input.width,
        input.height,
        input.width,
        input.height,
        input.bits_per_sample,
        u16::try_from(input.components.len()).map_err(|_| CodestreamError::SizeOverflow)?,
        input.multiple_component_transform,
        0,
        &[input.bits_per_sample],
    )?;
    write_tile_part(&mut codestream, 0, &packet, true)?;
    Ok(codestream)
}

fn encode_native_ht_no_decomp(input: NativeNoDecompEncode<'_>) -> Result<Vec<u8>> {
    if !matches!(input.components.len(), 1 | 3) || !(8..=16).contains(&input.bits_per_sample) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::ComponentCount,
            "native HTJ2K no-decomposition encode supports grayscale/RGB unsigned 8- through 16-bit samples",
        ));
    }
    let component_samples = checked_component_sample_count(input.width, input.height)?;
    for component in input.components {
        if component.coefficients.len() != component_samples
            || component.available_bitplanes != input.bits_per_sample
        {
            return Err(CodestreamError::SizeOverflow);
        }
    }

    let code_block_cols =
        u16::try_from(ceil_div(input.width, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
    let code_block_rows =
        u16::try_from(ceil_div(input.height, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
    let mut code_blocks = Vec::with_capacity(input.components.len());
    let mut segments = Vec::new();
    for component in input.components {
        code_blocks.push(encode_ht_no_decomp_component_blocks(
            input.width,
            input.height,
            component,
            code_block_cols,
            code_block_rows,
            &mut segments,
        )?);
    }

    let mut packet = Vec::with_capacity(native_no_decomp_packet_capacity_hint(
        &code_blocks,
        &segments,
    )?);
    write_native_no_decomp_packets(
        &mut packet,
        code_block_cols,
        code_block_rows,
        &code_blocks,
        &segments,
    )?;

    let mut codestream = Vec::with_capacity(native_single_tile_codestream_capacity_hint(
        packet.len(),
        input.components.len(),
        1,
    )?);
    write_native_ht_main_header(
        &mut codestream,
        input.width,
        input.height,
        input.bits_per_sample,
        u16::try_from(input.components.len()).map_err(|_| CodestreamError::SizeOverflow)?,
        input.multiple_component_transform,
    )?;
    write_tile_part(&mut codestream, 0, &packet, true)?;
    Ok(codestream)
}

/// Report whether feature-gated parallel encode paths are eligible for the
/// current native Part 1 encode benchmark row.
#[doc(hidden)]
pub fn encode_parallel_plan_for_bench(
    width: u32,
    height: u32,
    bits_per_sample: u8,
    component_count: usize,
    decomposition_levels: u8,
    tile_size: Option<TileSize>,
) -> Result<EncodeParallelPlan> {
    if width == 0 || height == 0 || component_count == 0 {
        return Err(CodestreamError::SizeOverflow);
    }
    if !matches!(bits_per_sample, 8 | 16) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native encode parallel plan supports unsigned 8-bit or 16-bit precision",
        ));
    }
    if !matches!(component_count, 1 | 3) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native encode parallel plan supports one or three components",
        ));
    }
    if !matches!(decomposition_levels, 0..=2) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "native encode parallel plan supports decomposition levels 0, 1, and 2",
        ));
    }
    if tile_size.is_some() && decomposition_levels != 2 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "native multi-tile encode parallel plan requires two decomposition levels",
        ));
    }

    let component_count_u64 =
        u64::try_from(component_count).map_err(|_| CodestreamError::SizeOverflow)?;
    let blocks_per_component = encode_code_blocks_per_component(width, height)?;
    let total_code_blocks = blocks_per_component
        .checked_mul(component_count)
        .ok_or(CodestreamError::SizeOverflow)?;

    let mut tile_count = 1_usize;
    let mut tile_component_samples = u64::from(width)
        .saturating_mul(u64::from(height))
        .saturating_mul(component_count_u64);
    let mut multitile_subband_parallel_eligible_tile_count = 0_usize;
    let mut multitile_component_parallel_eligible_tile_count = 0_usize;

    if let Some(tile_size) = tile_size {
        if tile_size.width == 0 || tile_size.height == 0 {
            return Err(CodestreamError::SizeOverflow);
        }
        let tile_count_x = ceil_div(width, tile_size.width)?;
        let tile_count_y = ceil_div(height, tile_size.height)?;
        tile_count =
            usize::try_from(u64::from(tile_count_x).saturating_mul(u64::from(tile_count_y)))
                .map_err(|_| CodestreamError::SizeOverflow)?;
        tile_component_samples = 0;
        for tile_y in 0..tile_count_y {
            let tile_height = tile_axis_len(height, tile_size.height, tile_y);
            for tile_x in 0..tile_count_x {
                let tile_width = tile_axis_len(width, tile_size.width, tile_x);
                tile_component_samples = tile_component_samples.saturating_add(
                    u64::from(tile_width)
                        .saturating_mul(u64::from(tile_height))
                        .saturating_mul(component_count_u64),
                );
                if component_count == 1
                    && should_parallel_encode_decomp_subbands(tile_width, tile_height, 2)
                {
                    multitile_subband_parallel_eligible_tile_count += 1;
                }
                if should_parallel_encode_decomp_components(
                    tile_width,
                    tile_height,
                    component_count,
                    2,
                ) {
                    multitile_component_parallel_eligible_tile_count += 1;
                }
            }
        }
    }

    Ok(EncodeParallelPlan {
        parallel_feature_enabled: cfg!(feature = "parallel"),
        worker_count: parallel_worker_count(),
        width,
        height,
        bits_per_sample,
        component_count,
        decomposition_levels,
        tile_count,
        tile_component_samples,
        blocks_per_component,
        total_code_blocks,
        no_decomp_block_parallel_eligible: decomposition_levels == 0
            && component_count == 1
            && should_parallel_encode_no_decomp_blocks(width, height, blocks_per_component),
        no_decomp_component_parallel_eligible: decomposition_levels == 0
            && should_parallel_encode_no_decomp_components(
                width,
                height,
                component_count,
                blocks_per_component,
            ),
        forward_transform_component_parallel_eligible: tile_size.is_none()
            && should_parallel_encode_decomp_components(
                width,
                height,
                component_count,
                decomposition_levels,
            ),
        single_tile_decomp_subband_parallel_eligible: tile_size.is_none()
            && component_count == 1
            && should_parallel_encode_decomp_subbands(width, height, decomposition_levels),
        single_tile_decomp_component_parallel_eligible: tile_size.is_none()
            && should_parallel_encode_decomp_components(
                width,
                height,
                component_count,
                decomposition_levels,
            ),
        multitile_tile_parallel_eligible: tile_size.is_some()
            && should_parallel_encode_tile_counts(tile_count, tile_component_samples),
        multitile_subband_parallel_eligible_tile_count,
        multitile_component_parallel_eligible_tile_count,
    })
}

fn encode_code_blocks_per_component(width: u32, height: u32) -> Result<usize> {
    let code_block_cols =
        usize::try_from(ceil_div(width, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
    let code_block_rows =
        usize::try_from(ceil_div(height, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
    code_block_cols
        .checked_mul(code_block_rows)
        .ok_or(CodestreamError::SizeOverflow)
}

fn tile_axis_len(full_len: u32, tile_len: u32, tile_index: u32) -> u32 {
    let start = tile_index.saturating_mul(tile_len);
    full_len.saturating_sub(start).min(tile_len)
}

#[cfg(feature = "parallel")]
struct EncodedNoDecompBlock {
    code_block: EncodedCodeBlock,
    segments: Vec<u8>,
}

#[cfg(feature = "parallel")]
struct EncodedNoDecompComponent {
    code_blocks: Vec<EncodedCodeBlock>,
    segments: Vec<u8>,
}

fn should_parallel_encode_no_decomp_blocks(
    width: u32,
    height: u32,
    blocks_per_component: usize,
) -> bool {
    if blocks_per_component < MIN_PARALLEL_CODE_BLOCKS {
        return false;
    }

    u64::from(width).saturating_mul(u64::from(height)) >= MIN_PARALLEL_CODE_BLOCK_COEFFICIENTS
}

fn should_parallel_encode_no_decomp_components(
    width: u32,
    height: u32,
    component_count: usize,
    blocks_per_component: usize,
) -> bool {
    if component_count < 3 || blocks_per_component == 0 {
        return false;
    }

    let component_count = match u64::try_from(component_count) {
        Ok(component_count) => component_count,
        Err(_) => return false,
    };
    let blocks_per_component = match u64::try_from(blocks_per_component) {
        Ok(blocks_per_component) => blocks_per_component,
        Err(_) => return false,
    };
    if blocks_per_component.saturating_mul(component_count) < MIN_PARALLEL_CODE_BLOCKS as u64 {
        return false;
    }

    u64::from(width)
        .saturating_mul(u64::from(height))
        .saturating_mul(component_count)
        >= MIN_PARALLEL_CODE_BLOCK_COEFFICIENTS
}

#[cfg(feature = "parallel")]
fn encode_no_decomp_components_parallel(
    image_width: u32,
    image_height: u32,
    components: &[NativeNoDecompComponent],
    code_block_cols: u16,
    code_block_rows: u16,
) -> Result<Vec<EncodedNoDecompComponent>> {
    use rayon::prelude::*;

    components
        .par_iter()
        .map(|component| {
            let mut segments = Vec::new();
            let blocks_per_component = usize::from(code_block_cols)
                .checked_mul(usize::from(code_block_rows))
                .ok_or(CodestreamError::SizeOverflow)?;
            let code_blocks = if should_parallel_encode_no_decomp_blocks(
                image_width,
                image_height,
                blocks_per_component,
            ) {
                encode_no_decomp_component_blocks_parallel(
                    image_width,
                    image_height,
                    component,
                    code_block_cols,
                    code_block_rows,
                    &mut segments,
                    false,
                )?
            } else {
                let mut tier1_encode_scratch = tier1::CodeBlockEncodeScratch::new();
                encode_no_decomp_component_blocks(
                    image_width,
                    image_height,
                    component,
                    code_block_cols,
                    code_block_rows,
                    &mut segments,
                    &mut tier1_encode_scratch,
                )?
            };
            Ok(EncodedNoDecompComponent {
                code_blocks,
                segments,
            })
        })
        .collect()
}

#[cfg(feature = "parallel")]
fn encode_no_decomp_component_blocks_parallel(
    image_width: u32,
    image_height: u32,
    component: &NativeNoDecompComponent,
    code_block_cols: u16,
    code_block_rows: u16,
    segments: &mut Vec<u8>,
    preallocate_block_segments: bool,
) -> Result<Vec<EncodedCodeBlock>> {
    use rayon::prelude::*;

    let block_count = usize::from(code_block_cols)
        .checked_mul(usize::from(code_block_rows))
        .ok_or(CodestreamError::SizeOverflow)?;
    let image_width_usize =
        usize::try_from(image_width).map_err(|_| CodestreamError::SizeOverflow)?;

    let encoded_blocks = (0..block_count)
        .into_par_iter()
        .map_init(
            tier1::CodeBlockEncodeScratch::new,
            |tier1_encode_scratch, block_index| {
                encode_no_decomp_component_block_parallel(
                    image_width,
                    image_height,
                    image_width_usize,
                    component,
                    code_block_cols,
                    block_index,
                    preallocate_block_segments,
                    tier1_encode_scratch,
                )
            },
        )
        .collect::<Result<Vec<_>>>()?;

    reserve_encoded_no_decomp_block_segments(segments, &encoded_blocks)?;
    let mut code_blocks = Vec::with_capacity(encoded_blocks.len());
    for mut encoded_block in encoded_blocks {
        encoded_block.code_block.segment_offset = segments.len();
        segments.extend_from_slice(&encoded_block.segments);
        code_blocks.push(encoded_block.code_block);
    }
    Ok(code_blocks)
}

#[cfg(feature = "parallel")]
fn encode_no_decomp_component_block_parallel(
    image_width: u32,
    image_height: u32,
    image_width_usize: usize,
    component: &NativeNoDecompComponent,
    code_block_cols: u16,
    block_index: usize,
    preallocate_block_segments: bool,
    tier1_encode_scratch: &mut tier1::CodeBlockEncodeScratch,
) -> Result<EncodedNoDecompBlock> {
    let block_x_usize = block_index % usize::from(code_block_cols);
    let block_y_usize = block_index / usize::from(code_block_cols);
    let block_x = u16::try_from(block_x_usize).map_err(|_| CodestreamError::SizeOverflow)?;
    let block_y = u16::try_from(block_y_usize).map_err(|_| CodestreamError::SizeOverflow)?;
    let x0 = u32::from(block_x)
        .checked_mul(64)
        .ok_or(CodestreamError::SizeOverflow)?;
    let y0 = u32::from(block_y)
        .checked_mul(64)
        .ok_or(CodestreamError::SizeOverflow)?;
    let width =
        u16::try_from((image_width - x0).min(64)).map_err(|_| CodestreamError::SizeOverflow)?;
    let height =
        u16::try_from((image_height - y0).min(64)).map_err(|_| CodestreamError::SizeOverflow)?;
    let dimensions = tier1::CodeBlockDimensions::new(width, height).map_err(map_tier1_error)?;
    let x0_usize = usize::try_from(x0).map_err(|_| CodestreamError::SizeOverflow)?;
    let y0_usize = usize::try_from(y0).map_err(|_| CodestreamError::SizeOverflow)?;
    let source_offset = y0_usize
        .checked_mul(image_width_usize)
        .and_then(|offset| offset.checked_add(x0_usize))
        .ok_or(CodestreamError::SizeOverflow)?;
    let source = component
        .coefficients
        .get(source_offset..)
        .ok_or(CodestreamError::SizeOverflow)?;

    let mut block_segments = if preallocate_block_segments {
        let block_segment_capacity = usize::from(width)
            .checked_mul(usize::from(height))
            .ok_or(CodestreamError::SizeOverflow)?
            .min(PARALLEL_ENCODE_BLOCK_SEGMENT_CAPACITY);
        Vec::with_capacity(block_segment_capacity)
    } else {
        Vec::new()
    };
    let encoded = tier1::encode_baseline_code_block_with_strided_scratch(
        source,
        image_width_usize,
        tier1::CodeBlockEncodeSpec {
            dimensions,
            subband: tier1::Subband::LowLow,
            available_bitplanes: component.available_bitplanes,
            code_block_style: 0,
        },
        &mut block_segments,
        tier1_encode_scratch,
    )
    .map_err(map_tier1_error)?;
    Ok(EncodedNoDecompBlock {
        code_block: EncodedCodeBlock {
            x: block_x,
            y: block_y,
            width,
            height,
            included: encoded.included,
            missing_bitplanes: encoded
                .missing_bitplanes
                .checked_add(1)
                .ok_or(CodestreamError::SizeOverflow)?,
            coding_passes: encoded.pass_count,
            segment_offset: 0,
            segment_len: encoded.byte_len,
        },
        segments: block_segments,
    })
}

#[cfg(feature = "parallel")]
fn reserve_encoded_no_decomp_block_segments(
    segments: &mut Vec<u8>,
    encoded_blocks: &[EncodedNoDecompBlock],
) -> Result<()> {
    let total_len = encoded_blocks.iter().try_fold(0_usize, |total, block| {
        total
            .checked_add(block.segments.len())
            .ok_or(CodestreamError::SizeOverflow)
    })?;
    segments
        .len()
        .checked_add(total_len)
        .ok_or(CodestreamError::SizeOverflow)?;
    segments.reserve(total_len);
    Ok(())
}

#[cfg(feature = "parallel")]
fn reserve_encoded_no_decomp_component_segments(
    segments: &mut Vec<u8>,
    encoded_components: &[EncodedNoDecompComponent],
) -> Result<()> {
    let total_len = encoded_components
        .iter()
        .try_fold(0_usize, |total, component| {
            total
                .checked_add(component.segments.len())
                .ok_or(CodestreamError::SizeOverflow)
        })?;
    segments
        .len()
        .checked_add(total_len)
        .ok_or(CodestreamError::SizeOverflow)?;
    segments.reserve(total_len);
    Ok(())
}

#[cfg(feature = "parallel")]
fn push_encoded_no_decomp_component(
    mut component: EncodedNoDecompComponent,
    code_blocks: &mut Vec<Vec<EncodedCodeBlock>>,
    segments: &mut Vec<u8>,
) -> Result<()> {
    let segment_base = segments.len();
    for code_block in &mut component.code_blocks {
        code_block.segment_offset = code_block
            .segment_offset
            .checked_add(segment_base)
            .ok_or(CodestreamError::SizeOverflow)?;
    }
    segments.extend_from_slice(&component.segments);
    code_blocks.push(component.code_blocks);
    Ok(())
}

fn forward_reversible_5_3_levels(
    width: u32,
    height: u32,
    coefficients: &mut [i32],
    decomposition_levels: u8,
    message: &'static str,
) -> Result<()> {
    let mut scratch = Vec::new();
    forward_reversible_5_3_levels_with_scratch(
        width,
        height,
        coefficients,
        decomposition_levels,
        message,
        &mut scratch,
    )
}

fn forward_reversible_5_3_rgb_components(
    width: u32,
    height: u32,
    y: &mut [i32],
    db: &mut [i32],
    dr: &mut [i32],
    decomposition_levels: u8,
    message: &'static str,
) -> Result<()> {
    #[cfg(feature = "parallel")]
    {
        if should_parallel_encode_decomp_components(width, height, 3, decomposition_levels) {
            return forward_reversible_5_3_rgb_components_parallel(
                width,
                height,
                y,
                db,
                dr,
                decomposition_levels,
                message,
            );
        }
    }

    let mut transform_scratch = Vec::new();
    for component in [y, db, dr] {
        forward_reversible_5_3_levels_with_scratch(
            width,
            height,
            component,
            decomposition_levels,
            message,
            &mut transform_scratch,
        )?;
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn forward_reversible_5_3_rgb_components_parallel(
    width: u32,
    height: u32,
    y: &mut [i32],
    db: &mut [i32],
    dr: &mut [i32],
    decomposition_levels: u8,
    message: &'static str,
) -> Result<()> {
    use rayon::join;

    let transform_component = |component: &mut [i32]| {
        let mut transform_scratch = Vec::new();
        forward_reversible_5_3_levels_with_scratch(
            width,
            height,
            component,
            decomposition_levels,
            message,
            &mut transform_scratch,
        )
    };
    let (y_result, (db_result, dr_result)) = join(
        || transform_component(y),
        || join(|| transform_component(db), || transform_component(dr)),
    );
    y_result?;
    db_result?;
    dr_result
}

fn forward_reversible_5_3_levels_with_scratch(
    width: u32,
    height: u32,
    coefficients: &mut [i32],
    decomposition_levels: u8,
    message: &'static str,
    scratch: &mut Vec<i32>,
) -> Result<()> {
    if !matches!(decomposition_levels, 1 | 2) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "native decomposition encode supports exactly one or two transform levels",
        ));
    }
    let config = reversible_5_3_region_config(
        width,
        width,
        height,
        transform::ComponentSampleRange::signed(32),
    )?;
    scratch.resize(config.scratch_len(), 0);
    transform::forward_reversible_5_3_bounded(coefficients, config, scratch.as_mut_slice())
        .map_err(|_| {
            unsupported(
                None,
                Some(Marker::Cod),
                UnsupportedConstruct::Transform,
                message,
            )
        })?;
    if decomposition_levels == 2 {
        let (ll_width, ll_height) = resolution_dimensions(width, height, 1, 0)?;
        let config = reversible_5_3_region_config(
            width,
            ll_width,
            ll_height,
            transform::ComponentSampleRange::signed(32),
        )?;
        transform::forward_reversible_5_3_bounded(coefficients, config, scratch.as_mut_slice())
            .map_err(|_| {
                unsupported(
                    None,
                    Some(Marker::Cod),
                    UnsupportedConstruct::Transform,
                    message,
                )
            })?;
    }
    Ok(())
}

fn reversible_5_3_region_config(
    image_width: u32,
    region_width: u32,
    region_height: u32,
    sample_range: transform::ComponentSampleRange,
) -> Result<transform::Reversible53Config> {
    let stride = usize::try_from(image_width).map_err(|_| CodestreamError::SizeOverflow)?;
    let width = usize::try_from(region_width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(region_height).map_err(|_| CodestreamError::SizeOverflow)?;
    Ok(transform::Reversible53Config {
        width,
        height,
        stride,
        edges: transform::Reversible53Edges::from_tile_origin(0, 0, width, height),
        sample_range,
    })
}

fn encode_native_decomp_transformed(
    width: u32,
    height: u32,
    bits_per_sample: u8,
    decomposition_levels: u8,
    component_planes: &[&[i32]],
    multiple_component_transform: bool,
) -> Result<Vec<u8>> {
    if !matches!(bits_per_sample, 8 | 16) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "native decomposition encode supports unsigned 8-bit or 16-bit profiles",
        ));
    }
    if !matches!(component_planes.len(), 1 | 3) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native decomposition encode supports one or three components",
        ));
    }
    if !matches!(decomposition_levels, 1 | 2) {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "native decomposition encode supports exactly one or two levels",
        ));
    }
    let expected_samples = checked_component_sample_count(width, height)?;
    for plane in component_planes {
        if plane.len() != expected_samples {
            return Err(CodestreamError::SizeOverflow);
        }
    }

    let mut segments = Vec::new();
    let subband_specs = decomp_subband_specs(width, height, decomposition_levels)?;
    let qcd_exponents = subband_specs
        .iter()
        .map(|spec| max_component_subband_available_bitplanes(width, component_planes, *spec))
        .collect::<Result<Vec<_>>>()?;

    let mut component_subbands = Vec::with_capacity(component_planes.len());
    #[cfg(feature = "parallel")]
    {
        let preallocate_parallel_segment_buffers = bits_per_sample > 8;
        if component_planes.len() == 1
            && should_parallel_encode_decomp_subbands(width, height, decomposition_levels)
        {
            let encoded_subbands = encode_decomp_subbands_parallel(
                width,
                component_planes[0],
                &subband_specs,
                &qcd_exponents,
                preallocate_parallel_segment_buffers,
            )?;
            if preallocate_parallel_segment_buffers {
                reserve_encoded_decomp_subband_segments(&mut segments, &encoded_subbands)?;
            }
            component_subbands.push(push_encoded_decomp_subbands(
                encoded_subbands,
                &mut segments,
            )?);
        } else if should_parallel_encode_decomp_components(
            width,
            height,
            component_planes.len(),
            decomposition_levels,
        ) {
            let encoded_components = encode_decomp_components_parallel(
                width,
                component_planes,
                &subband_specs,
                &qcd_exponents,
                preallocate_parallel_segment_buffers,
            )?;
            if preallocate_parallel_segment_buffers {
                reserve_encoded_decomp_component_segments(&mut segments, &encoded_components)?;
            }
            for component in encoded_components {
                push_encoded_decomp_component(component, &mut component_subbands, &mut segments)?;
            }
        } else {
            encode_decomp_components_sequential(
                width,
                component_planes,
                &subband_specs,
                &qcd_exponents,
                &mut component_subbands,
                &mut segments,
            )?;
        }
    }
    #[cfg(not(feature = "parallel"))]
    {
        encode_decomp_components_sequential(
            width,
            component_planes,
            &subband_specs,
            &qcd_exponents,
            &mut component_subbands,
            &mut segments,
        )?;
    }

    let mut packet = Vec::with_capacity(native_decomp_packet_capacity_hint(
        &component_subbands,
        &segments,
    )?);
    write_native_decomp_packets(
        &mut packet,
        decomposition_levels,
        &component_subbands,
        &segments,
    )?;

    let mut codestream = Vec::with_capacity(native_single_tile_codestream_capacity_hint(
        packet.len(),
        component_planes.len(),
        qcd_exponents.len(),
    )?);
    write_native_part1_main_header(
        &mut codestream,
        width,
        height,
        width,
        height,
        bits_per_sample,
        u16::try_from(component_planes.len()).map_err(|_| CodestreamError::SizeOverflow)?,
        multiple_component_transform,
        decomposition_levels,
        &qcd_exponents,
    )?;
    write_tile_part(&mut codestream, 0, &packet, true)?;
    Ok(codestream)
}

fn encode_decomp_components_sequential(
    width: u32,
    component_planes: &[&[i32]],
    subband_specs: &[DecompSubbandSpec],
    qcd_exponents: &[u8],
    component_subbands: &mut Vec<Vec<NativeDecompSubband>>,
    segments: &mut Vec<u8>,
) -> Result<()> {
    let mut tier1_encode_scratch = tier1::CodeBlockEncodeScratch::new();
    for plane in component_planes {
        let mut subbands = Vec::with_capacity(subband_specs.len());
        for (spec, available_bitplanes) in subband_specs.iter().zip(qcd_exponents) {
            subbands.push(encode_decomp_subband(
                width,
                plane,
                *spec,
                *available_bitplanes,
                segments,
                &mut tier1_encode_scratch,
            )?);
        }
        component_subbands.push(subbands);
    }
    Ok(())
}

fn should_parallel_encode_decomp_subbands(
    width: u32,
    height: u32,
    decomposition_levels: u8,
) -> bool {
    if !matches!(decomposition_levels, 1 | 2) {
        return false;
    }

    u64::from(width).saturating_mul(u64::from(height)) >= MIN_PARALLEL_CODE_BLOCK_COEFFICIENTS
}

#[cfg(feature = "parallel")]
struct EncodedDecompSubband {
    subband: NativeDecompSubband,
    segments: Vec<u8>,
}

#[cfg(feature = "parallel")]
fn encode_decomp_subbands_parallel(
    width: u32,
    plane: &[i32],
    subband_specs: &[DecompSubbandSpec],
    qcd_exponents: &[u8],
    preallocate_subband_segments: bool,
) -> Result<Vec<EncodedDecompSubband>> {
    use rayon::prelude::*;

    subband_specs
        .par_iter()
        .zip(qcd_exponents.par_iter())
        .map(|(spec, available_bitplanes)| {
            let mut segments = if preallocate_subband_segments {
                Vec::with_capacity(parallel_encode_subband_segment_capacity(*spec)?)
            } else {
                Vec::new()
            };
            let mut tier1_encode_scratch = tier1::CodeBlockEncodeScratch::new();
            let subband = encode_decomp_subband(
                width,
                plane,
                *spec,
                *available_bitplanes,
                &mut segments,
                &mut tier1_encode_scratch,
            )?;
            Ok(EncodedDecompSubband { subband, segments })
        })
        .collect()
}

#[cfg(feature = "parallel")]
fn parallel_encode_subband_segment_capacity(spec: DecompSubbandSpec) -> Result<usize> {
    let width = usize::try_from(spec.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(spec.height).map_err(|_| CodestreamError::SizeOverflow)?;
    width
        .checked_mul(height)
        .map(|coefficients| coefficients.min(PARALLEL_ENCODE_SUBBAND_SEGMENT_CAPACITY))
        .ok_or(CodestreamError::SizeOverflow)
}

#[cfg(feature = "parallel")]
fn reserve_encoded_decomp_subband_segments(
    segments: &mut Vec<u8>,
    encoded_subbands: &[EncodedDecompSubband],
) -> Result<()> {
    let total_len = encoded_subbands
        .iter()
        .try_fold(0_usize, |total, subband| {
            total
                .checked_add(subband.segments.len())
                .ok_or(CodestreamError::SizeOverflow)
        })?;
    segments
        .len()
        .checked_add(total_len)
        .ok_or(CodestreamError::SizeOverflow)?;
    segments.reserve(total_len);
    Ok(())
}

#[cfg(feature = "parallel")]
fn push_encoded_decomp_subbands(
    encoded_subbands: Vec<EncodedDecompSubband>,
    segments: &mut Vec<u8>,
) -> Result<Vec<NativeDecompSubband>> {
    let mut subbands = Vec::with_capacity(encoded_subbands.len());
    for mut encoded_subband in encoded_subbands {
        let segment_base = segments.len();
        for code_block in &mut encoded_subband.subband.code_blocks {
            code_block.segment_offset = code_block
                .segment_offset
                .checked_add(segment_base)
                .ok_or(CodestreamError::SizeOverflow)?;
        }
        segments.extend_from_slice(&encoded_subband.segments);
        subbands.push(encoded_subband.subband);
    }
    Ok(subbands)
}

fn should_parallel_encode_decomp_components(
    width: u32,
    height: u32,
    component_count: usize,
    decomposition_levels: u8,
) -> bool {
    if component_count < 3 || !matches!(decomposition_levels, 1 | 2) {
        return false;
    }

    let component_count = match u64::try_from(component_count) {
        Ok(component_count) => component_count,
        Err(_) => return false,
    };
    u64::from(width)
        .saturating_mul(u64::from(height))
        .saturating_mul(component_count)
        >= MIN_PARALLEL_CODE_BLOCK_COEFFICIENTS
}

#[cfg(feature = "parallel")]
struct EncodedDecompComponent {
    subbands: Vec<NativeDecompSubband>,
    segments: Vec<u8>,
}

#[cfg(feature = "parallel")]
fn encode_decomp_components_parallel(
    width: u32,
    component_planes: &[&[i32]],
    subband_specs: &[DecompSubbandSpec],
    qcd_exponents: &[u8],
    preallocate_component_segments: bool,
) -> Result<Vec<EncodedDecompComponent>> {
    use rayon::prelude::*;

    component_planes
        .par_iter()
        .map(|plane| {
            let mut segments = if preallocate_component_segments {
                Vec::with_capacity(parallel_encode_component_segment_capacity(subband_specs)?)
            } else {
                Vec::new()
            };
            let mut tier1_encode_scratch = tier1::CodeBlockEncodeScratch::new();
            let mut subbands = Vec::with_capacity(subband_specs.len());
            for (spec, available_bitplanes) in subband_specs.iter().zip(qcd_exponents) {
                let subband = encode_decomp_subband(
                    width,
                    plane,
                    *spec,
                    *available_bitplanes,
                    &mut segments,
                    &mut tier1_encode_scratch,
                )?;
                subbands.push(subband);
            }
            Ok(EncodedDecompComponent { subbands, segments })
        })
        .collect()
}

#[cfg(feature = "parallel")]
fn parallel_encode_component_segment_capacity(
    subband_specs: &[DecompSubbandSpec],
) -> Result<usize> {
    subband_specs.iter().try_fold(0_usize, |total, spec| {
        total
            .checked_add(parallel_encode_subband_segment_capacity(*spec)?)
            .ok_or(CodestreamError::SizeOverflow)
    })
}

#[cfg(feature = "parallel")]
fn reserve_encoded_decomp_component_segments(
    segments: &mut Vec<u8>,
    encoded_components: &[EncodedDecompComponent],
) -> Result<()> {
    let total_len = encoded_components
        .iter()
        .try_fold(0_usize, |total, component| {
            total
                .checked_add(component.segments.len())
                .ok_or(CodestreamError::SizeOverflow)
        })?;
    segments
        .len()
        .checked_add(total_len)
        .ok_or(CodestreamError::SizeOverflow)?;
    segments.reserve(total_len);
    Ok(())
}

#[cfg(feature = "parallel")]
fn push_encoded_decomp_component(
    mut component: EncodedDecompComponent,
    component_subbands: &mut Vec<Vec<NativeDecompSubband>>,
    segments: &mut Vec<u8>,
) -> Result<()> {
    let segment_base = segments.len();
    for subband in &mut component.subbands {
        for code_block in &mut subband.code_blocks {
            code_block.segment_offset = code_block
                .segment_offset
                .checked_add(segment_base)
                .ok_or(CodestreamError::SizeOverflow)?;
        }
    }
    segments.extend_from_slice(&component.segments);
    component_subbands.push(component.subbands);
    Ok(())
}

fn encode_native_two_decomp_multitile_transformed(
    width: u32,
    height: u32,
    tile_size: TileSize,
    tiles: &[NativeDecompTile],
    bits_per_sample: u8,
    component_count: usize,
    multiple_component_transform: bool,
    profile_label: &'static str,
) -> Result<Vec<u8>> {
    if tiles.is_empty() {
        return Err(CodestreamError::SizeOverflow);
    }
    if !matches!(component_count, 1 | 3) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native multi-tile DWT2 encode supports one or three components",
        ));
    }
    if !matches!(bits_per_sample, 8 | 16) {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native multi-tile DWT2 encode supports unsigned 8-bit or 16-bit precision",
        ));
    }
    if multiple_component_transform != (component_count == 3) {
        return Err(invalid(
            None,
            Some(Marker::Cod),
            "native u16 multi-tile DWT2 encode MCT flag must match the component profile",
        ));
    }
    for tile in tiles {
        if tile.component_planes.len() != component_count {
            return Err(invalid(None, Some(Marker::Siz), profile_label));
        }
        let expected_samples =
            checked_component_sample_count(tile.tile_rect.width, tile.tile_rect.height)?;
        if tile
            .component_planes
            .iter()
            .any(|plane| plane.len() != expected_samples)
        {
            return Err(CodestreamError::SizeOverflow);
        }
    }

    let mut qcd_exponents = [0_u8; 7];
    for tile in tiles {
        let subband_specs = decomp_subband_specs_two(tile.tile_rect.width, tile.tile_rect.height)?;
        for (current, spec) in qcd_exponents.iter_mut().zip(&subband_specs) {
            for plane in &tile.component_planes {
                let tile_value = subband_available_bitplanes(
                    tile.tile_rect.width,
                    plane,
                    spec.x,
                    spec.y,
                    spec.width,
                    spec.height,
                )?;
                *current = (*current).max(tile_value);
            }
        }
    }

    let tile_packets =
        encode_native_two_decomp_multitile_packets(tiles, component_count, &qcd_exponents)?;
    let mut codestream = Vec::with_capacity(native_multitile_codestream_capacity_hint(
        &tile_packets,
        component_count,
        qcd_exponents.len(),
    )?);
    write_native_part1_main_header(
        &mut codestream,
        width,
        height,
        tile_size.width,
        tile_size.height,
        bits_per_sample,
        u16::try_from(component_count).map_err(|_| CodestreamError::SizeOverflow)?,
        multiple_component_transform,
        2,
        &qcd_exponents,
    )?;
    for tile_packet in tile_packets {
        write_tile_part(
            &mut codestream,
            tile_packet.tile_index,
            &tile_packet.packet,
            false,
        )?;
    }

    codestream.extend_from_slice(&[0xff, 0xd9]);
    Ok(codestream)
}

struct EncodedTilePacket {
    tile_index: u16,
    packet: Vec<u8>,
}

#[cfg_attr(not(feature = "parallel"), allow(dead_code))]
fn should_parallel_encode_tiles(tiles: &[NativeDecompTile], component_count: usize) -> bool {
    let component_count = match u64::try_from(component_count) {
        Ok(component_count) if component_count != 0 => component_count,
        _ => return false,
    };
    let coefficient_count = tiles.iter().fold(0_u64, |total, tile| {
        total.saturating_add(
            u64::from(tile.tile_rect.width)
                .saturating_mul(u64::from(tile.tile_rect.height))
                .saturating_mul(component_count),
        )
    });
    should_parallel_encode_tile_counts(tiles.len(), coefficient_count)
}

fn should_parallel_encode_tile_counts(tile_count: usize, tile_component_samples: u64) -> bool {
    tile_count >= MIN_PARALLEL_TILES && tile_component_samples >= MIN_PARALLEL_TILE_COEFFICIENTS
}

#[cfg(feature = "parallel")]
fn encode_native_two_decomp_multitile_packets(
    tiles: &[NativeDecompTile],
    component_count: usize,
    qcd_exponents: &[u8],
) -> Result<Vec<EncodedTilePacket>> {
    if !should_parallel_encode_tiles(tiles, component_count) {
        return encode_native_two_decomp_multitile_packets_sequential(
            tiles,
            component_count,
            qcd_exponents,
        );
    }

    use rayon::prelude::*;

    tiles
        .par_iter()
        .map(|tile| encode_native_two_decomp_tile_packet(tile, component_count, qcd_exponents))
        .collect()
}

#[cfg(not(feature = "parallel"))]
fn encode_native_two_decomp_multitile_packets(
    tiles: &[NativeDecompTile],
    component_count: usize,
    qcd_exponents: &[u8],
) -> Result<Vec<EncodedTilePacket>> {
    encode_native_two_decomp_multitile_packets_sequential(tiles, component_count, qcd_exponents)
}

fn encode_native_two_decomp_multitile_packets_sequential(
    tiles: &[NativeDecompTile],
    component_count: usize,
    qcd_exponents: &[u8],
) -> Result<Vec<EncodedTilePacket>> {
    let mut tile_packets = Vec::with_capacity(tiles.len());
    for tile in tiles {
        tile_packets.push(encode_native_two_decomp_tile_packet(
            tile,
            component_count,
            qcd_exponents,
        )?);
    }
    Ok(tile_packets)
}

fn encode_native_two_decomp_tile_packet(
    tile: &NativeDecompTile,
    component_count: usize,
    qcd_exponents: &[u8],
) -> Result<EncodedTilePacket> {
    let mut segments = Vec::new();
    let subband_specs = decomp_subband_specs_two(tile.tile_rect.width, tile.tile_rect.height)?;
    let mut component_subbands = Vec::with_capacity(component_count);

    #[cfg(feature = "parallel")]
    {
        if component_count == 1
            && should_parallel_encode_decomp_subbands(
                tile.tile_rect.width,
                tile.tile_rect.height,
                2,
            )
        {
            let encoded_subbands = encode_decomp_subbands_parallel(
                tile.tile_rect.width,
                &tile.component_planes[0],
                &subband_specs,
                qcd_exponents,
                true,
            )?;
            reserve_encoded_decomp_subband_segments(&mut segments, &encoded_subbands)?;
            component_subbands.push(push_encoded_decomp_subbands(
                encoded_subbands,
                &mut segments,
            )?);
        } else if should_parallel_encode_decomp_components(
            tile.tile_rect.width,
            tile.tile_rect.height,
            component_count,
            2,
        ) {
            let component_planes = tile
                .component_planes
                .iter()
                .map(Vec::as_slice)
                .collect::<Vec<_>>();
            let encoded_components = encode_decomp_components_parallel(
                tile.tile_rect.width,
                &component_planes,
                &subband_specs,
                qcd_exponents,
                true,
            )?;
            reserve_encoded_decomp_component_segments(&mut segments, &encoded_components)?;
            for component in encoded_components {
                push_encoded_decomp_component(component, &mut component_subbands, &mut segments)?;
            }
        } else {
            let component_planes = tile
                .component_planes
                .iter()
                .map(Vec::as_slice)
                .collect::<Vec<_>>();
            encode_decomp_components_sequential(
                tile.tile_rect.width,
                &component_planes,
                &subband_specs,
                qcd_exponents,
                &mut component_subbands,
                &mut segments,
            )?;
        }
    }

    #[cfg(not(feature = "parallel"))]
    {
        let component_planes = tile
            .component_planes
            .iter()
            .map(Vec::as_slice)
            .collect::<Vec<_>>();
        encode_decomp_components_sequential(
            tile.tile_rect.width,
            &component_planes,
            &subband_specs,
            qcd_exponents,
            &mut component_subbands,
            &mut segments,
        )?;
    }

    let mut packet = Vec::with_capacity(native_decomp_packet_capacity_hint(
        &component_subbands,
        &segments,
    )?);
    write_native_decomp_packets(&mut packet, 2, &component_subbands, &segments)?;
    Ok(EncodedTilePacket {
        tile_index: tile.tile_rect.tile_index,
        packet,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DecompSubbandSpec {
    index: u8,
    resolution: u8,
    kind: PacketSubbandKind,
    x: u32,
    y: u32,
    width: u32,
    height: u32,
}

fn decomp_subband_specs(
    width: u32,
    height: u32,
    decomposition_levels: u8,
) -> Result<Vec<DecompSubbandSpec>> {
    if !matches!(decomposition_levels, 1 | 2) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native decomposition encode supports exactly one or two levels",
        ));
    }
    let expected = 1usize
        .checked_add(
            usize::from(decomposition_levels)
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut specs = Vec::with_capacity(expected);
    let (ll_width, ll_height) = resolution_dimensions(width, height, decomposition_levels, 0)?;
    if ll_width == 0 || ll_height == 0 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native decomposition encode requires a non-empty lowest-resolution LL subband",
        ));
    }
    specs.push(DecompSubbandSpec {
        index: 0,
        resolution: 0,
        kind: PacketSubbandKind::LowLow,
        x: 0,
        y: 0,
        width: ll_width,
        height: ll_height,
    });

    for resolution in 1..=decomposition_levels {
        specs.extend(decomp_resolution_subband_specs(
            width,
            height,
            decomposition_levels,
            resolution,
        )?);
    }
    Ok(specs)
}

fn decomp_subband_specs_two(width: u32, height: u32) -> Result<[DecompSubbandSpec; 7]> {
    let (ll_width, ll_height) = resolution_dimensions(width, height, 2, 0)?;
    if ll_width == 0 || ll_height == 0 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native decomposition encode requires a non-empty lowest-resolution LL subband",
        ));
    }
    let level_one = decomp_resolution_subband_specs(width, height, 2, 1)?;
    let level_two = decomp_resolution_subband_specs(width, height, 2, 2)?;
    Ok([
        DecompSubbandSpec {
            index: 0,
            resolution: 0,
            kind: PacketSubbandKind::LowLow,
            x: 0,
            y: 0,
            width: ll_width,
            height: ll_height,
        },
        level_one[0],
        level_one[1],
        level_one[2],
        level_two[0],
        level_two[1],
        level_two[2],
    ])
}

fn decomp_resolution_subband_specs(
    width: u32,
    height: u32,
    decomposition_levels: u8,
    resolution: u8,
) -> Result<[DecompSubbandSpec; 3]> {
    let (low_width, low_height) =
        resolution_dimensions(width, height, decomposition_levels, resolution - 1)?;
    let (full_width, full_height) =
        resolution_dimensions(width, height, decomposition_levels, resolution)?;
    let high_width = full_width
        .checked_sub(low_width)
        .ok_or(CodestreamError::SizeOverflow)?;
    let high_height = full_height
        .checked_sub(low_height)
        .ok_or(CodestreamError::SizeOverflow)?;
    if high_width == 0 || high_height == 0 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native decomposition encode requires non-empty HL, LH, and HH subbands at every resolution",
        ));
    }
    let base_index = 1_u8
        .checked_add(
            resolution
                .checked_sub(1)
                .ok_or(CodestreamError::SizeOverflow)?
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    Ok([
        DecompSubbandSpec {
            index: base_index,
            resolution,
            kind: PacketSubbandKind::HighLow,
            x: low_width,
            y: 0,
            width: high_width,
            height: low_height,
        },
        DecompSubbandSpec {
            index: base_index
                .checked_add(1)
                .ok_or(CodestreamError::SizeOverflow)?,
            resolution,
            kind: PacketSubbandKind::LowHigh,
            x: 0,
            y: low_height,
            width: low_width,
            height: high_height,
        },
        DecompSubbandSpec {
            index: base_index
                .checked_add(2)
                .ok_or(CodestreamError::SizeOverflow)?,
            resolution,
            kind: PacketSubbandKind::HighHigh,
            x: low_width,
            y: low_height,
            width: high_width,
            height: high_height,
        },
    ])
}

fn encode_decomp_subband(
    image_width: u32,
    plane: &[i32],
    spec: DecompSubbandSpec,
    available_bitplanes: u8,
    segments: &mut Vec<u8>,
    tier1_encode_scratch: &mut tier1::CodeBlockEncodeScratch,
) -> Result<NativeDecompSubband> {
    let code_block_cols =
        u16::try_from(ceil_div(spec.width, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
    let code_block_rows =
        u16::try_from(ceil_div(spec.height, 64)?).map_err(|_| CodestreamError::SizeOverflow)?;
    let mut code_blocks = Vec::with_capacity(
        usize::from(code_block_cols)
            .checked_mul(usize::from(code_block_rows))
            .ok_or(CodestreamError::SizeOverflow)?,
    );
    let image_width_usize =
        usize::try_from(image_width).map_err(|_| CodestreamError::SizeOverflow)?;
    let subband_x = usize::try_from(spec.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let subband_y = usize::try_from(spec.y).map_err(|_| CodestreamError::SizeOverflow)?;

    for block_y in 0..code_block_rows {
        for block_x in 0..code_block_cols {
            let local_x0 = u32::from(block_x)
                .checked_mul(64)
                .ok_or(CodestreamError::SizeOverflow)?;
            let local_y0 = u32::from(block_y)
                .checked_mul(64)
                .ok_or(CodestreamError::SizeOverflow)?;
            let width = u16::try_from((spec.width - local_x0).min(64))
                .map_err(|_| CodestreamError::SizeOverflow)?;
            let height = u16::try_from((spec.height - local_y0).min(64))
                .map_err(|_| CodestreamError::SizeOverflow)?;
            let dimensions =
                tier1::CodeBlockDimensions::new(width, height).map_err(map_tier1_error)?;
            let local_x0 = usize::try_from(local_x0).map_err(|_| CodestreamError::SizeOverflow)?;
            let local_y0 = usize::try_from(local_y0).map_err(|_| CodestreamError::SizeOverflow)?;
            let source_x = subband_x
                .checked_add(local_x0)
                .ok_or(CodestreamError::SizeOverflow)?;
            let source_y = subband_y
                .checked_add(local_y0)
                .ok_or(CodestreamError::SizeOverflow)?;
            let source_offset = source_y
                .checked_mul(image_width_usize)
                .and_then(|offset| offset.checked_add(source_x))
                .ok_or(CodestreamError::SizeOverflow)?;
            let source = plane
                .get(source_offset..)
                .ok_or(CodestreamError::SizeOverflow)?;

            let segment_offset = segments.len();
            let encoded = tier1::encode_baseline_code_block_with_strided_scratch(
                source,
                image_width_usize,
                tier1::CodeBlockEncodeSpec {
                    dimensions,
                    subband: spec.kind.tier1_subband(),
                    available_bitplanes,
                    code_block_style: 0,
                },
                segments,
                tier1_encode_scratch,
            )
            .map_err(map_tier1_error)?;
            code_blocks.push(EncodedCodeBlock {
                x: block_x,
                y: block_y,
                width,
                height,
                included: encoded.included,
                missing_bitplanes: encoded
                    .missing_bitplanes
                    .checked_add(1)
                    .ok_or(CodestreamError::SizeOverflow)?,
                coding_passes: encoded.pass_count,
                segment_offset,
                segment_len: encoded.byte_len,
            });
        }
    }

    Ok(NativeDecompSubband {
        index: spec.index,
        resolution: spec.resolution,
        kind: spec.kind,
        x: spec.x,
        y: spec.y,
        width: spec.width,
        height: spec.height,
        code_block_cols,
        code_block_rows,
        available_bitplanes,
        code_blocks,
    })
}

fn subband_available_bitplanes(
    image_width: u32,
    plane: &[i32],
    x: u32,
    y: u32,
    width: u32,
    height: u32,
) -> Result<u8> {
    let image_width = usize::try_from(image_width).map_err(|_| CodestreamError::SizeOverflow)?;
    let x = usize::try_from(x).map_err(|_| CodestreamError::SizeOverflow)?;
    let y = usize::try_from(y).map_err(|_| CodestreamError::SizeOverflow)?;
    let width = usize::try_from(width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(height).map_err(|_| CodestreamError::SizeOverflow)?;
    let mut max_magnitude = 0_u32;
    for row in 0..height {
        let start = y
            .checked_add(row)
            .and_then(|row| row.checked_mul(image_width))
            .and_then(|offset| offset.checked_add(x))
            .ok_or(CodestreamError::SizeOverflow)?;
        let end = start
            .checked_add(width)
            .ok_or(CodestreamError::SizeOverflow)?;
        for coefficient in plane.get(start..end).ok_or(CodestreamError::SizeOverflow)? {
            max_magnitude = max_magnitude.max(coefficient.unsigned_abs());
        }
    }
    if max_magnitude == 0 {
        return Ok(1);
    }
    u8::try_from(32 - max_magnitude.leading_zeros()).map_err(|_| CodestreamError::SizeOverflow)
}

fn max_component_subband_available_bitplanes(
    image_width: u32,
    component_planes: &[&[i32]],
    spec: DecompSubbandSpec,
) -> Result<u8> {
    let mut max_bitplanes = None;
    for plane in component_planes {
        let bitplanes = subband_available_bitplanes(
            image_width,
            plane,
            spec.x,
            spec.y,
            spec.width,
            spec.height,
        )?;
        max_bitplanes = Some(max_bitplanes.map_or(bitplanes, |current: u8| current.max(bitplanes)));
    }
    max_bitplanes.ok_or(CodestreamError::SizeOverflow)
}

fn encode_no_decomp_component_blocks(
    image_width: u32,
    image_height: u32,
    component: &NativeNoDecompComponent,
    code_block_cols: u16,
    code_block_rows: u16,
    segments: &mut Vec<u8>,
    tier1_encode_scratch: &mut tier1::CodeBlockEncodeScratch,
) -> Result<Vec<EncodedCodeBlock>> {
    let mut code_blocks = Vec::with_capacity(
        usize::from(code_block_cols)
            .checked_mul(usize::from(code_block_rows))
            .ok_or(CodestreamError::SizeOverflow)?,
    );
    let image_width_usize =
        usize::try_from(image_width).map_err(|_| CodestreamError::SizeOverflow)?;
    for block_y in 0..code_block_rows {
        for block_x in 0..code_block_cols {
            let x0 = u32::from(block_x)
                .checked_mul(64)
                .ok_or(CodestreamError::SizeOverflow)?;
            let y0 = u32::from(block_y)
                .checked_mul(64)
                .ok_or(CodestreamError::SizeOverflow)?;
            let width = u16::try_from((image_width - x0).min(64))
                .map_err(|_| CodestreamError::SizeOverflow)?;
            let height = u16::try_from((image_height - y0).min(64))
                .map_err(|_| CodestreamError::SizeOverflow)?;
            let dimensions =
                tier1::CodeBlockDimensions::new(width, height).map_err(map_tier1_error)?;
            let x0_usize = usize::try_from(x0).map_err(|_| CodestreamError::SizeOverflow)?;
            let y0_usize = usize::try_from(y0).map_err(|_| CodestreamError::SizeOverflow)?;
            let source_offset = y0_usize
                .checked_mul(image_width_usize)
                .and_then(|offset| offset.checked_add(x0_usize))
                .ok_or(CodestreamError::SizeOverflow)?;
            let source = component
                .coefficients
                .get(source_offset..)
                .ok_or(CodestreamError::SizeOverflow)?;

            let segment_offset = segments.len();
            let encoded = tier1::encode_baseline_code_block_with_strided_scratch(
                source,
                image_width_usize,
                tier1::CodeBlockEncodeSpec {
                    dimensions,
                    subband: tier1::Subband::LowLow,
                    available_bitplanes: component.available_bitplanes,
                    code_block_style: 0,
                },
                segments,
                tier1_encode_scratch,
            )
            .map_err(map_tier1_error)?;
            code_blocks.push(EncodedCodeBlock {
                x: block_x,
                y: block_y,
                width,
                height,
                included: encoded.included,
                missing_bitplanes: encoded
                    .missing_bitplanes
                    .checked_add(1)
                    .ok_or(CodestreamError::SizeOverflow)?,
                coding_passes: encoded.pass_count,
                segment_offset,
                segment_len: encoded.byte_len,
            });
        }
    }
    Ok(code_blocks)
}

fn encode_ht_no_decomp_component_blocks(
    image_width: u32,
    image_height: u32,
    component: &NativeNoDecompComponent,
    code_block_cols: u16,
    code_block_rows: u16,
    segments: &mut Vec<u8>,
) -> Result<Vec<EncodedCodeBlock>> {
    let mut code_blocks = Vec::with_capacity(
        usize::from(code_block_cols)
            .checked_mul(usize::from(code_block_rows))
            .ok_or(CodestreamError::SizeOverflow)?,
    );
    let image_width_usize =
        usize::try_from(image_width).map_err(|_| CodestreamError::SizeOverflow)?;
    for block_y in 0..code_block_rows {
        for block_x in 0..code_block_cols {
            let x0 = u32::from(block_x)
                .checked_mul(64)
                .ok_or(CodestreamError::SizeOverflow)?;
            let y0 = u32::from(block_y)
                .checked_mul(64)
                .ok_or(CodestreamError::SizeOverflow)?;
            let width = u16::try_from((image_width - x0).min(64))
                .map_err(|_| CodestreamError::SizeOverflow)?;
            let height = u16::try_from((image_height - y0).min(64))
                .map_err(|_| CodestreamError::SizeOverflow)?;
            let source_offset = usize::try_from(y0)
                .ok()
                .and_then(|y| y.checked_mul(image_width_usize))
                .and_then(|offset| offset.checked_add(usize::try_from(x0).ok()?))
                .ok_or(CodestreamError::SizeOverflow)?;
            let source = component
                .coefficients
                .get(source_offset..)
                .ok_or(CodestreamError::SizeOverflow)?;
            let encoded = ht::encode_ht_cleanup_block(
                source,
                width,
                height,
                image_width_usize,
                component.available_bitplanes,
            )
            .map_err(map_ht_cleanup_encode_error)?;
            let segment_offset = segments.len();
            let (included, missing_bitplanes, coding_passes, segment_len) =
                if let Some(encoded) = encoded {
                    let segment_len = encoded.segment.len();
                    segments.extend_from_slice(&encoded.segment);
                    (
                        true,
                        encoded.missing_most_significant_bitplanes,
                        encoded.coding_passes,
                        segment_len,
                    )
                } else {
                    (false, 0, 0, 0)
                };
            code_blocks.push(EncodedCodeBlock {
                x: block_x,
                y: block_y,
                width,
                height,
                included,
                missing_bitplanes,
                coding_passes,
                segment_offset,
                segment_len,
            });
        }
    }
    Ok(code_blocks)
}

fn validate_grayscale_u8_encode(input: GrayscaleU8Encode<'_>) -> Result<()> {
    if input.width == 0 || input.height == 0 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native grayscale encode dimensions must be greater than zero",
        ));
    }
    if input.width > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES as u32
        || input.height > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES as u32
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let row_bytes = usize::try_from(input.width).map_err(|_| CodestreamError::SizeOverflow)?;
    if input.stride_bytes < row_bytes {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native grayscale encode stride is smaller than one image row",
        ));
    }
    let sample_count = u64::from(input.width)
        .checked_mul(u64::from(input.height))
        .ok_or(CodestreamError::SizeOverflow)?;
    if sample_count > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native grayscale encode is guarded to at most 16 Mi samples",
        ));
    }
    let last_row = usize::try_from(input.height - 1)
        .map_err(|_| CodestreamError::SizeOverflow)?
        .checked_mul(input.stride_bytes)
        .ok_or(CodestreamError::SizeOverflow)?;
    let required = last_row
        .checked_add(row_bytes)
        .ok_or(CodestreamError::SizeOverflow)?;
    require(input.samples, 0, required)
}

fn validate_grayscale_u16_le_encode(input: GrayscaleU16LeEncode<'_>) -> Result<()> {
    if input.width == 0 || input.height == 0 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native grayscale encode dimensions must be greater than zero",
        ));
    }
    if input.width > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES as u32
        || input.height > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES as u32
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let row_bytes = usize::try_from(input.width)
        .map_err(|_| CodestreamError::SizeOverflow)?
        .checked_mul(2)
        .ok_or(CodestreamError::SizeOverflow)?;
    if input.stride_bytes < row_bytes {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native grayscale encode stride is smaller than one image row",
        ));
    }
    let sample_count = u64::from(input.width)
        .checked_mul(u64::from(input.height))
        .ok_or(CodestreamError::SizeOverflow)?;
    if sample_count > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native grayscale encode is guarded to at most 16 Mi samples",
        ));
    }
    let last_row = usize::try_from(input.height - 1)
        .map_err(|_| CodestreamError::SizeOverflow)?
        .checked_mul(input.stride_bytes)
        .ok_or(CodestreamError::SizeOverflow)?;
    let required = last_row
        .checked_add(row_bytes)
        .ok_or(CodestreamError::SizeOverflow)?;
    require(input.samples, 0, required)
}

fn validate_native_multitile_dwt2_tile_size(
    width: u32,
    height: u32,
    tile_size: TileSize,
) -> Result<()> {
    if tile_size.width == 0 || tile_size.height == 0 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native multi-tile encode tile dimensions must be greater than zero",
        ));
    }
    let tile_count_x = ceil_div(width, tile_size.width)?;
    let tile_count_y = ceil_div(height, tile_size.height)?;
    let tile_count = tile_count_x
        .checked_mul(tile_count_y)
        .ok_or(CodestreamError::SizeOverflow)?;
    if tile_count <= 1 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::MultipleTiles,
            "native multi-tile encode requires a tile grid with more than one tile",
        ));
    }
    if tile_count > u32::from(u16::MAX) + 1 {
        return Err(CodestreamError::SizeOverflow);
    }

    for tile_rect in native_encode_tile_rects(width, height, tile_size)? {
        decomp_subband_specs(tile_rect.width, tile_rect.height, 2)?;
    }
    Ok(())
}

fn native_encode_tile_rects(width: u32, height: u32, tile_size: TileSize) -> Result<Vec<TileRect>> {
    let tile_count_x = ceil_div(width, tile_size.width)?;
    let tile_count_y = ceil_div(height, tile_size.height)?;
    let tile_count = tile_count_x
        .checked_mul(tile_count_y)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut tiles =
        Vec::with_capacity(usize::try_from(tile_count).map_err(|_| CodestreamError::SizeOverflow)?);
    for tile_y in 0..tile_count_y {
        for tile_x in 0..tile_count_x {
            let tile_index_u32 = tile_y
                .checked_mul(tile_count_x)
                .and_then(|value| value.checked_add(tile_x))
                .ok_or(CodestreamError::SizeOverflow)?;
            let tile_index =
                u16::try_from(tile_index_u32).map_err(|_| CodestreamError::SizeOverflow)?;
            let x = tile_x
                .checked_mul(tile_size.width)
                .ok_or(CodestreamError::SizeOverflow)?;
            let y = tile_y
                .checked_mul(tile_size.height)
                .ok_or(CodestreamError::SizeOverflow)?;
            let width = width
                .checked_sub(x)
                .ok_or(CodestreamError::SizeOverflow)?
                .min(tile_size.width);
            let height = height
                .checked_sub(y)
                .ok_or(CodestreamError::SizeOverflow)?
                .min(tile_size.height);
            tiles.push(TileRect {
                tile_index,
                tile_x,
                tile_y,
                x,
                y,
                width,
                height,
            });
        }
    }
    Ok(tiles)
}

fn validate_rgb_u8_encode(input: RgbU8Encode<'_>) -> Result<()> {
    validate_rgb_encode_shape(
        input.width,
        input.height,
        input.samples,
        input.stride_bytes,
        1,
    )
}

fn validate_rgb_u16_le_encode(input: RgbU16LeEncode<'_>) -> Result<()> {
    validate_rgb_encode_shape(
        input.width,
        input.height,
        input.samples,
        input.stride_bytes,
        2,
    )
}

fn validate_rgb_encode_shape(
    width: u32,
    height: u32,
    samples: &[u8],
    stride_bytes: usize,
    bytes_per_sample: usize,
) -> Result<()> {
    if width == 0 || height == 0 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native RGB encode dimensions must be greater than zero",
        ));
    }
    if width > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES as u32
        || height > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES as u32
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let row_bytes = usize::try_from(width)
        .map_err(|_| CodestreamError::SizeOverflow)?
        .checked_mul(3)
        .and_then(|value| value.checked_mul(bytes_per_sample))
        .ok_or(CodestreamError::SizeOverflow)?;
    if stride_bytes < row_bytes {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "native RGB encode stride is smaller than one packed image row",
        ));
    }
    checked_component_sample_count(width, height)?;
    let last_row = usize::try_from(height - 1)
        .map_err(|_| CodestreamError::SizeOverflow)?
        .checked_mul(stride_bytes)
        .ok_or(CodestreamError::SizeOverflow)?;
    let required = last_row
        .checked_add(row_bytes)
        .ok_or(CodestreamError::SizeOverflow)?;
    require(samples, 0, required)
}

fn checked_component_sample_count(width: u32, height: u32) -> Result<usize> {
    let sample_count = u64::from(width)
        .checked_mul(u64::from(height))
        .ok_or(CodestreamError::SizeOverflow)?;
    if sample_count > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "native no-decomposition encode is guarded to at most 16 Mi samples per component",
        ));
    }
    usize::try_from(sample_count).map_err(|_| CodestreamError::SizeOverflow)
}

fn level_shift_grayscale_component(
    input: GrayscaleU8Encode<'_>,
) -> Result<NativeNoDecompComponent> {
    let coefficients = level_shift_grayscale_plane(input)?;
    Ok(NativeNoDecompComponent {
        coefficients,
        available_bitplanes: 8,
    })
}

fn level_shift_grayscale_plane(input: GrayscaleU8Encode<'_>) -> Result<Vec<i32>> {
    let sample_count = checked_component_sample_count(input.width, input.height)?;
    let mut coefficients = Vec::with_capacity(sample_count);
    let width = usize::try_from(input.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(input.height).map_err(|_| CodestreamError::SizeOverflow)?;
    for y in 0..height {
        let src = y
            .checked_mul(input.stride_bytes)
            .ok_or(CodestreamError::SizeOverflow)?;
        let row_samples = checked_slice(input.samples, src, width)?;
        for sample in row_samples {
            coefficients.push(i32::from(*sample) - 128);
        }
    }
    Ok(coefficients)
}

fn level_shift_grayscale_u8_tile_plane(
    input: GrayscaleU8Encode<'_>,
    tile_rect: TileRect,
) -> Result<Vec<i32>> {
    let sample_count = checked_component_sample_count(tile_rect.width, tile_rect.height)?;
    let mut coefficients = Vec::with_capacity(sample_count);
    let tile_width = usize::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_height =
        usize::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_x = usize::try_from(tile_rect.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_y = usize::try_from(tile_rect.y).map_err(|_| CodestreamError::SizeOverflow)?;
    for row in 0..tile_height {
        let src = tile_y
            .checked_add(row)
            .and_then(|y| y.checked_mul(input.stride_bytes))
            .and_then(|offset| offset.checked_add(tile_x))
            .ok_or(CodestreamError::SizeOverflow)?;
        let row_samples = checked_slice(input.samples, src, tile_width)?;
        for sample in row_samples {
            coefficients.push(i32::from(*sample) - 128);
        }
    }
    Ok(coefficients)
}

fn level_shift_grayscale_u16_le_component(
    input: GrayscaleU16LeEncode<'_>,
) -> Result<NativeNoDecompComponent> {
    level_shift_grayscale_u16_le_component_with_precision(input, 16)
}

fn level_shift_grayscale_u16_le_component_with_precision(
    input: GrayscaleU16LeEncode<'_>,
    bits_per_sample: u8,
) -> Result<NativeNoDecompComponent> {
    validate_u16_stored_precision(bits_per_sample)?;
    let coefficients = level_shift_grayscale_u16_le_plane_with_precision(input, bits_per_sample)?;
    Ok(NativeNoDecompComponent {
        coefficients,
        available_bitplanes: bits_per_sample,
    })
}

fn level_shift_grayscale_u16_le_plane(input: GrayscaleU16LeEncode<'_>) -> Result<Vec<i32>> {
    level_shift_grayscale_u16_le_plane_with_precision(input, 16)
}

fn level_shift_grayscale_u16_le_plane_with_precision(
    input: GrayscaleU16LeEncode<'_>,
    bits_per_sample: u8,
) -> Result<Vec<i32>> {
    validate_u16_stored_precision(bits_per_sample)?;
    let level_shift = 1_i32 << (bits_per_sample - 1);
    let max_sample = (1_u32 << bits_per_sample) - 1;
    let sample_count = checked_component_sample_count(input.width, input.height)?;
    let mut coefficients = Vec::with_capacity(sample_count);
    let width = usize::try_from(input.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let row_bytes = width.checked_mul(2).ok_or(CodestreamError::SizeOverflow)?;
    for y in 0..usize::try_from(input.height).map_err(|_| CodestreamError::SizeOverflow)? {
        let src = y
            .checked_mul(input.stride_bytes)
            .ok_or(CodestreamError::SizeOverflow)?;
        let row_samples = checked_slice(input.samples, src, row_bytes)?;
        for sample in row_samples.chunks_exact(2) {
            let value = u16::from_le_bytes([sample[0], sample[1]]);
            if u32::from(value) > max_sample {
                return Err(invalid(
                    None,
                    Some(Marker::Siz),
                    "input sample exceeds declared unsigned precision",
                ));
            }
            coefficients.push(i32::from(value) - level_shift);
        }
    }
    Ok(coefficients)
}

fn validate_u16_stored_precision(bits_per_sample: u8) -> Result<()> {
    if !(9..=16).contains(&bits_per_sample) {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "little-endian u16 HTJ2K encode requires precision in 9..=16",
        ));
    }
    Ok(())
}

fn level_shift_grayscale_u16_le_tile_plane(
    input: GrayscaleU16LeEncode<'_>,
    tile_rect: TileRect,
) -> Result<Vec<i32>> {
    let sample_count = checked_component_sample_count(tile_rect.width, tile_rect.height)?;
    let mut coefficients = Vec::with_capacity(sample_count);
    let tile_width = usize::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_height =
        usize::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_x = usize::try_from(tile_rect.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_y = usize::try_from(tile_rect.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let row_bytes = tile_width
        .checked_mul(2)
        .ok_or(CodestreamError::SizeOverflow)?;
    let x_byte_offset = tile_x.checked_mul(2).ok_or(CodestreamError::SizeOverflow)?;
    for row in 0..tile_height {
        let src = tile_y
            .checked_add(row)
            .and_then(|y| y.checked_mul(input.stride_bytes))
            .and_then(|offset| offset.checked_add(x_byte_offset))
            .ok_or(CodestreamError::SizeOverflow)?;
        let row_samples = checked_slice(input.samples, src, row_bytes)?;
        for sample in row_samples.chunks_exact(2) {
            let value = u16::from_le_bytes([sample[0], sample[1]]);
            coefficients.push(i32::from(value) - 32768);
        }
    }
    Ok(coefficients)
}

fn forward_rct_rgb_components(input: RgbU8Encode<'_>) -> Result<[NativeNoDecompComponent; 3]> {
    let sample_count = checked_component_sample_count(input.width, input.height)?;
    let mut y_plane = alloc::vec![0_i32; sample_count];
    let mut db_plane = alloc::vec![0_i32; sample_count];
    let mut dr_plane = alloc::vec![0_i32; sample_count];
    let width = usize::try_from(input.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(input.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let row_bytes = width.checked_mul(3).ok_or(CodestreamError::SizeOverflow)?;
    for row in 0..height {
        let src = row
            .checked_mul(input.stride_bytes)
            .ok_or(CodestreamError::SizeOverflow)?;
        let row_samples = checked_slice(input.samples, src, row_bytes)?;
        let dst = row
            .checked_mul(width)
            .ok_or(CodestreamError::SizeOverflow)?;
        let dst_end = dst
            .checked_add(width)
            .ok_or(CodestreamError::SizeOverflow)?;
        fill_forward_rct_u8_row(
            row_samples,
            &mut y_plane[dst..dst_end],
            &mut db_plane[dst..dst_end],
            &mut dr_plane[dst..dst_end],
        );
    }
    Ok([
        NativeNoDecompComponent {
            coefficients: y_plane,
            available_bitplanes: 8,
        },
        NativeNoDecompComponent {
            coefficients: db_plane,
            available_bitplanes: 8,
        },
        NativeNoDecompComponent {
            coefficients: dr_plane,
            available_bitplanes: 8,
        },
    ])
}

fn level_shift_rgb_u8_components(input: RgbU8Encode<'_>) -> Result<[NativeNoDecompComponent; 3]> {
    let sample_count = checked_component_sample_count(input.width, input.height)?;
    let mut planes = [
        Vec::with_capacity(sample_count),
        Vec::with_capacity(sample_count),
        Vec::with_capacity(sample_count),
    ];
    let width = usize::try_from(input.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(input.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let row_bytes = width.checked_mul(3).ok_or(CodestreamError::SizeOverflow)?;
    for row in 0..height {
        let offset = row
            .checked_mul(input.stride_bytes)
            .ok_or(CodestreamError::SizeOverflow)?;
        for pixel in checked_slice(input.samples, offset, row_bytes)?.chunks_exact(3) {
            planes[0].push(i32::from(pixel[0]) - 128);
            planes[1].push(i32::from(pixel[1]) - 128);
            planes[2].push(i32::from(pixel[2]) - 128);
        }
    }
    Ok(planes.map(|coefficients| NativeNoDecompComponent {
        coefficients,
        available_bitplanes: 8,
    }))
}

fn forward_rct_rgb_u8_tile_components(
    input: RgbU8Encode<'_>,
    tile_rect: TileRect,
) -> Result<[NativeNoDecompComponent; 3]> {
    let sample_count = checked_component_sample_count(tile_rect.width, tile_rect.height)?;
    let mut y_plane = alloc::vec![0_i32; sample_count];
    let mut db_plane = alloc::vec![0_i32; sample_count];
    let mut dr_plane = alloc::vec![0_i32; sample_count];
    let tile_width = usize::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_height =
        usize::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_x = usize::try_from(tile_rect.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_y = usize::try_from(tile_rect.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let row_bytes = tile_width
        .checked_mul(3)
        .ok_or(CodestreamError::SizeOverflow)?;
    let x_byte_offset = tile_x.checked_mul(3).ok_or(CodestreamError::SizeOverflow)?;
    for row in 0..tile_height {
        let src = tile_y
            .checked_add(row)
            .and_then(|y| y.checked_mul(input.stride_bytes))
            .and_then(|offset| offset.checked_add(x_byte_offset))
            .ok_or(CodestreamError::SizeOverflow)?;
        let row_samples = checked_slice(input.samples, src, row_bytes)?;
        let dst = row
            .checked_mul(tile_width)
            .ok_or(CodestreamError::SizeOverflow)?;
        let dst_end = dst
            .checked_add(tile_width)
            .ok_or(CodestreamError::SizeOverflow)?;
        fill_forward_rct_u8_row(
            row_samples,
            &mut y_plane[dst..dst_end],
            &mut db_plane[dst..dst_end],
            &mut dr_plane[dst..dst_end],
        );
    }
    Ok([
        NativeNoDecompComponent {
            coefficients: y_plane,
            available_bitplanes: 8,
        },
        NativeNoDecompComponent {
            coefficients: db_plane,
            available_bitplanes: 8,
        },
        NativeNoDecompComponent {
            coefficients: dr_plane,
            available_bitplanes: 8,
        },
    ])
}

fn forward_rct_rgb_u16_le_components(
    input: RgbU16LeEncode<'_>,
) -> Result<[NativeNoDecompComponent; 3]> {
    let sample_count = checked_component_sample_count(input.width, input.height)?;
    let mut y_plane = alloc::vec![0_i32; sample_count];
    let mut db_plane = alloc::vec![0_i32; sample_count];
    let mut dr_plane = alloc::vec![0_i32; sample_count];
    let width = usize::try_from(input.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(input.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let row_bytes = width.checked_mul(6).ok_or(CodestreamError::SizeOverflow)?;
    for row in 0..height {
        let src = row
            .checked_mul(input.stride_bytes)
            .ok_or(CodestreamError::SizeOverflow)?;
        let row_samples = checked_slice(input.samples, src, row_bytes)?;
        let dst = row
            .checked_mul(width)
            .ok_or(CodestreamError::SizeOverflow)?;
        let dst_end = dst
            .checked_add(width)
            .ok_or(CodestreamError::SizeOverflow)?;
        fill_forward_rct_u16_le_row(
            row_samples,
            &mut y_plane[dst..dst_end],
            &mut db_plane[dst..dst_end],
            &mut dr_plane[dst..dst_end],
        );
    }
    Ok([
        NativeNoDecompComponent {
            coefficients: y_plane,
            available_bitplanes: 16,
        },
        NativeNoDecompComponent {
            coefficients: db_plane,
            available_bitplanes: 16,
        },
        NativeNoDecompComponent {
            coefficients: dr_plane,
            available_bitplanes: 16,
        },
    ])
}

fn level_shift_rgb_u16_le_components_with_precision(
    input: RgbU16LeEncode<'_>,
    bits_per_sample: u8,
) -> Result<[NativeNoDecompComponent; 3]> {
    validate_u16_stored_precision(bits_per_sample)?;
    let level_shift = 1_i32 << (bits_per_sample - 1);
    let max_sample = (1_u32 << bits_per_sample) - 1;
    let sample_count = checked_component_sample_count(input.width, input.height)?;
    let mut planes = [
        Vec::with_capacity(sample_count),
        Vec::with_capacity(sample_count),
        Vec::with_capacity(sample_count),
    ];
    let width = usize::try_from(input.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(input.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let row_bytes = width.checked_mul(6).ok_or(CodestreamError::SizeOverflow)?;
    for row in 0..height {
        let offset = row
            .checked_mul(input.stride_bytes)
            .ok_or(CodestreamError::SizeOverflow)?;
        for pixel in checked_slice(input.samples, offset, row_bytes)?.chunks_exact(6) {
            for (component, plane) in planes.iter_mut().enumerate() {
                let byte = component * 2;
                let value = u16::from_le_bytes([pixel[byte], pixel[byte + 1]]);
                if u32::from(value) > max_sample {
                    return Err(invalid(
                        None,
                        Some(Marker::Siz),
                        "input sample exceeds declared unsigned precision",
                    ));
                }
                plane.push(i32::from(value) - level_shift);
            }
        }
    }
    Ok(planes.map(|coefficients| NativeNoDecompComponent {
        coefficients,
        available_bitplanes: bits_per_sample,
    }))
}

fn forward_rct_rgb_u16_le_tile_components(
    input: RgbU16LeEncode<'_>,
    tile_rect: TileRect,
) -> Result<[NativeNoDecompComponent; 3]> {
    let sample_count = checked_component_sample_count(tile_rect.width, tile_rect.height)?;
    let mut y_plane = alloc::vec![0_i32; sample_count];
    let mut db_plane = alloc::vec![0_i32; sample_count];
    let mut dr_plane = alloc::vec![0_i32; sample_count];
    let tile_width = usize::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_height =
        usize::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_x = usize::try_from(tile_rect.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_y = usize::try_from(tile_rect.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let row_bytes = tile_width
        .checked_mul(6)
        .ok_or(CodestreamError::SizeOverflow)?;
    let x_byte_offset = tile_x.checked_mul(6).ok_or(CodestreamError::SizeOverflow)?;
    for row in 0..tile_height {
        let src = tile_y
            .checked_add(row)
            .and_then(|y| y.checked_mul(input.stride_bytes))
            .and_then(|offset| offset.checked_add(x_byte_offset))
            .ok_or(CodestreamError::SizeOverflow)?;
        let row_samples = checked_slice(input.samples, src, row_bytes)?;
        let dst = row
            .checked_mul(tile_width)
            .ok_or(CodestreamError::SizeOverflow)?;
        let dst_end = dst
            .checked_add(tile_width)
            .ok_or(CodestreamError::SizeOverflow)?;
        fill_forward_rct_u16_le_row(
            row_samples,
            &mut y_plane[dst..dst_end],
            &mut db_plane[dst..dst_end],
            &mut dr_plane[dst..dst_end],
        );
    }
    Ok([
        NativeNoDecompComponent {
            coefficients: y_plane,
            available_bitplanes: 16,
        },
        NativeNoDecompComponent {
            coefficients: db_plane,
            available_bitplanes: 16,
        },
        NativeNoDecompComponent {
            coefficients: dr_plane,
            available_bitplanes: 16,
        },
    ])
}

fn fill_forward_rct_u8_row(
    row_samples: &[u8],
    y_plane: &mut [i32],
    db_plane: &mut [i32],
    dr_plane: &mut [i32],
) {
    for (((y, db), dr), pixel) in y_plane
        .iter_mut()
        .zip(db_plane)
        .zip(dr_plane)
        .zip(row_samples.chunks_exact(3))
    {
        let red = i32::from(pixel[0]) - 128;
        let green = i32::from(pixel[1]) - 128;
        let blue = i32::from(pixel[2]) - 128;
        *y = forward_rct_luma(red, green, blue);
        *db = blue - green;
        *dr = red - green;
    }
}

fn fill_forward_rct_u16_le_row(
    row_samples: &[u8],
    y_plane: &mut [i32],
    db_plane: &mut [i32],
    dr_plane: &mut [i32],
) {
    for (((y, db), dr), pixel) in y_plane
        .iter_mut()
        .zip(db_plane)
        .zip(dr_plane)
        .zip(row_samples.chunks_exact(6))
    {
        let red = i32::from(u16::from_le_bytes([pixel[0], pixel[1]])) - 32768;
        let green = i32::from(u16::from_le_bytes([pixel[2], pixel[3]])) - 32768;
        let blue = i32::from(u16::from_le_bytes([pixel[4], pixel[5]])) - 32768;
        *y = forward_rct_luma(red, green, blue);
        *db = blue - green;
        *dr = red - green;
    }
}

fn forward_rct_luma(red: i32, green: i32, blue: i32) -> i32 {
    (red + (green << 1) + blue) >> 2
}

fn write_native_part1_main_header(
    output: &mut Vec<u8>,
    width: u32,
    height: u32,
    tile_width: u32,
    tile_height: u32,
    bits_per_sample: u8,
    components: u16,
    multiple_component_transform: bool,
    decomposition_levels: u8,
    qcd_exponents: &[u8],
) -> Result<()> {
    write_native_main_header(
        output,
        width,
        height,
        tile_width,
        tile_height,
        bits_per_sample,
        components,
        multiple_component_transform,
        decomposition_levels,
        qcd_exponents,
        false,
    )
}

fn write_native_ht_main_header(
    output: &mut Vec<u8>,
    width: u32,
    height: u32,
    bits_per_sample: u8,
    components: u16,
    multiple_component_transform: bool,
) -> Result<()> {
    write_native_main_header(
        output,
        width,
        height,
        width,
        height,
        bits_per_sample,
        components,
        multiple_component_transform,
        0,
        &[bits_per_sample],
        true,
    )
}

#[allow(clippy::too_many_arguments)]
fn write_native_main_header(
    output: &mut Vec<u8>,
    width: u32,
    height: u32,
    tile_width: u32,
    tile_height: u32,
    bits_per_sample: u8,
    components: u16,
    multiple_component_transform: bool,
    decomposition_levels: u8,
    qcd_exponents: &[u8],
    ht_block_coding: bool,
) -> Result<()> {
    let expected_subbands = 1usize
        .checked_add(
            usize::from(decomposition_levels)
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    if qcd_exponents.len() != expected_subbands {
        return Err(CodestreamError::SizeOverflow);
    }
    let siz_len = 38_u16
        .checked_add(
            components
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    output.extend_from_slice(&[0xff, 0x4f]);
    output.extend_from_slice(&[0xff, 0x51]);
    output.extend_from_slice(&siz_len.to_be_bytes());
    output.extend_from_slice(&if ht_block_coding { 0x4000_u16 } else { 0 }.to_be_bytes());
    output.extend_from_slice(&width.to_be_bytes());
    output.extend_from_slice(&height.to_be_bytes());
    output.extend_from_slice(&0_u32.to_be_bytes());
    output.extend_from_slice(&0_u32.to_be_bytes());
    output.extend_from_slice(&tile_width.to_be_bytes());
    output.extend_from_slice(&tile_height.to_be_bytes());
    output.extend_from_slice(&0_u32.to_be_bytes());
    output.extend_from_slice(&0_u32.to_be_bytes());
    output.extend_from_slice(&components.to_be_bytes());
    let sample_marker = bits_per_sample
        .checked_sub(1)
        .ok_or(CodestreamError::SizeOverflow)?;
    for _ in 0..components {
        output.extend_from_slice(&[sample_marker, 1, 1]);
    }
    if ht_block_coding {
        let magnitude_bound = qcd_exponents
            .iter()
            .copied()
            .max()
            .ok_or(CodestreamError::SizeOverflow)?;
        let ccap15 = if magnitude_bound <= 8 {
            0_u16
        } else if magnitude_bound < 28 {
            u16::from(magnitude_bound - 8)
        } else {
            13_u16 + u16::from(magnitude_bound >> 2)
        };
        output.extend_from_slice(&[0xff, 0x50]);
        output.extend_from_slice(&8_u16.to_be_bytes());
        output.extend_from_slice(&0x0002_0000_u32.to_be_bytes());
        output.extend_from_slice(&ccap15.to_be_bytes());
    }
    output.extend_from_slice(&[0xff, 0x52]);
    output.extend_from_slice(&12_u16.to_be_bytes());
    output.extend_from_slice(&[0, 0]);
    output.extend_from_slice(&1_u16.to_be_bytes());
    output.extend_from_slice(&[
        u8::from(multiple_component_transform),
        decomposition_levels,
        4,
        4,
        if ht_block_coding { 0x40 } else { 0 },
        1,
    ]);
    output.extend_from_slice(&[0xff, 0x5c]);
    let qcd_len = u16::try_from(
        3usize
            .checked_add(qcd_exponents.len())
            .ok_or(CodestreamError::SizeOverflow)?,
    )
    .map_err(|_| CodestreamError::SizeOverflow)?;
    output.extend_from_slice(&qcd_len.to_be_bytes());
    output.push(if ht_block_coding { 0x20 } else { 0x40 });
    for exponent in qcd_exponents {
        output.push(
            exponent
                .checked_shl(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        );
    }
    Ok(())
}

fn write_tile_part(
    output: &mut Vec<u8>,
    tile_index: u16,
    packet: &[u8],
    final_eoc: bool,
) -> Result<()> {
    let sot_offset = output.len();
    output.extend_from_slice(&[0xff, 0x90]);
    output.extend_from_slice(&10_u16.to_be_bytes());
    output.extend_from_slice(&tile_index.to_be_bytes());
    output.extend_from_slice(&0_u32.to_be_bytes());
    output.push(0);
    output.push(1);
    output.extend_from_slice(&[0xff, 0x93]);
    output.extend_from_slice(packet);
    let tile_part_len = u32::try_from(
        output
            .len()
            .checked_sub(sot_offset)
            .ok_or(CodestreamError::SizeOverflow)?,
    )
    .map_err(|_| CodestreamError::SizeOverflow)?;
    output[sot_offset + 6..sot_offset + 10].copy_from_slice(&tile_part_len.to_be_bytes());
    if final_eoc {
        output.extend_from_slice(&[0xff, 0xd9]);
    }
    Ok(())
}

fn write_native_no_decomp_packets(
    output: &mut Vec<u8>,
    code_block_cols: u16,
    code_block_rows: u16,
    component_code_blocks: &[Vec<EncodedCodeBlock>],
    segments: &[u8],
) -> Result<()> {
    for code_blocks in component_code_blocks {
        let mut writer = PacketBitWriter::new();
        let has_contribution = code_blocks.iter().any(|block| block.included);
        writer.write_bit(u32::from(has_contribution))?;
        if has_contribution {
            write_component_packet_header(
                &mut writer,
                code_block_cols,
                code_block_rows,
                code_blocks,
            )?;
        }
        writer.align();
        output.extend_from_slice(writer.bytes());
        for block in code_blocks.iter().filter(|block| block.included) {
            let segment = checked_slice(segments, block.segment_offset, block.segment_len)?;
            output.extend_from_slice(segment);
        }
    }
    Ok(())
}

fn native_no_decomp_packet_capacity_hint(
    component_code_blocks: &[Vec<EncodedCodeBlock>],
    segments: &[u8],
) -> Result<usize> {
    const PACKET_HEADER_BYTES_HINT: usize = 64;

    let packet_header_hint = component_code_blocks
        .len()
        .checked_mul(PACKET_HEADER_BYTES_HINT)
        .ok_or(CodestreamError::SizeOverflow)?;
    segments
        .len()
        .checked_add(packet_header_hint)
        .ok_or(CodestreamError::SizeOverflow)
}

fn native_decomp_packet_capacity_hint(
    component_subbands: &[Vec<NativeDecompSubband>],
    segments: &[u8],
) -> Result<usize> {
    const PACKET_HEADER_BYTES_HINT: usize = 64;

    let packet_count =
        component_subbands
            .iter()
            .map(Vec::len)
            .try_fold(0_usize, |total, subbands| {
                total
                    .checked_add(subbands)
                    .ok_or(CodestreamError::SizeOverflow)
            })?;
    let packet_header_hint = packet_count
        .checked_mul(PACKET_HEADER_BYTES_HINT)
        .ok_or(CodestreamError::SizeOverflow)?;
    segments
        .len()
        .checked_add(packet_header_hint)
        .ok_or(CodestreamError::SizeOverflow)
}

fn native_single_tile_codestream_capacity_hint(
    packet_len: usize,
    component_count: usize,
    qcd_exponent_count: usize,
) -> Result<usize> {
    const TILE_PART_OVERHEAD: usize = 16;
    const EOC_BYTES: usize = 2;

    native_main_header_capacity_hint(component_count, qcd_exponent_count)?
        .checked_add(TILE_PART_OVERHEAD)
        .and_then(|capacity| capacity.checked_add(packet_len))
        .and_then(|capacity| capacity.checked_add(EOC_BYTES))
        .ok_or(CodestreamError::SizeOverflow)
}

fn native_multitile_codestream_capacity_hint(
    tile_packets: &[EncodedTilePacket],
    component_count: usize,
    qcd_exponent_count: usize,
) -> Result<usize> {
    const TILE_PART_OVERHEAD: usize = 16;
    const EOC_BYTES: usize = 2;

    let packet_bytes = tile_packets.iter().try_fold(0_usize, |total, packet| {
        total
            .checked_add(packet.packet.len())
            .ok_or(CodestreamError::SizeOverflow)
    })?;
    let tile_overhead = tile_packets
        .len()
        .checked_mul(TILE_PART_OVERHEAD)
        .ok_or(CodestreamError::SizeOverflow)?;
    native_main_header_capacity_hint(component_count, qcd_exponent_count)?
        .checked_add(packet_bytes)
        .and_then(|capacity| capacity.checked_add(tile_overhead))
        .and_then(|capacity| capacity.checked_add(EOC_BYTES))
        .ok_or(CodestreamError::SizeOverflow)
}

fn native_main_header_capacity_hint(
    component_count: usize,
    qcd_exponent_count: usize,
) -> Result<usize> {
    const BASE_MAIN_HEADER_BYTES: usize = 64;

    let component_bytes = component_count
        .checked_mul(3)
        .ok_or(CodestreamError::SizeOverflow)?;
    BASE_MAIN_HEADER_BYTES
        .checked_add(component_bytes)
        .and_then(|capacity| capacity.checked_add(qcd_exponent_count))
        .ok_or(CodestreamError::SizeOverflow)
}

fn write_native_decomp_packets(
    output: &mut Vec<u8>,
    decomposition_levels: u8,
    component_subbands: &[Vec<NativeDecompSubband>],
    segments: &[u8],
) -> Result<()> {
    for resolution in 0..=decomposition_levels {
        for subbands in component_subbands {
            let packet_subbands = subbands
                .iter()
                .filter(|subband| subband.resolution == resolution)
                .collect::<Vec<_>>();
            let mut writer = PacketBitWriter::new();
            let has_contribution = packet_subbands
                .iter()
                .any(|subband| subband.code_blocks.iter().any(|block| block.included));
            writer.write_bit(u32::from(has_contribution))?;
            if has_contribution {
                for subband in &packet_subbands {
                    write_component_packet_header(
                        &mut writer,
                        subband.code_block_cols,
                        subband.code_block_rows,
                        &subband.code_blocks,
                    )?;
                }
            }
            writer.align();
            output.extend_from_slice(writer.bytes());
            for subband in packet_subbands {
                for block in subband.code_blocks.iter().filter(|block| block.included) {
                    let segment = checked_slice(segments, block.segment_offset, block.segment_len)?;
                    output.extend_from_slice(segment);
                }
            }
        }
    }
    Ok(())
}

fn write_component_packet_header(
    writer: &mut PacketBitWriter,
    code_block_cols: u16,
    code_block_rows: u16,
    code_blocks: &[EncodedCodeBlock],
) -> Result<()> {
    let mut inclusion = EncTagTree::new(
        code_block_cols,
        code_block_rows,
        code_blocks
            .iter()
            .map(|block| if block.included { 0 } else { 1 }),
    )?;
    let mut missing = EncTagTree::new(
        code_block_cols,
        code_block_rows,
        code_blocks
            .iter()
            .map(|block| u32::from(block.missing_bitplanes)),
    )?;
    for block in code_blocks {
        let included = block.included;
        inclusion.encode(writer, block.x, block.y, 1)?;
        if !included {
            continue;
        }
        missing.encode(writer, block.x, block.y, u32::MAX)?;
        write_coding_pass_count(writer, block.coding_passes)?;
        let length_bits = write_lblock_and_length_bits(writer, block)?;
        writer.write_bits(
            u32::try_from(block.segment_len).map_err(|_| CodestreamError::SizeOverflow)?,
            length_bits,
        )?;
    }
    Ok(())
}

fn write_lblock_and_length_bits(
    writer: &mut PacketBitWriter,
    block: &EncodedCodeBlock,
) -> Result<u8> {
    let pass_bits = u8::try_from(u32::from(block.coding_passes).ilog2())
        .map_err(|_| CodestreamError::SizeOverflow)?;
    let mut lblock = 3_u8;
    while u128::try_from(block.segment_len).map_err(|_| CodestreamError::SizeOverflow)?
        >= (1_u128 << u32::from(lblock + pass_bits))
    {
        writer.write_bit(1)?;
        lblock = lblock.checked_add(1).ok_or(CodestreamError::SizeOverflow)?;
    }
    writer.write_bit(0)?;
    lblock
        .checked_add(pass_bits)
        .ok_or(CodestreamError::SizeOverflow)
}

fn write_coding_pass_count(writer: &mut PacketBitWriter, coding_passes: u16) -> Result<()> {
    match coding_passes {
        1 => writer.write_bit(0),
        2 => writer.write_bits(0b10, 2),
        3 => writer.write_bits(0b1100, 4),
        4 => writer.write_bits(0b1101, 4),
        5 => writer.write_bits(0b1110, 4),
        6..=36 => {
            writer.write_bits(0b1111, 4)?;
            writer.write_bits(u32::from(coding_passes - 6), 5)
        }
        37..=164 => {
            writer.write_bits(0x1ff, 9)?;
            writer.write_bits(u32::from(coding_passes - 37), 7)
        }
        _ => Err(CodestreamError::SizeOverflow),
    }
}

/// Return explicit unsupported metadata for the current milestone subset.
pub fn unsupported_construct(codestream: &Codestream) -> Option<(UnsupportedConstruct, String)> {
    if codestream.kind == CodestreamKind::Htj2k {
        return ht_unsupported_construct(codestream);
    }

    if let Some((marker, detail)) = unsupported_part1_profile_marker(codestream) {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            detail_for_marker(marker, detail),
        ));
    }

    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.bits_per_sample != 8 || component.signed)
    {
        return Some((
            UnsupportedConstruct::SamplePrecision,
            "only unsigned 8-bit component samples are in the current native decode subset".into(),
        ));
    }

    if !matches!(codestream.siz.component_count(), 1 | 3) {
        return Some((
            UnsupportedConstruct::ComponentCount,
            "only grayscale and RGB codestreams are in the current native baseline decode subset"
                .into(),
        ));
    }

    if codestream
        .siz
        .components
        .iter()
        .any(|component| component.horizontal_separation != 1 || component.vertical_separation != 1)
    {
        return Some((
            UnsupportedConstruct::ComponentSampling,
            "subsampled component-grid decode is not implemented for this profile".into(),
        ));
    }

    if codestream.siz.tile_count_x().ok()? > 1 || codestream.siz.tile_count_y().ok()? > 1 {
        return Some((
            UnsupportedConstruct::MultipleTiles,
            "arbitrary multi-tile codestreams outside the admitted grayscale profiles remain unsupported"
                .into(),
        ));
    }

    let component_samples = native_part1_profile_component_samples(codestream)?;
    if component_samples == 0 || component_samples > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Some((
            UnsupportedConstruct::PacketDecode,
            "native Part 1 profile decode is guarded to at most 16 Mi component samples".into(),
        ));
    }

    let Some(coding_style) = codestream.coding_style else {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            "COD marker is required before decode support can be classified".into(),
        ));
    };

    if coding_style.entropy_coder != EntropyCoder::ClassicTier1 {
        return Some((
            UnsupportedConstruct::EntropyCoder,
            "only classic tier-1 coding is in the initial Part 1 baseline subset".into(),
        ));
    }

    if !default_precinct_progression_order_supported(coding_style.progression_order) {
        return Some((
            UnsupportedConstruct::ProgressionOrder,
            "only LRCP/RLCP progression is in the initial default-precinct decode support subset"
                .into(),
        ));
    }

    if coding_style.transform != WaveletTransform::Reversible53 {
        return Some((
            UnsupportedConstruct::WaveletTransform,
            "irreversible 9/7 decode is not implemented for this profile".into(),
        ));
    }

    if !default_precinct_layer_count_supported(coding_style.layers) {
        return Some((
            UnsupportedConstruct::PacketDecode,
            "COD marker must declare at least one quality layer for default-precinct decode".into(),
        ));
    }

    if coding_style.sop_markers || coding_style.eph_markers || coding_style.precincts_declared {
        return Some((
            UnsupportedConstruct::MarkerSegment,
            "SOP markers, EPH markers, and explicit precinct tables are outside the initial baseline subset"
                .into(),
        ));
    }

    if !classic_tier1_code_block_style_supported(coding_style.code_block_style) {
        return Some((
            UnsupportedConstruct::Tier1Decode,
            "code-block style bits other than BYPASS, RESET, TERMALL, VSC, PTERM, and SEGSYM are not implemented"
                .into(),
        ));
    }

    if codestream.siz.component_count() == 3 && !coding_style.multiple_component_transform {
        return Some((
            UnsupportedConstruct::Transform,
            "three-component native Part 1 profile decode requires COD.mct=1 reversible color transform"
                .into(),
        ));
    }

    match codestream.tiles.as_slice() {
        [tile]
            if tile.tile_part_index == 0
                && !matches!(tile.tile_part_count, Some(count) if count != 1) => {}
        [] => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                "at least one tile-part payload is required before decode support can be enabled"
                    .into(),
            ));
        }
        [_] => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                "native Part 1 profile decode requires a single first tile-part payload".into(),
            ));
        }
        _ => {
            return Some((
                UnsupportedConstruct::MarkerSegment,
                "native Part 1 profile decode requires exactly one tile-part".into(),
            ));
        }
    }

    None
}

fn unsupported_part1_profile_marker(codestream: &Codestream) -> Option<(Marker, &'static str)> {
    codestream.markers.iter().find_map(|segment| {
        let detail = match segment.marker {
            Marker::Soc
            | Marker::Sot
            | Marker::Sod
            | Marker::Eoc
            | Marker::Siz
            | Marker::Cod
            | Marker::Qcd
            | Marker::Tlm
            | Marker::Plm
            | Marker::Plt
            | Marker::Com => return None,
            Marker::Coc => "COC component coding style overrides are not consumed by the profile decoder",
            Marker::Qcc => "QCC component quantization overrides are not consumed by the profile decoder",
            Marker::Poc => "POC progression order changes are not consumed by the profile packet walker",
            Marker::Rgn => "RGN region-of-interest scaling is not implemented in native profile decode",
            Marker::Ppm => "PPM packed packet headers are not consumed by the profile packet walker",
            Marker::Ppt => "PPT packed packet headers are not consumed by the profile packet walker",
            Marker::Sop | Marker::Eph => {
                "SOP/EPH packet markers are not consumed by the profile packet walker"
            }
            Marker::Cap => "CAP markers identify HTJ2K/extended capability codestreams outside Part 1 profile decode",
            Marker::Unknown(code) if Marker::Unknown(code).is_reserved_parameterless() => return None,
            Marker::Unknown(_) => "unknown marker segments are outside the admitted native profile",
        };
        Some((segment.marker, detail))
    })
}

fn detail_for_marker(marker: Marker, detail: &'static str) -> String {
    alloc::format!("{marker} marker is unsupported in native Part 1 profile decode: {detail}")
}

fn default_precinct_progression_order_supported(order: ProgressionOrder) -> bool {
    matches!(order, ProgressionOrder::Lrcp | ProgressionOrder::Rlcp)
}

fn default_precinct_layer_count_supported(layers: u16) -> bool {
    layers > 0
}

fn classic_tier1_code_block_style_supported(style: u8) -> bool {
    tier1::CodeBlockStyle::from_bits(style)
        .validate_baseline()
        .is_ok()
}

