    #[test]
    fn synthesis_crossover_is_dependency_and_workspace_aware() {
        let route_for = |width: u32, height: u32| {
            let plan = transform::plan_window_synthesis(
                4096,
                4096,
                2,
                transform::AxisAlignedRegion {
                    x: (4096 - width) / 2,
                    y: (4096 - height) / 2,
                    width,
                    height,
                },
                transform::WaveletTransform::Reversible53,
            )
            .unwrap();
            resolve_synthesis_crossover(
                &plan,
                coding_style(WaveletTransform::Reversible53),
                4096,
                4096,
                2,
                4,
                FullSynthesisExecutionOptions::default(),
                None,
            )
            .unwrap()
        };

        let (small, small_recommended, small_executed, small_policy) = route_for(1024, 1024);
        assert_eq!(small_recommended, SynthesisCrossoverRoute::Windowed);
        assert_eq!(small_executed, small_recommended);
        assert_eq!(small_policy, SynthesisCrossoverPolicy::Adaptive);
        assert!(small.bounded_dependency_samples < small.full_active_samples);
        assert!(small.bounded_workspace_bytes < small.full_workspace_bytes);
        assert!(small.bounded_score < small.full_score);

        let (medium, medium_recommended, _, _) = route_for(2048, 2048);
        assert_eq!(medium_recommended, SynthesisCrossoverRoute::Windowed);
        assert!(medium.bounded_score < medium.full_score);

        let (nearly_full, nearly_full_recommended, _, _) = route_for(3584, 3584);
        assert_eq!(nearly_full_recommended, SynthesisCrossoverRoute::Full);
        assert!(nearly_full.full_score <= nearly_full.bounded_score);
        assert_eq!(nearly_full.cropped_output_samples, 3584_u64 * 3584);
        assert!(nearly_full.bounded_lifting_updates > 0);
        assert!(nearly_full.full_lifting_updates > 0);
        assert!(nearly_full.bounded_copy_samples > 0);
        assert!(nearly_full.full_copy_samples > 0);

        let full = route_for(4096, 4096);
        assert_eq!(full.1, SynthesisCrossoverRoute::Full);
    }

