fn irreversible_component_samples_to_bytes(
    component: &ComponentParameters,
    samples: &[f32],
) -> Result<Vec<u8>> {
    let precision = component.bits_per_sample;
    if precision == 0 || precision > 16 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "irreversible component conversion accepts precision from 1 through 16 bits",
        ));
    }
    let (minimum, maximum, level_shift) = if component.signed {
        (
            -(1_i32 << (precision - 1)),
            (1_i32 << (precision - 1)) - 1,
            0_i32,
        )
    } else {
        (0, (1_i32 << precision) - 1, 1_i32 << (precision - 1))
    };
    let bytes_per_sample = if precision <= 8 { 1 } else { 2 };
    let mut output = alloc::vec![
        0_u8;
        samples
            .len()
            .checked_mul(bytes_per_sample)
            .ok_or(CodestreamError::SizeOverflow)?
    ];
    for (sample, destination) in samples
        .iter()
        .copied()
        .zip(output.chunks_exact_mut(bytes_per_sample))
    {
        if !sample.is_finite() {
            return Err(invalid(
                None,
                None,
                "irreversible reconstruction produced a non-finite sample",
            ));
        }
        let rounded = round_ties_even_f32_to_i32(sample);
        let value = rounded.saturating_add(level_shift).clamp(minimum, maximum);
        if bytes_per_sample == 1 {
            destination[0] = value as u8;
        } else {
            let value = value as u16;
            destination.copy_from_slice(&value.to_le_bytes());
        }
    }
    Ok(output)
}

#[cfg(feature = "parallel")]
fn write_irreversible_component_samples(
    component: &ComponentParameters,
    samples: &[f32],
    output: &mut [u8],
) -> Result<()> {
    let precision = component.bits_per_sample;
    if precision == 0 || precision > 16 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "irreversible component conversion accepts precision from 1 through 16 bits",
        ));
    }
    let (minimum, maximum, level_shift) = if component.signed {
        (
            -(1_i32 << (precision - 1)),
            (1_i32 << (precision - 1)) - 1,
            0_i32,
        )
    } else {
        (0, (1_i32 << precision) - 1, 1_i32 << (precision - 1))
    };
    let bytes_per_sample = if precision <= 8 { 1 } else { 2 };
    if output.len()
        != samples
            .len()
            .checked_mul(bytes_per_sample)
            .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    for (sample, destination) in samples
        .iter()
        .copied()
        .zip(output.chunks_exact_mut(bytes_per_sample))
    {
        if !sample.is_finite() {
            return Err(invalid(
                None,
                None,
                "irreversible reconstruction produced a non-finite sample",
            ));
        }
        let rounded = round_ties_even_f32_to_i32(sample);
        let value = rounded.saturating_add(level_shift).clamp(minimum, maximum);
        if bytes_per_sample == 1 {
            destination[0] = value as u8;
        } else {
            destination.copy_from_slice(&(value as u16).to_le_bytes());
        }
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn irreversible_component_samples_to_bytes_parallel(
    component: &ComponentParameters,
    samples: &[f32],
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<Vec<u8>> {
    use rayon::prelude::*;

    let bytes_per_sample = component_sample_byte_width(component.bits_per_sample)?;
    let mut output = alloc::vec![
        0_u8;
        samples
            .len()
            .checked_mul(bytes_per_sample)
            .ok_or(CodestreamError::SizeOverflow)?
    ];
    if samples.is_empty() {
        return Ok(output);
    }
    let chunk_samples = samples
        .len()
        .div_ceil(worker_count.max(1).min(samples.len()));
    samples
        .par_chunks(chunk_samples)
        .zip(output.par_chunks_mut(chunk_samples * bytes_per_sample))
        .try_for_each(|(samples, output)| {
            let started = timer.start();
            write_irreversible_component_samples(component, samples, output)?;
            timer.finish(started);
            Ok::<(), CodestreamError>(())
        })?;
    Ok(output)
}

#[cfg(feature = "parallel")]
fn write_irreversible_component_samples_to_rows_parallel(
    component: &ComponentParameters,
    samples: &[f32],
    width: usize,
    height: usize,
    output: &mut ComponentPlaneMut<'_>,
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<()> {
    use rayon::prelude::*;

    let bytes_per_sample = component_sample_byte_width(component.bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.stride_bytes < row_bytes
        || samples.len()
            != width
                .checked_mul(height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let required = if height == 0 {
        0
    } else {
        (height - 1)
            .checked_mul(output.stride_bytes)
            .and_then(|offset| offset.checked_add(row_bytes))
            .ok_or(CodestreamError::SizeOverflow)?
    };
    if output.samples.len() < required {
        return Err(CodestreamError::SizeOverflow);
    }
    if samples.is_empty() {
        return Ok(());
    }
    if worker_count <= 1 && output.stride_bytes == row_bytes {
        let output_len = row_bytes
            .checked_mul(height)
            .ok_or(CodestreamError::SizeOverflow)?;
        return write_irreversible_component_samples(
            component,
            samples,
            output
                .samples
                .get_mut(..output_len)
                .ok_or(CodestreamError::SizeOverflow)?,
        );
    }
    let chunk_rows = height.div_ceil(worker_count.max(1).min(height));
    samples
        .par_chunks(width * chunk_rows)
        .zip(
            output
                .samples
                .par_chunks_mut(output.stride_bytes * chunk_rows),
        )
        .try_for_each(|(sample_rows, output_rows)| {
            let started = timer.start();
            for (row, samples) in sample_rows.chunks(width).enumerate() {
                let start = row
                    .checked_mul(output.stride_bytes)
                    .ok_or(CodestreamError::SizeOverflow)?;
                write_irreversible_component_samples(
                    component,
                    samples,
                    output_rows
                        .get_mut(start..start + row_bytes)
                        .ok_or(CodestreamError::SizeOverflow)?,
                )?;
            }
            timer.finish(started);
            Ok(())
        })
}

#[cfg(feature = "parallel")]
fn write_irreversible_component_region_to_rows_parallel(
    component: &ComponentParameters,
    samples: &[f32],
    source_width: usize,
    source_height: usize,
    region: AxisAlignedRegion,
    output: &mut ComponentPlaneMut<'_>,
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<()> {
    use rayon::prelude::*;

    let x = usize::try_from(region.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let y = usize::try_from(region.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let width = usize::try_from(region.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(region.height).map_err(|_| CodestreamError::SizeOverflow)?;
    if x == 0 && y == 0 && width == source_width && height == source_height {
        return write_irreversible_component_samples_to_rows_parallel(
            component,
            samples,
            width,
            height,
            output,
            worker_count,
            timer,
        );
    }
    if x.checked_add(width).is_none_or(|end| end > source_width)
        || y.checked_add(height).is_none_or(|end| end > source_height)
        || samples.len()
            != source_width
                .checked_mul(source_height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let bytes_per_sample = component_sample_byte_width(component.bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.stride_bytes < row_bytes {
        return Err(CodestreamError::SizeOverflow);
    }
    let required = if height == 0 {
        0
    } else {
        (height - 1)
            .checked_mul(output.stride_bytes)
            .and_then(|offset| offset.checked_add(row_bytes))
            .ok_or(CodestreamError::SizeOverflow)?
    };
    if output.samples.len() < required || height == 0 {
        return (output.samples.len() >= required)
            .then_some(())
            .ok_or(CodestreamError::SizeOverflow);
    }
    let chunk_rows = height.div_ceil(worker_count.max(1).min(height));
    let output_chunk_bytes = output
        .stride_bytes
        .checked_mul(chunk_rows)
        .ok_or(CodestreamError::SizeOverflow)?;
    output
        .samples
        .get_mut(..required)
        .ok_or(CodestreamError::SizeOverflow)?
        .par_chunks_mut(output_chunk_bytes)
        .enumerate()
        .try_for_each(|(chunk, output_rows)| {
            let started = timer.start();
            let first_row = chunk * chunk_rows;
            let rows = 1 + (output_rows.len() - row_bytes) / output.stride_bytes;
            for local_row in 0..rows {
                let source_start = (y + first_row + local_row)
                    .checked_mul(source_width)
                    .and_then(|offset| offset.checked_add(x))
                    .ok_or(CodestreamError::SizeOverflow)?;
                let destination_start = local_row
                    .checked_mul(output.stride_bytes)
                    .ok_or(CodestreamError::SizeOverflow)?;
                write_irreversible_component_samples(
                    component,
                    samples
                        .get(source_start..source_start + width)
                        .ok_or(CodestreamError::SizeOverflow)?,
                    output_rows
                        .get_mut(destination_start..destination_start + row_bytes)
                        .ok_or(CodestreamError::SizeOverflow)?,
                )?;
            }
            timer.finish(started);
            Ok(())
        })
}

#[cfg(feature = "parallel")]
fn write_irreversible_component_samples_to_output_rect(
    component: &ComponentParameters,
    samples: &[f32],
    width: usize,
    height: usize,
    output: &mut emuella_j2k_accel::OutputRect<'_>,
) -> Result<()> {
    let bytes_per_sample = component_sample_byte_width(component.bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.width_bytes() != row_bytes
        || output.height() != height
        || samples.len()
            != width
                .checked_mul(height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    for (row, samples) in samples.chunks(width).enumerate() {
        write_irreversible_component_samples(
            component,
            samples,
            output
                .row_mut(row)
                .map_err(|_| CodestreamError::SizeOverflow)?,
        )?;
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn write_transposed_irreversible_component_samples_to_output_rect(
    component: &ComponentParameters,
    samples: &[f32],
    width: usize,
    height: usize,
    output: &mut emuella_j2k_accel::OutputRect<'_>,
    scratch: &mut Vec<f32>,
) -> Result<()> {
    let bytes_per_sample = component_sample_byte_width(component.bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.width_bytes() != row_bytes
        || output.height() != height
        || samples.len()
            != width
                .checked_mul(height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    scratch.resize(width, 0.0);
    for row in 0..height {
        for (column, sample) in scratch[..width].iter_mut().enumerate() {
            *sample = samples[column * height + row];
        }
        write_irreversible_component_samples(
            component,
            &scratch[..width],
            output
                .row_mut(row)
                .map_err(|_| CodestreamError::SizeOverflow)?,
        )?;
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn write_transposed_irreversible_component_samples_to_rows_parallel(
    component: &ComponentParameters,
    samples: &[f32],
    width: usize,
    height: usize,
    output: &mut ComponentPlaneMut<'_>,
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<()> {
    use rayon::prelude::*;

    const COLUMN_BLOCK: usize = 32;
    let bytes_per_sample = component_sample_byte_width(component.bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.stride_bytes < row_bytes
        || samples.len()
            != width
                .checked_mul(height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let required = (height - 1)
        .checked_mul(output.stride_bytes)
        .and_then(|offset| offset.checked_add(row_bytes))
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.samples.len() < required {
        return Err(CodestreamError::SizeOverflow);
    }
    let chunk_rows = height.div_ceil(worker_count.max(1).min(height)).max(1);
    let output_block_bytes = output
        .stride_bytes
        .checked_mul(chunk_rows)
        .ok_or(CodestreamError::SizeOverflow)?;
    output
        .samples
        .get_mut(..required)
        .ok_or(CodestreamError::SizeOverflow)?
        .par_chunks_mut(output_block_bytes)
        .enumerate()
        .map_init(Vec::<f32>::new, |scratch, (block, output_rows)| {
            let started = timer.start();
            let first_y = block * chunk_rows;
            let rows = 1 + (output_rows.len() - row_bytes) / output.stride_bytes;
            for first_x in (0..width).step_by(COLUMN_BLOCK) {
                let columns = (width - first_x).min(COLUMN_BLOCK);
                scratch.resize(rows * columns, 0.0);
                emuella_j2k_accel::transpose_f32_stripe(
                    &samples[first_x * height..],
                    height,
                    height,
                    columns,
                    first_y,
                    rows,
                    scratch,
                    columns,
                )
                .map_err(|_| CodestreamError::SizeOverflow)?;
                for local_y in 0..rows {
                    let destination_start = local_y
                        .checked_mul(output.stride_bytes)
                        .and_then(|offset| {
                            offset.checked_add(first_x.saturating_mul(bytes_per_sample))
                        })
                        .ok_or(CodestreamError::SizeOverflow)?;
                    let destination_end = destination_start
                        .checked_add(columns.saturating_mul(bytes_per_sample))
                        .ok_or(CodestreamError::SizeOverflow)?;
                    write_irreversible_component_samples(
                        component,
                        &scratch[local_y * columns..(local_y + 1) * columns],
                        output_rows
                            .get_mut(destination_start..destination_end)
                            .ok_or(CodestreamError::SizeOverflow)?,
                    )?;
                }
            }
            timer.finish(started);
            Ok(())
        })
        .try_for_each(|result| result)
}

#[cfg(feature = "parallel")]
fn write_transposed_irreversible_component_region_to_rows_parallel(
    component: &ComponentParameters,
    samples: &[f32],
    source_width: usize,
    source_height: usize,
    region: AxisAlignedRegion,
    output: &mut ComponentPlaneMut<'_>,
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<()> {
    use rayon::prelude::*;

    const COLUMN_BLOCK: usize = 32;
    let x = usize::try_from(region.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let y = usize::try_from(region.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let width = usize::try_from(region.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(region.height).map_err(|_| CodestreamError::SizeOverflow)?;
    if x == 0 && y == 0 && width == source_width && height == source_height {
        return write_transposed_irreversible_component_samples_to_rows_parallel(
            component,
            samples,
            width,
            height,
            output,
            worker_count,
            timer,
        );
    }
    if x.checked_add(width).is_none_or(|end| end > source_width)
        || y.checked_add(height).is_none_or(|end| end > source_height)
        || samples.len()
            != source_width
                .checked_mul(source_height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let bytes_per_sample = component_sample_byte_width(component.bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.stride_bytes < row_bytes {
        return Err(CodestreamError::SizeOverflow);
    }
    let required = if height == 0 {
        0
    } else {
        (height - 1)
            .checked_mul(output.stride_bytes)
            .and_then(|offset| offset.checked_add(row_bytes))
            .ok_or(CodestreamError::SizeOverflow)?
    };
    if output.samples.len() < required || height == 0 {
        return (output.samples.len() >= required)
            .then_some(())
            .ok_or(CodestreamError::SizeOverflow);
    }
    let chunk_rows = height.div_ceil(worker_count.max(1).min(height)).max(1);
    let output_block_bytes = output
        .stride_bytes
        .checked_mul(chunk_rows)
        .ok_or(CodestreamError::SizeOverflow)?;
    output
        .samples
        .get_mut(..required)
        .ok_or(CodestreamError::SizeOverflow)?
        .par_chunks_mut(output_block_bytes)
        .enumerate()
        .map_init(Vec::<f32>::new, |scratch, (block, output_rows)| {
            let started = timer.start();
            let first_y = block * chunk_rows;
            let rows = 1 + (output_rows.len() - row_bytes) / output.stride_bytes;
            for first_x in (0..width).step_by(COLUMN_BLOCK) {
                let columns = (width - first_x).min(COLUMN_BLOCK);
                scratch.resize(rows * columns, 0.0);
                emuella_j2k_accel::transpose_f32_stripe(
                    &samples[(x + first_x) * source_height..],
                    source_height,
                    source_height,
                    columns,
                    y + first_y,
                    rows,
                    scratch,
                    columns,
                )
                .map_err(|_| CodestreamError::SizeOverflow)?;
                for local_y in 0..rows {
                    let destination_start = local_y
                        .checked_mul(output.stride_bytes)
                        .and_then(|offset| {
                            offset.checked_add(first_x.saturating_mul(bytes_per_sample))
                        })
                        .ok_or(CodestreamError::SizeOverflow)?;
                    let destination_end = destination_start
                        .checked_add(columns.saturating_mul(bytes_per_sample))
                        .ok_or(CodestreamError::SizeOverflow)?;
                    write_irreversible_component_samples(
                        component,
                        &scratch[local_y * columns..(local_y + 1) * columns],
                        output_rows
                            .get_mut(destination_start..destination_end)
                            .ok_or(CodestreamError::SizeOverflow)?,
                    )?;
                }
            }
            timer.finish(started);
            Ok(())
        })
        .try_for_each(|result| result)
}

fn round_ties_even_f32_to_i32(value: f32) -> i32 {
    let truncated = value as i32;
    if truncated == i32::MIN || truncated == i32::MAX {
        return truncated;
    }
    let fraction = value - truncated as f32;
    if fraction > 0.5 || (fraction == 0.5 && truncated & 1 != 0) {
        truncated + 1
    } else if fraction < -0.5 || (fraction == -0.5 && truncated & 1 != 0) {
        truncated - 1
    } else {
        truncated
    }
}

fn unsigned_component_samples_to_bytes(
    bits_per_sample: u8,
    coefficients: Vec<i32>,
) -> Result<Vec<u8>> {
    unsigned_component_sample_slice_to_bytes(bits_per_sample, &coefficients)
}

fn unsigned_component_sample_slice_to_bytes(
    bits_per_sample: u8,
    coefficients: &[i32],
) -> Result<Vec<u8>> {
    if bits_per_sample == 8 {
        let mut samples = alloc::vec![0_u8; coefficients.len()];
        for (sample, coefficient) in samples.iter_mut().zip(coefficients.iter().copied()) {
            *sample = (coefficient + 128).clamp(0, 255) as u8;
        }
        return Ok(samples);
    }

    if bits_per_sample <= 8 {
        let offset = 1_i32 << (bits_per_sample - 1);
        let max_value = (1_i32 << bits_per_sample) - 1;
        let mut samples = alloc::vec![0_u8; coefficients.len()];
        for (sample, coefficient) in samples.iter_mut().zip(coefficients.iter().copied()) {
            *sample = (coefficient + offset).clamp(0, max_value) as u8;
        }
        return Ok(samples);
    }

    if bits_per_sample == 16 {
        let sample_bytes = coefficients
            .len()
            .checked_mul(2)
            .ok_or(CodestreamError::SizeOverflow)?;
        let mut samples = alloc::vec![0_u8; sample_bytes];
        for (sample_bytes, coefficient) in samples
            .chunks_exact_mut(2)
            .zip(coefficients.iter().copied())
        {
            let sample = (coefficient + 32768).clamp(0, 65535) as u16;
            sample_bytes[0] = sample as u8;
            sample_bytes[1] = (sample >> 8) as u8;
        }
        return Ok(samples);
    }

    if bits_per_sample <= 16 {
        let offset = 1_i32 << (bits_per_sample - 1);
        let max_value = (1_i32 << bits_per_sample) - 1;
        let sample_bytes = coefficients
            .len()
            .checked_mul(2)
            .ok_or(CodestreamError::SizeOverflow)?;
        let mut samples = alloc::vec![0_u8; sample_bytes];
        for (sample_bytes, coefficient) in samples
            .chunks_exact_mut(2)
            .zip(coefficients.iter().copied())
        {
            let sample = (coefficient + offset).clamp(0, max_value) as u16;
            sample_bytes[0] = sample as u8;
            sample_bytes[1] = (sample >> 8) as u8;
        }
        return Ok(samples);
    }

    Err(unsupported(
        None,
        Some(Marker::Siz),
        UnsupportedConstruct::SamplePrecision,
        "owned baseline decode accepts unsigned component precision up to 16 bits for admitted algorithmic profiles",
    ))
}

fn signed_component_samples_to_bytes(
    bits_per_sample: u8,
    coefficients: Vec<i32>,
) -> Result<Vec<u8>> {
    signed_component_sample_slice_to_bytes(bits_per_sample, &coefficients)
}

fn signed_component_sample_slice_to_bytes(
    bits_per_sample: u8,
    coefficients: &[i32],
) -> Result<Vec<u8>> {
    if bits_per_sample > 16 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "owned component decode accepts signed precision up to 16 bits",
        ));
    }
    if bits_per_sample <= 8 {
        let min_value = -(1_i32 << (bits_per_sample - 1));
        let max_value = (1_i32 << (bits_per_sample - 1)) - 1;
        let mut samples = alloc::vec![0_u8; coefficients.len()];
        for (sample, coefficient) in samples.iter_mut().zip(coefficients.iter().copied()) {
            *sample = coefficient.clamp(min_value, max_value) as u8;
        }
        return Ok(samples);
    }
    if bits_per_sample == 16 {
        let sample_bytes = coefficients
            .len()
            .checked_mul(2)
            .ok_or(CodestreamError::SizeOverflow)?;
        let mut samples = alloc::vec![0_u8; sample_bytes];
        for (sample_bytes, coefficient) in samples
            .chunks_exact_mut(2)
            .zip(coefficients.iter().copied())
        {
            let sample = coefficient.clamp(-32768, 32767) as u16;
            sample_bytes[0] = sample as u8;
            sample_bytes[1] = (sample >> 8) as u8;
        }
        return Ok(samples);
    }
    let min_value = -(1_i32 << (bits_per_sample - 1));
    let max_value = (1_i32 << (bits_per_sample - 1)) - 1;
    let sample_bytes = coefficients
        .len()
        .checked_mul(2)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut samples = alloc::vec![0_u8; sample_bytes];
    for (sample_bytes, coefficient) in samples
        .chunks_exact_mut(2)
        .zip(coefficients.iter().copied())
    {
        let sample = coefficient.clamp(min_value, max_value) as u16;
        sample_bytes[0] = sample as u8;
        sample_bytes[1] = (sample >> 8) as u8;
    }
    Ok(samples)
}

fn component_samples_to_bytes(
    bits_per_sample: u8,
    signed: bool,
    coefficients: Vec<i32>,
) -> Result<Vec<u8>> {
    if signed {
        signed_component_samples_to_bytes(bits_per_sample, coefficients)
    } else {
        unsigned_component_samples_to_bytes(bits_per_sample, coefficients)
    }
}

fn component_sample_slice_to_bytes(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
) -> Result<Vec<u8>> {
    if signed {
        signed_component_sample_slice_to_bytes(bits_per_sample, coefficients)
    } else {
        unsigned_component_sample_slice_to_bytes(bits_per_sample, coefficients)
    }
}

#[cfg(feature = "parallel")]
fn write_component_sample_slice_to_bytes(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
    output: &mut [u8],
) -> Result<()> {
    if bits_per_sample == 0 || bits_per_sample > 16 {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::SamplePrecision,
            "owned component decode accepts precision from 1 through 16 bits",
        ));
    }
    let bytes_per_sample = if bits_per_sample <= 8 { 1 } else { 2 };
    if output.len()
        != coefficients
            .len()
            .checked_mul(bytes_per_sample)
            .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    if bits_per_sample == 8 && !signed {
        return emuella_j2k_accel::pack_unsigned_u8_level_shift(coefficients, output)
            .map_err(|_| CodestreamError::SizeOverflow);
    }
    let (minimum, maximum, level_shift) = if signed {
        (
            -(1_i32 << (bits_per_sample - 1)),
            (1_i32 << (bits_per_sample - 1)) - 1,
            0_i32,
        )
    } else {
        (
            0,
            (1_i32 << bits_per_sample) - 1,
            1_i32 << (bits_per_sample - 1),
        )
    };
    for (coefficient, destination) in coefficients
        .iter()
        .copied()
        .zip(output.chunks_exact_mut(bytes_per_sample))
    {
        let value = coefficient
            .saturating_add(level_shift)
            .clamp(minimum, maximum);
        if bytes_per_sample == 1 {
            destination[0] = value as u8;
        } else {
            destination.copy_from_slice(&(value as u16).to_le_bytes());
        }
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn component_sample_slice_to_bytes_parallel(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<Vec<u8>> {
    use rayon::prelude::*;

    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let mut output = alloc::vec![
        0_u8;
        coefficients
            .len()
            .checked_mul(bytes_per_sample)
            .ok_or(CodestreamError::SizeOverflow)?
    ];
    if coefficients.is_empty() {
        return Ok(output);
    }
    let chunk_samples = coefficients
        .len()
        .div_ceil(worker_count.max(1).min(coefficients.len()));
    coefficients
        .par_chunks(chunk_samples)
        .zip(output.par_chunks_mut(chunk_samples * bytes_per_sample))
        .try_for_each(|(coefficients, output)| {
            let started = timer.start();
            write_component_sample_slice_to_bytes(bits_per_sample, signed, coefficients, output)?;
            timer.finish(started);
            Ok::<(), CodestreamError>(())
        })?;
    Ok(output)
}

#[cfg(feature = "parallel")]
fn write_component_sample_slice_to_rows_parallel(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
    width: usize,
    height: usize,
    output: &mut ComponentPlaneMut<'_>,
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<()> {
    use rayon::prelude::*;

    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.stride_bytes < row_bytes
        || coefficients.len()
            != width
                .checked_mul(height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let required = if height == 0 {
        0
    } else {
        (height - 1)
            .checked_mul(output.stride_bytes)
            .and_then(|offset| offset.checked_add(row_bytes))
            .ok_or(CodestreamError::SizeOverflow)?
    };
    if output.samples.len() < required {
        return Err(CodestreamError::SizeOverflow);
    }
    if coefficients.is_empty() {
        return Ok(());
    }
    if worker_count <= 1 && output.stride_bytes == row_bytes {
        let output_len = row_bytes
            .checked_mul(height)
            .ok_or(CodestreamError::SizeOverflow)?;
        return write_component_sample_slice_to_bytes(
            bits_per_sample,
            signed,
            coefficients,
            output
                .samples
                .get_mut(..output_len)
                .ok_or(CodestreamError::SizeOverflow)?,
        );
    }
    let chunk_rows = height.div_ceil(worker_count.max(1).min(height));
    coefficients
        .par_chunks(width * chunk_rows)
        .zip(
            output
                .samples
                .par_chunks_mut(output.stride_bytes * chunk_rows),
        )
        .try_for_each(|(coefficient_rows, output_rows)| {
            let started = timer.start();
            for (row, coefficients) in coefficient_rows.chunks(width).enumerate() {
                let start = row
                    .checked_mul(output.stride_bytes)
                    .ok_or(CodestreamError::SizeOverflow)?;
                write_component_sample_slice_to_bytes(
                    bits_per_sample,
                    signed,
                    coefficients,
                    output_rows
                        .get_mut(start..start + row_bytes)
                        .ok_or(CodestreamError::SizeOverflow)?,
                )?;
            }
            timer.finish(started);
            Ok(())
        })
}

#[cfg(feature = "parallel")]
fn write_component_sample_region_to_rows_parallel(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
    source_width: usize,
    source_height: usize,
    region: AxisAlignedRegion,
    output: &mut ComponentPlaneMut<'_>,
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<()> {
    use rayon::prelude::*;

    let x = usize::try_from(region.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let y = usize::try_from(region.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let width = usize::try_from(region.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(region.height).map_err(|_| CodestreamError::SizeOverflow)?;
    if x == 0 && y == 0 && width == source_width && height == source_height {
        return write_component_sample_slice_to_rows_parallel(
            bits_per_sample,
            signed,
            coefficients,
            width,
            height,
            output,
            worker_count,
            timer,
        );
    }
    if x.checked_add(width).is_none_or(|end| end > source_width)
        || y.checked_add(height).is_none_or(|end| end > source_height)
        || coefficients.len()
            != source_width
                .checked_mul(source_height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.stride_bytes < row_bytes {
        return Err(CodestreamError::SizeOverflow);
    }
    let required = if height == 0 {
        0
    } else {
        (height - 1)
            .checked_mul(output.stride_bytes)
            .and_then(|offset| offset.checked_add(row_bytes))
            .ok_or(CodestreamError::SizeOverflow)?
    };
    if output.samples.len() < required || height == 0 {
        return (output.samples.len() >= required)
            .then_some(())
            .ok_or(CodestreamError::SizeOverflow);
    }
    let chunk_rows = height.div_ceil(worker_count.max(1).min(height));
    let output_chunk_bytes = output
        .stride_bytes
        .checked_mul(chunk_rows)
        .ok_or(CodestreamError::SizeOverflow)?;
    output
        .samples
        .get_mut(..required)
        .ok_or(CodestreamError::SizeOverflow)?
        .par_chunks_mut(output_chunk_bytes)
        .enumerate()
        .try_for_each(|(chunk, output_rows)| {
            let started = timer.start();
            let first_row = chunk * chunk_rows;
            let rows = 1 + (output_rows.len() - row_bytes) / output.stride_bytes;
            for local_row in 0..rows {
                let source_start = (y + first_row + local_row)
                    .checked_mul(source_width)
                    .and_then(|offset| offset.checked_add(x))
                    .ok_or(CodestreamError::SizeOverflow)?;
                let destination_start = local_row
                    .checked_mul(output.stride_bytes)
                    .ok_or(CodestreamError::SizeOverflow)?;
                write_component_sample_slice_to_bytes(
                    bits_per_sample,
                    signed,
                    coefficients
                        .get(source_start..source_start + width)
                        .ok_or(CodestreamError::SizeOverflow)?,
                    output_rows
                        .get_mut(destination_start..destination_start + row_bytes)
                        .ok_or(CodestreamError::SizeOverflow)?,
                )?;
            }
            timer.finish(started);
            Ok(())
        })
}

#[cfg(feature = "parallel")]
fn write_component_sample_slice_to_output_rect(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
    width: usize,
    height: usize,
    output: &mut emuella_j2k_accel::OutputRect<'_>,
) -> Result<()> {
    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.width_bytes() != row_bytes
        || output.height() != height
        || coefficients.len()
            != width
                .checked_mul(height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    for (row, coefficients) in coefficients.chunks(width).enumerate() {
        write_component_sample_slice_to_bytes(
            bits_per_sample,
            signed,
            coefficients,
            output
                .row_mut(row)
                .map_err(|_| CodestreamError::SizeOverflow)?,
        )?;
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn write_transposed_component_sample_slice_to_output_rect(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
    width: usize,
    height: usize,
    output: &mut emuella_j2k_accel::OutputRect<'_>,
    scratch: &mut Vec<i32>,
) -> Result<()> {
    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.width_bytes() != row_bytes
        || output.height() != height
        || coefficients.len()
            != width
                .checked_mul(height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    scratch.resize(width, 0);
    for row in 0..height {
        for (column, coefficient) in scratch[..width].iter_mut().enumerate() {
            *coefficient = coefficients[column * height + row];
        }
        write_component_sample_slice_to_bytes(
            bits_per_sample,
            signed,
            &scratch[..width],
            output
                .row_mut(row)
                .map_err(|_| CodestreamError::SizeOverflow)?,
        )?;
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn write_transposed_component_sample_slice_to_rows_parallel(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
    width: usize,
    height: usize,
    output: &mut ComponentPlaneMut<'_>,
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<()> {
    use rayon::prelude::*;

    const COLUMN_BLOCK: usize = 32;
    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.stride_bytes < row_bytes
        || coefficients.len()
            != width
                .checked_mul(height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let required = (height - 1)
        .checked_mul(output.stride_bytes)
        .and_then(|offset| offset.checked_add(row_bytes))
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.samples.len() < required {
        return Err(CodestreamError::SizeOverflow);
    }
    let chunk_rows = height.div_ceil(worker_count.max(1).min(height)).max(1);
    let output_block_bytes = output
        .stride_bytes
        .checked_mul(chunk_rows)
        .ok_or(CodestreamError::SizeOverflow)?;
    if bits_per_sample == 8 && !signed {
        return output
            .samples
            .get_mut(..required)
            .ok_or(CodestreamError::SizeOverflow)?
            .par_chunks_mut(output_block_bytes)
            .enumerate()
            .try_for_each(|(block, output_rows)| {
                let started = timer.start();
                let first_y = block * chunk_rows;
                let rows = 1 + (output_rows.len() - row_bytes) / output.stride_bytes;
                emuella_j2k_accel::transpose_pack_i32_unsigned_u8(
                    coefficients,
                    width,
                    height,
                    0,
                    first_y,
                    width,
                    rows,
                    output_rows,
                    output.stride_bytes,
                )
                .map_err(|_| CodestreamError::SizeOverflow)?;
                timer.finish(started);
                Ok(())
            });
    }
    output
        .samples
        .get_mut(..required)
        .ok_or(CodestreamError::SizeOverflow)?
        .par_chunks_mut(output_block_bytes)
        .enumerate()
        .map_init(Vec::<i32>::new, |scratch, (block, output_rows)| {
            let started = timer.start();
            let first_y = block * chunk_rows;
            let rows = 1 + (output_rows.len() - row_bytes) / output.stride_bytes;
            for first_x in (0..width).step_by(COLUMN_BLOCK) {
                let columns = (width - first_x).min(COLUMN_BLOCK);
                scratch.resize(rows * columns, 0);
                emuella_j2k_accel::transpose_i32_stripe(
                    &coefficients[first_x * height..],
                    height,
                    height,
                    columns,
                    first_y,
                    rows,
                    scratch,
                    columns,
                )
                .map_err(|_| CodestreamError::SizeOverflow)?;
                for local_y in 0..rows {
                    let destination_start = local_y
                        .checked_mul(output.stride_bytes)
                        .and_then(|offset| {
                            offset.checked_add(first_x.saturating_mul(bytes_per_sample))
                        })
                        .ok_or(CodestreamError::SizeOverflow)?;
                    let destination_end = destination_start
                        .checked_add(columns.saturating_mul(bytes_per_sample))
                        .ok_or(CodestreamError::SizeOverflow)?;
                    write_component_sample_slice_to_bytes(
                        bits_per_sample,
                        signed,
                        &scratch[local_y * columns..(local_y + 1) * columns],
                        output_rows
                            .get_mut(destination_start..destination_end)
                            .ok_or(CodestreamError::SizeOverflow)?,
                    )?;
                }
            }
            timer.finish(started);
            Ok(())
        })
        .try_for_each(|result| result)
}

#[cfg(feature = "parallel")]
fn write_transposed_component_sample_region_to_rows_parallel(
    bits_per_sample: u8,
    signed: bool,
    coefficients: &[i32],
    source_width: usize,
    source_height: usize,
    region: AxisAlignedRegion,
    output: &mut ComponentPlaneMut<'_>,
    worker_count: usize,
    timer: &PhaseTaskTimer,
) -> Result<()> {
    use rayon::prelude::*;

    const COLUMN_BLOCK: usize = 32;
    let x = usize::try_from(region.x).map_err(|_| CodestreamError::SizeOverflow)?;
    let y = usize::try_from(region.y).map_err(|_| CodestreamError::SizeOverflow)?;
    let width = usize::try_from(region.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(region.height).map_err(|_| CodestreamError::SizeOverflow)?;
    if x == 0 && y == 0 && width == source_width && height == source_height {
        return write_transposed_component_sample_slice_to_rows_parallel(
            bits_per_sample,
            signed,
            coefficients,
            width,
            height,
            output,
            worker_count,
            timer,
        );
    }
    if x.checked_add(width).is_none_or(|end| end > source_width)
        || y.checked_add(height).is_none_or(|end| end > source_height)
        || coefficients.len()
            != source_width
                .checked_mul(source_height)
                .ok_or(CodestreamError::SizeOverflow)?
    {
        return Err(CodestreamError::SizeOverflow);
    }
    let bytes_per_sample = component_sample_byte_width(bits_per_sample)?;
    let row_bytes = width
        .checked_mul(bytes_per_sample)
        .ok_or(CodestreamError::SizeOverflow)?;
    if output.stride_bytes < row_bytes {
        return Err(CodestreamError::SizeOverflow);
    }
    let required = if height == 0 {
        0
    } else {
        (height - 1)
            .checked_mul(output.stride_bytes)
            .and_then(|offset| offset.checked_add(row_bytes))
            .ok_or(CodestreamError::SizeOverflow)?
    };
    if output.samples.len() < required || height == 0 {
        return (output.samples.len() >= required)
            .then_some(())
            .ok_or(CodestreamError::SizeOverflow);
    }
    let chunk_rows = height.div_ceil(worker_count.max(1).min(height)).max(1);
    let output_block_bytes = output
        .stride_bytes
        .checked_mul(chunk_rows)
        .ok_or(CodestreamError::SizeOverflow)?;
    let output_rows = output
        .samples
        .get_mut(..required)
        .ok_or(CodestreamError::SizeOverflow)?;
    if bits_per_sample == 8 && !signed {
        return output_rows
            .par_chunks_mut(output_block_bytes)
            .enumerate()
            .try_for_each(|(block, output_rows)| {
                let started = timer.start();
                let first_y = block * chunk_rows;
                let rows = 1 + (output_rows.len() - row_bytes) / output.stride_bytes;
                emuella_j2k_accel::transpose_pack_i32_unsigned_u8(
                    coefficients,
                    source_width,
                    source_height,
                    x,
                    y + first_y,
                    width,
                    rows,
                    output_rows,
                    output.stride_bytes,
                )
                .map_err(|_| CodestreamError::SizeOverflow)?;
                timer.finish(started);
                Ok(())
            });
    }
    output_rows
        .par_chunks_mut(output_block_bytes)
        .enumerate()
        .map_init(Vec::<i32>::new, |scratch, (block, output_rows)| {
            let started = timer.start();
            let first_y = block * chunk_rows;
            let rows = 1 + (output_rows.len() - row_bytes) / output.stride_bytes;
            for first_x in (0..width).step_by(COLUMN_BLOCK) {
                let columns = (width - first_x).min(COLUMN_BLOCK);
                scratch.resize(rows * columns, 0);
                emuella_j2k_accel::transpose_i32_stripe(
                    &coefficients[(x + first_x) * source_height..],
                    source_height,
                    source_height,
                    columns,
                    y + first_y,
                    rows,
                    scratch,
                    columns,
                )
                .map_err(|_| CodestreamError::SizeOverflow)?;
                for local_y in 0..rows {
                    let destination_start = local_y
                        .checked_mul(output.stride_bytes)
                        .and_then(|offset| {
                            offset.checked_add(first_x.saturating_mul(bytes_per_sample))
                        })
                        .ok_or(CodestreamError::SizeOverflow)?;
                    let destination_end = destination_start
                        .checked_add(columns.saturating_mul(bytes_per_sample))
                        .ok_or(CodestreamError::SizeOverflow)?;
                    write_component_sample_slice_to_bytes(
                        bits_per_sample,
                        signed,
                        &scratch[local_y * columns..(local_y + 1) * columns],
                        output_rows
                            .get_mut(destination_start..destination_end)
                            .ok_or(CodestreamError::SizeOverflow)?,
                    )?;
                }
            }
            timer.finish(started);
            Ok(())
        })
        .try_for_each(|result| result)
}

