#[cfg(feature = "std")]
#[derive(Debug, Clone, Copy, Default)]
struct HtCleanupOctetAccumulator {
    seen_mask: u8,
    significance_mask: u8,
    magnitude_sign_bits: u16,
    magnitude_sign_width_pattern: u64,
}

#[cfg(feature = "std")]
#[derive(Debug, Clone, Copy, Default)]
struct HtCleanupQuadAccumulator {
    significance_mask: u8,
    u_value: Option<u16>,
}

#[cfg(feature = "std")]
fn accumulate_ht_cleanup_octet_workload(
    block: ht::HtBlockLayout,
    outputs: &[ht::HtVlcCleanupCoefficientOutput],
    profile: &mut Htj2kCleanupOctetWorkload,
) -> Result<()> {
    let mut octets = vec![HtCleanupOctetAccumulator::default(); block.octet_count()];
    let quad_columns = block.quad_columns();
    let line_pair_count = block.line_pair_count();
    let predictor_count = quad_columns
        .checked_add(1)
        .ok_or(CodestreamError::SizeOverflow)?;
    let mut quads = vec![
        HtCleanupQuadAccumulator::default();
        line_pair_count
            .checked_mul(quad_columns)
            .ok_or(CodestreamError::SizeOverflow)?
    ];
    let mut south_predictors = vec![
        0_u32;
        line_pair_count
            .checked_mul(predictor_count)
            .ok_or(CodestreamError::SizeOverflow)?
    ];
    for output in outputs {
        let octet = octets
            .get_mut(output.position.octet_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let mask = u8::try_from(output.position.octet_mask())
            .map_err(|_| CodestreamError::SizeOverflow)?;
        if octet.seen_mask & mask != 0 {
            return Err(CodestreamError::SizeOverflow);
        }
        if output.magnitude_sign_bits > 16 {
            return Err(CodestreamError::SizeOverflow);
        }
        octet.seen_mask |= mask;
        octet.magnitude_sign_width_pattern |=
            u64::from(output.magnitude_sign_bits) << (u32::from(output.position.octet_slot()) * 5);
        if output.significant {
            octet.significance_mask |= mask;
            octet.magnitude_sign_bits = octet
                .magnitude_sign_bits
                .checked_add(output.magnitude_sign_bits)
                .ok_or(CodestreamError::SizeOverflow)?;

            let quad_index = output
                .position
                .line_pair
                .checked_mul(quad_columns)
                .and_then(|base| base.checked_add(output.position.quad_column))
                .ok_or(CodestreamError::SizeOverflow)?;
            let quad = quads
                .get_mut(quad_index)
                .ok_or(CodestreamError::SizeOverflow)?;
            quad.significance_mask |= 1_u8 << output.position.quad_slot();
            // For every significant coefficient, m_n = u - exponent reduction.
            let u_value = output
                .magnitude_sign_bits
                .checked_add(u16::from(output.magnitude_exponent_reduction))
                .ok_or(CodestreamError::SizeOverflow)?;
            if quad
                .u_value
                .replace(u_value)
                .is_some_and(|prior| prior != u_value)
            {
                return Err(CodestreamError::SizeOverflow);
            }

            let slot = output.position.quad_slot();
            if matches!(slot, 1 | 3) {
                let explicit_mask = if output.magnitude_sign_bits == 16 {
                    u16::MAX
                } else {
                    (1_u16 << output.magnitude_sign_bits) - 1
                };
                let mut predictor = u32::from(output.magnitude_sign_value & explicit_mask);
                predictor |= u32::from(output.embedded_magnitude_bit)
                    << u32::from(output.magnitude_sign_bits);
                predictor |= 1;
                let boundary = output
                    .position
                    .quad_column
                    .checked_add(usize::from(slot == 3))
                    .ok_or(CodestreamError::SizeOverflow)?;
                let predictor_index = output
                    .position
                    .line_pair
                    .checked_mul(predictor_count)
                    .and_then(|base| base.checked_add(boundary))
                    .ok_or(CodestreamError::SizeOverflow)?;
                let target = south_predictors
                    .get_mut(predictor_index)
                    .ok_or(CodestreamError::SizeOverflow)?;
                *target |= predictor;
            }
        }
        profile.embedded_magnitude_coefficient_count += u64::from(output.embedded_magnitude_bit);
        profile.exponent_reduction_coefficient_count +=
            u64::from(output.magnitude_exponent_reduction);
    }

    for group in block.octet_groups() {
        let octet = octets
            .get(group.octet_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let present_mask =
            u8::try_from(group.present_mask()).map_err(|_| CodestreamError::SizeOverflow)?;
        if octet.seen_mask != present_mask || octet.magnitude_sign_bits > 128 {
            return Err(CodestreamError::SizeOverflow);
        }
        profile.octet_count = profile
            .octet_count
            .checked_add(1)
            .ok_or(CodestreamError::SizeOverflow)?;
        profile.significance_mask_histogram[usize::from(octet.significance_mask)] += 1;
        profile.significant_coefficient_count_histogram
            [octet.significance_mask.count_ones() as usize] += 1;
        profile.magnitude_sign_bit_count_histogram[usize::from(octet.magnitude_sign_bits)] += 1;
        *profile
            .magnitude_sign_width_pattern_histogram
            .entry(octet.magnitude_sign_width_pattern)
            .or_insert(0) += 1;
    }

    for line_pair in 0..line_pair_count {
        let mut west_context = 0_u8;
        let mut first_u_offset = false;
        for quad_column in 0..quad_columns {
            let quad_index = line_pair
                .checked_mul(quad_columns)
                .and_then(|base| base.checked_add(quad_column))
                .ok_or(CodestreamError::SizeOverflow)?;
            let quad = quads.get(quad_index).ok_or(CodestreamError::SizeOverflow)?;
            let significance_mask = quad.significance_mask;
            let (context, kappa) = if line_pair == 0 {
                (west_context, 1_u16)
            } else {
                let previous_predictor_base = (line_pair - 1)
                    .checked_mul(predictor_count)
                    .ok_or(CodestreamError::SizeOverflow)?;
                let south_west = *south_predictors
                    .get(previous_predictor_base + quad_column)
                    .ok_or(CodestreamError::SizeOverflow)?;
                let south_east = *south_predictors
                    .get(previous_predictor_base + quad_column + 1)
                    .ok_or(CodestreamError::SizeOverflow)?;
                let context =
                    west_context | u8::from(south_west != 0) | (u8::from(south_east != 0) << 2);
                let kappa = if significance_mask.count_ones() <= 1 {
                    1
                } else {
                    let predictor = south_west | south_east | 2;
                    (u32::BITS - 1 - predictor.leading_zeros()).max(1) as u16
                };
                (context, kappa)
            };
            let histogram = if line_pair == 0 {
                &mut profile.initial_vlc_context_histogram
            } else {
                &mut profile.noninitial_vlc_context_histogram
            };
            histogram[usize::from(context)] += 1;
            let u_value = quad.u_value.unwrap_or(kappa);
            if u_value < kappa {
                return Err(CodestreamError::SizeOverflow);
            }
            // An unset u_offset contributes the base value one, hence u == kappa.
            let u_offset = u_value != kappa;
            if quad_column % 2 == 0 {
                first_u_offset = u_offset;
            }
            if quad_column % 2 == 1 || quad_column + 1 == quad_columns {
                let second_u_offset = quad_column % 2 == 1 && u_offset;
                let mode = usize::from(first_u_offset) | (usize::from(second_u_offset) << 1);
                let histogram = if line_pair == 0 {
                    &mut profile.initial_uvlc_mode_histogram
                } else {
                    &mut profile.noninitial_uvlc_mode_histogram
                };
                histogram[mode] += 1;
            }
            west_context = if line_pair == 0 {
                (significance_mask & 1) | ((significance_mask & 0x0e) >> 1)
            } else {
                u8::from(significance_mask & 0x0c != 0) << 1
            };
        }
    }
    Ok(())
}

/// Parse the current lossless, no-decomposition HT profile into workload
/// characteristics suitable for corpus histograms and backend thresholds.
///
/// Returns `Ok(None)` for codestreams outside that structural profile. Packet
/// and segment errors within the profile remain explicit errors.
#[cfg(feature = "std")]
pub fn htj2k_lossless_no_decomp_workload_profile(
    input: &[u8],
) -> Result<Option<Htj2kDecodeWorkloadProfile>> {
    let codestream = parse(input)?;
    if codestream.kind != CodestreamKind::Htj2k {
        return Ok(None);
    }
    let Some(coding_style) = codestream.coding_style else {
        return Ok(None);
    };
    if coding_style.entropy_coder != EntropyCoder::HtBlockCoding
        || coding_style.decomposition_levels != 0
        || (coding_style.multiple_component_transform
            && ht_reversible_mct_component_format(&codestream).is_none())
        || coding_style.code_block_style & !0x40 != 0
        || !default_precinct_layer_count_supported(coding_style.layers)
    {
        return Ok(None);
    }
    let Some(Ok(candidate)) = ht_decode_candidate(&codestream) else {
        return Ok(None);
    };

    let configured_width = checked_pow2_u32(coding_style.code_block_width_exponent)?;
    let configured_height = checked_pow2_u32(coding_style.code_block_height_exponent)?;
    let configured_code_block_width =
        u16::try_from(configured_width).map_err(|_| CodestreamError::SizeOverflow)?;
    let configured_code_block_height =
        u16::try_from(configured_height).map_err(|_| CodestreamError::SizeOverflow)?;
    let tile_rects = tile_rects(&codestream)?;
    if tile_rects.len() > 1 {
        validate_one_tile_part_per_tile(&codestream)?;
    }
    let single_tile = tile_rects.len() == 1;
    let mut total_code_block_count = 0_usize;
    let mut cleanup_only_code_block_count = 0;
    let mut refinement_code_block_count = 0;
    let mut cleanup_octets = Htj2kCleanupOctetWorkload {
        octet_count: 0,
        initial_vlc_context_histogram: [0; 8],
        noninitial_vlc_context_histogram: [0; 8],
        initial_uvlc_mode_histogram: [0; 4],
        noninitial_uvlc_mode_histogram: [0; 4],
        significance_mask_histogram: [0; 256],
        significant_coefficient_count_histogram: [0; 9],
        magnitude_sign_bit_count_histogram: [0; 129],
        magnitude_sign_width_pattern_histogram: BTreeMap::new(),
        embedded_magnitude_coefficient_count: 0,
        exponent_reduction_coefficient_count: 0,
    };
    let mut cleanup_profile_scratch = ht::HtBlockScratchBuffer::new();
    let mut segment_scratch = Vec::new();
    let mut code_blocks = Vec::new();
    for tile_rect in tile_rects {
        let payload = if single_tile {
            single_part1_profile_tile(input, &codestream)?.1
        } else {
            let tile_part = codestream
                .tiles
                .iter()
                .find(|tile| tile.tile_index == tile_rect.tile_index)
                .ok_or(CodestreamError::SizeOverflow)?;
            tile_payload(input, tile_part)?
        };
        let contributions =
            parse_default_precinct_lrcp_packets(input, &codestream, tile_rect, payload)?;
        let code_block_columns = usize::try_from(ceil_div(tile_rect.width, configured_width)?)
            .map_err(|_| CodestreamError::SizeOverflow)?;
        let code_block_rows = usize::try_from(ceil_div(tile_rect.height, configured_height)?)
            .map_err(|_| CodestreamError::SizeOverflow)?;
        let tile_code_block_count = code_block_columns
            .checked_mul(code_block_rows)
            .and_then(|count| count.checked_mul(usize::from(codestream.siz.component_count())))
            .ok_or(CodestreamError::SizeOverflow)?;
        if contributions.len() > tile_code_block_count {
            return Err(CodestreamError::SizeOverflow);
        }
        total_code_block_count = total_code_block_count
            .checked_add(tile_code_block_count)
            .ok_or(CodestreamError::SizeOverflow)?;

        for contribution in &contributions {
            let code_block_segment =
                code_block_segment_for_decode(payload, contribution, &mut segment_scratch)?;
            let expanded_coding_set = contribution
                .expanded_ht_coding_sets
                .as_deref()
                .and_then(<[HtCodeBlockCodingSet]>::last)
                .copied();
            let (segment, cleanup_len, missing_most_significant_bitplanes, coding_passes) =
                if let Some(coding_set) = expanded_coding_set {
                    let coding_set_end = coding_set
                        .byte_offset
                        .checked_add(coding_set.byte_len)
                        .ok_or(CodestreamError::SizeOverflow)?;
                    (
                        code_block_segment
                            .get(coding_set.byte_offset..coding_set_end)
                            .ok_or(CodestreamError::SizeOverflow)?,
                        coding_set.cleanup_byte_len,
                        coding_set.missing_most_significant_bitplanes,
                        coding_set.coding_passes,
                    )
                } else {
                    (
                        code_block_segment,
                        contribution
                            .coding_segments
                            .first()
                            .map_or(code_block_segment.len(), |cleanup| cleanup.byte_len),
                        contribution.missing_most_significant_bitplanes,
                        contribution.coding_passes,
                    )
                };
            if coding_passes == 1 {
                cleanup_only_code_block_count += 1;
            } else {
                refinement_code_block_count += 1;
            }
            let cleanup_segment = segment
                .get(..cleanup_len)
                .ok_or(CodestreamError::SizeOverflow)?;
            let layout = ht::HtCleanupPassSegmentLayout::from_cleanup_pass_bytes(cleanup_segment)
                .map_err(ht_cleanup_pass_segment_layout_error)?;
            let views = layout
                .split_segment(cleanup_segment)
                .map_err(ht_cleanup_pass_segment_layout_error)?;
            let active_dimensions =
                ht::HtCodeBlockDimensions::new(contribution.width, contribution.height)
                    .map_err(ht_cleanup_pass_segment_layout_error)?;
            let cleanup_request =
                ht::HtCodeBlockDecodeRequest::new_with_active_dimensions_and_cleanup_pass_segment_layout(
                    candidate.marker_candidate,
                    active_dimensions,
                    missing_most_significant_bitplanes,
                    1,
                    layout,
                    cleanup_segment,
                );
            let outcome = cleanup_profile_scratch
                .decode_code_block_cleanup_vlc_outputs_with_reusable_buffers(cleanup_request)
                .map_err(ht_cleanup_pass_segment_layout_error)?
                .ok_or(CodestreamError::SizeOverflow)?;
            accumulate_ht_cleanup_octet_workload(
                outcome.block(),
                outcome.outputs(),
                &mut cleanup_octets,
            )?;
            let (ff_bytes, longest_non_ff_run) = byte_stuffing_profile(views.magnitude_sign);
            let coefficient_count = usize::from(contribution.width)
                .checked_mul(usize::from(contribution.height))
                .ok_or(CodestreamError::SizeOverflow)?;
            code_blocks.push(Htj2kCodeBlockWorkload {
                component_index: contribution.component_index,
                width: contribution.width,
                height: contribution.height,
                coefficient_count,
                segment_bytes: segment.len(),
                cleanup_magnitude_sign_bytes: Some(layout.magnitude_sign().len),
                cleanup_magnitude_sign_ff_bytes: Some(ff_bytes),
                cleanup_magnitude_sign_longest_non_ff_run: Some(longest_non_ff_run),
                cleanup_mel_vlc_bytes: Some(layout.mel_vlc().len),
                coding_passes,
                missing_most_significant_bitplanes,
                full_configured_block: contribution.width == configured_code_block_width
                    && contribution.height == configured_code_block_height,
                full_octets: contribution.width % 4 == 0 && contribution.height % 2 == 0,
            });
        }
    }

    Ok(Some(Htj2kDecodeWorkloadProfile {
        configured_code_block_width,
        configured_code_block_height,
        total_code_block_count,
        included_code_block_count: code_blocks.len(),
        omitted_code_block_count: total_code_block_count - code_blocks.len(),
        cleanup_only_code_block_count,
        refinement_code_block_count,
        cleanup_octets,
        code_blocks,
    }))
}

#[cfg(feature = "std")]
fn byte_stuffing_profile(bytes: &[u8]) -> (usize, usize) {
    let mut ff_bytes = 0;
    let mut current_non_ff_run = 0;
    let mut longest_non_ff_run = 0;
    for &byte in bytes {
        if byte == 0xff {
            ff_bytes += 1;
            current_non_ff_run = 0;
        } else {
            current_non_ff_run += 1;
            longest_non_ff_run = longest_non_ff_run.max(current_non_ff_run);
        }
    }
    (ff_bytes, longest_non_ff_run)
}

/// Decode the benchmark-oriented lossless HTJ2K profile with caller-retained
/// block workspace.
///
/// The accepted profile is one or more tiles, one effective precinct per
/// component and resolution, any positive quality-layer count and COD
/// progression order, reversible 5/3 with zero or one decomposition level,
/// grayscale/RGB components with matching signedness and 8- to 16-bit
/// precision, and one or
/// more HT sets of Cleanup plus optional SigProp/MagRef passes per included
/// code-block. The final independently decodable set supplies the requested
/// full-quality block. Three-component streams with three matching signed or
/// unsigned 8- to 16-bit components may use the reversible multiple-component
/// transform; decoded RGB samples are returned after inverse DWT and RCT.
/// Multi-tile decode currently requires zero decomposition levels and exactly
/// one tile-part per tile.
#[cfg(feature = "std")]
pub fn decode_htj2k_lossless_owned_with_workspace(
    input: &[u8],
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Option<DecodedImage>> {
    let codestream = parse(input)?;
    if codestream.kind != CodestreamKind::Htj2k {
        return Ok(None);
    }

    let candidate = match ht_decode_candidate(&codestream) {
        Some(Ok(candidate)) => candidate,
        Some(Err(classification)) => {
            return Err(unsupported(
                None,
                None,
                ht_construct_from_reason(classification.reason),
                classification.reason.message(),
            ));
        }
        None => {
            return Err(unsupported(
                None,
                Some(Marker::Cod),
                UnsupportedConstruct::MarkerSegment,
                "HTJ2K decode requires complete marker and tile-part state",
            ));
        }
    };
    let coding_style = codestream.coding_style.ok_or_else(|| {
        unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::MarkerSegment,
            "HTJ2K decode requires a COD marker",
        )
    })?;
    if coding_style.decomposition_levels > 1 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "benchmark-oriented HTJ2K decode accepts at most one reversible 5/3 decomposition level",
        ));
    }
    if coding_style.decomposition_levels == 1
        && (codestream.siz.image_origin_x != 0
            || codestream.siz.image_origin_y != 0
            || codestream.siz.tile_origin_x != 0
            || codestream.siz.tile_origin_y != 0)
    {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::WaveletTransform,
            "benchmark-oriented HTJ2K DWT1 decode currently requires zero image and tile origins",
        ));
    }
    if coding_style.multiple_component_transform
        && ht_reversible_mct_component_format(&codestream).is_none()
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::Transform,
            "benchmark-oriented HTJ2K multiple-component transform requires three matching, non-subsampled signed or unsigned 8- to 16-bit components",
        ));
    }
    if coding_style.code_block_style & !0x40 != 0 {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::HtBlockDecode,
            "benchmark-oriented HTJ2K decode accepts the HT code-block style without additional style flags",
        ));
    }

    let transfer = ht_reversible_code_block_transfer(input, &codestream)?.ok_or_else(|| {
        unsupported(
            None,
            Some(Marker::Qcd),
            UnsupportedConstruct::MarkerSegment,
            "benchmark-oriented HTJ2K decode requires one reversible scalar QCD value",
        )
    })?;
    let ht_tile_rects = tile_rects(&codestream)?;
    if ht_tile_rects.len() > 1 {
        if coding_style.decomposition_levels != 0 {
            return Err(unsupported(
                None,
                Some(Marker::Cod),
                UnsupportedConstruct::WaveletTransform,
                "multi-tile HTJ2K decode currently accepts no decomposition levels",
            ));
        }
        return decode_htj2k_lossless_multitile_no_decomp(
            input,
            &codestream,
            candidate.marker_candidate,
            transfer,
            &ht_tile_rects,
            workspace,
        )
        .map(Some);
    }

    let (tile_rect, payload) = single_part1_profile_tile(input, &codestream)?;
    let contributions =
        parse_default_precinct_lrcp_packets(input, &codestream, tile_rect, payload)?;

    let stride = usize::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let plane_len = stride
        .checked_mul(height)
        .ok_or(CodestreamError::SizeOverflow)?;
    if coding_style.decomposition_levels == 1 {
        let components = decode_htj2k_lossless_decomp_components(
            candidate,
            payload,
            &contributions,
            transfer,
            &codestream,
            coding_style,
            tile_rect,
            stride,
            plane_len,
            workspace,
        )?;
        let first_component = codestream
            .siz
            .components
            .first()
            .ok_or(CodestreamError::SizeOverflow)?;
        return Ok(Some(DecodedImage {
            width: tile_rect.width,
            height: tile_rect.height,
            bits_per_sample: first_component.bits_per_sample,
            signed: first_component.signed,
            components,
        }));
    }
    let components = decode_htj2k_lossless_no_decomp_tile_components(
        candidate,
        payload,
        &contributions,
        transfer,
        stride,
        plane_len,
        &codestream,
        workspace,
    )?;
    let first_component = codestream
        .siz
        .components
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    Ok(Some(DecodedImage {
        width: tile_rect.width,
        height: tile_rect.height,
        bits_per_sample: first_component.bits_per_sample,
        signed: first_component.signed,
        components,
    }))
}

#[cfg(feature = "std")]
fn decode_htj2k_lossless_multitile_no_decomp(
    input: &[u8],
    codestream: &Codestream,
    marker_candidate: ht::HtDecodeCandidate,
    transfer: HtReversibleCodeBlockTransfer,
    tile_rects: &[TileRect],
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<DecodedImage> {
    validate_one_tile_part_per_tile(codestream)?;
    let component_samples =
        native_part1_profile_component_samples(codestream).ok_or(CodestreamError::SizeOverflow)?;
    if component_samples == 0 || component_samples > MAX_NATIVE_PART1_PROFILE_COMPONENT_SAMPLES {
        return Err(unsupported(
            None,
            Some(Marker::Siz),
            UnsupportedConstruct::PacketDecode,
            "multi-tile HTJ2K decode is guarded to at most 16 Mi component samples",
        ));
    }
    let image_width =
        usize::try_from(codestream.image_width()).map_err(|_| CodestreamError::SizeOverflow)?;
    let image_height =
        usize::try_from(codestream.image_height()).map_err(|_| CodestreamError::SizeOverflow)?;
    let plane_len = image_width
        .checked_mul(image_height)
        .ok_or(CodestreamError::SizeOverflow)?;
    let component_sample_bytes = codestream
        .siz
        .components
        .iter()
        .map(|component| component_sample_byte_width(component.bits_per_sample))
        .collect::<Result<Vec<_>>>()?;

    #[cfg(feature = "parallel")]
    let use_parallel_tiles = {
        let component_count = usize::from(codestream.siz.component_count());
        rayon::current_thread_index().is_none()
            && parallel_decode_dispatch_available()
            && should_parallel_decode_tiles(tile_rects, component_count)
    };
    let components = {
        #[cfg(feature = "parallel")]
        {
            if use_parallel_tiles {
                decode_htj2k_multitile_components_parallel(
                    input,
                    codestream,
                    marker_candidate,
                    transfer,
                    image_width,
                    plane_len,
                    &component_sample_bytes,
                    tile_rects,
                    workspace,
                )?
            } else {
                decode_htj2k_multitile_components_sequential(
                    input,
                    codestream,
                    marker_candidate,
                    transfer,
                    image_width,
                    plane_len,
                    &component_sample_bytes,
                    tile_rects,
                    workspace,
                )?
            }
        }
        #[cfg(not(feature = "parallel"))]
        {
            decode_htj2k_multitile_components_sequential(
                input,
                codestream,
                marker_candidate,
                transfer,
                image_width,
                plane_len,
                &component_sample_bytes,
                tile_rects,
                workspace,
            )?
        }
    };

    let first_component = codestream
        .siz
        .components
        .first()
        .ok_or(CodestreamError::SizeOverflow)?;
    Ok(DecodedImage {
        width: u32::try_from(image_width).map_err(|_| CodestreamError::SizeOverflow)?,
        height: u32::try_from(image_height).map_err(|_| CodestreamError::SizeOverflow)?,
        bits_per_sample: first_component.bits_per_sample,
        signed: first_component.signed,
        components,
    })
}

#[cfg(feature = "std")]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_multitile_components_sequential(
    input: &[u8],
    codestream: &Codestream,
    marker_candidate: ht::HtDecodeCandidate,
    transfer: HtReversibleCodeBlockTransfer,
    image_width: usize,
    plane_len: usize,
    component_sample_bytes: &[usize],
    tile_rects: &[TileRect],
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Vec<DecodedComponent>> {
    let mut components = allocate_stitched_components(plane_len, component_sample_bytes)?;
    for &tile_rect in tile_rects {
        let tile_components = decode_htj2k_multitile_tile_components(
            input,
            codestream,
            marker_candidate,
            transfer,
            tile_rect,
            workspace,
        )?;
        stitch_htj2k_tile_components(
            &mut components,
            &tile_components,
            component_sample_bytes,
            image_width,
            tile_rect,
        )?;
    }
    Ok(components)
}

#[cfg(all(feature = "std", feature = "parallel"))]
struct DecodedHtTileComponents {
    tile_rect: TileRect,
    components: Vec<DecodedComponent>,
}

#[cfg(all(feature = "std", feature = "parallel"))]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_multitile_components_parallel(
    input: &[u8],
    codestream: &Codestream,
    marker_candidate: ht::HtDecodeCandidate,
    transfer: HtReversibleCodeBlockTransfer,
    image_width: usize,
    plane_len: usize,
    component_sample_bytes: &[usize],
    tile_rects: &[TileRect],
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Vec<DecodedComponent>> {
    use rayon::prelude::*;

    workspace
        .parallel_tiles
        .resize_with(tile_rects.len(), HtCodestreamDecodeWorkspace::new);
    let decoded_tiles = tile_rects
        .par_iter()
        .zip(workspace.parallel_tiles.par_iter_mut())
        .map(|(&tile_rect, tile_workspace)| {
            decode_htj2k_multitile_tile_components(
                input,
                codestream,
                marker_candidate,
                transfer,
                tile_rect,
                tile_workspace,
            )
            .map(|components| DecodedHtTileComponents {
                tile_rect,
                components,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let mut components = allocate_stitched_components(plane_len, component_sample_bytes)?;
    for decoded_tile in decoded_tiles {
        stitch_htj2k_tile_components(
            &mut components,
            &decoded_tile.components,
            component_sample_bytes,
            image_width,
            decoded_tile.tile_rect,
        )?;
    }
    Ok(components)
}

#[cfg(feature = "std")]
fn allocate_stitched_components(
    plane_len: usize,
    component_sample_bytes: &[usize],
) -> Result<Vec<DecodedComponent>> {
    component_sample_bytes
        .iter()
        .map(|bytes_per_sample| {
            plane_len
                .checked_mul(*bytes_per_sample)
                .map(|len| DecodedComponent {
                    samples: alloc::vec![0_u8; len],
                })
                .ok_or(CodestreamError::SizeOverflow)
        })
        .collect()
}

#[cfg(feature = "std")]
fn stitch_htj2k_tile_components(
    components: &mut [DecodedComponent],
    tile_components: &[DecodedComponent],
    component_sample_bytes: &[usize],
    image_width: usize,
    tile_rect: TileRect,
) -> Result<()> {
    if components.len() != tile_components.len() || components.len() != component_sample_bytes.len()
    {
        return Err(CodestreamError::SizeOverflow);
    }
    for ((stitched, tile_component), bytes_per_sample) in components
        .iter_mut()
        .zip(tile_components)
        .zip(component_sample_bytes)
    {
        stitch_tile_sample_plane(
            &mut stitched.samples,
            image_width,
            *bytes_per_sample,
            tile_rect,
            &tile_component.samples,
        )?;
    }
    Ok(())
}

#[cfg(feature = "std")]
fn decode_htj2k_multitile_tile_components(
    input: &[u8],
    codestream: &Codestream,
    marker_candidate: ht::HtDecodeCandidate,
    transfer: HtReversibleCodeBlockTransfer,
    tile_rect: TileRect,
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Vec<DecodedComponent>> {
    let tile_part = codestream
        .tiles
        .iter()
        .find(|tile| tile.tile_index == tile_rect.tile_index)
        .copied()
        .ok_or(CodestreamError::SizeOverflow)?;
    let payload = tile_payload(input, &tile_part)?;
    let contributions = parse_default_precinct_lrcp_packets(input, codestream, tile_rect, payload)?;
    let stride = usize::try_from(tile_rect.width).map_err(|_| CodestreamError::SizeOverflow)?;
    let height = usize::try_from(tile_rect.height).map_err(|_| CodestreamError::SizeOverflow)?;
    let plane_len = stride
        .checked_mul(height)
        .ok_or(CodestreamError::SizeOverflow)?;
    decode_htj2k_lossless_no_decomp_tile_components(
        HtCodestreamDecodeCandidate {
            marker_candidate,
            tile_part,
        },
        payload,
        &contributions,
        transfer,
        stride,
        plane_len,
        codestream,
        workspace,
    )
}

#[cfg(feature = "std")]
#[inline(never)]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_lossless_no_decomp_tile_components(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    stride: usize,
    plane_len: usize,
    codestream: &Codestream,
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Vec<DecodedComponent>> {
    // Keep MCT plane assembly outlined so independent components retain their
    // direct byte-placement loop without per-block destination dispatch.
    if codestream
        .coding_style
        .is_some_and(|style| style.multiple_component_transform)
    {
        let component_format =
            ht_reversible_mct_component_format(codestream).ok_or(CodestreamError::SizeOverflow)?;
        return decode_htj2k_lossless_no_decomp_mct_components(
            candidate,
            payload,
            contributions,
            transfer,
            component_format,
            stride,
            plane_len,
            workspace,
        );
    }

    let component_count = usize::from(codestream.siz.component_count());
    let mut components = Vec::with_capacity(component_count);
    for component in &codestream.siz.components {
        let sample_len = plane_len
            .checked_mul(component_sample_byte_width(component.bits_per_sample)?)
            .ok_or(CodestreamError::SizeOverflow)?;
        components.push(DecodedComponent {
            samples: alloc::vec![0_u8; sample_len],
        });
    }

    #[cfg(feature = "parallel")]
    if let Some(axis) =
        select_ht_parallel_decode_axis(component_count, contributions.len(), plane_len)
    {
        match axis {
            HtParallelDecodeAxis::Components => {
                ensure_ht_parallel_workers(&mut workspace.parallel_workers, component_count);
                decode_htj2k_no_decomp_components_parallel(
                    candidate,
                    payload,
                    contributions,
                    transfer,
                    stride,
                    &codestream.siz.components,
                    &mut components,
                    &mut workspace.parallel_workers[..component_count],
                )?;
            }
            HtParallelDecodeAxis::CodeBlocks => {
                let worker_count = rayon::current_num_threads().min(contributions.len());
                ensure_ht_parallel_workers(&mut workspace.parallel_workers, worker_count);
                ensure_ht_parallel_decoded_blocks(
                    &mut workspace.parallel_decoded_blocks,
                    contributions.len(),
                );
                decode_htj2k_no_decomp_code_blocks_parallel(
                    candidate,
                    payload,
                    contributions,
                    transfer,
                    stride,
                    &codestream.siz.components,
                    &mut components,
                    &mut workspace.parallel_workers[..worker_count],
                    &mut workspace.parallel_decoded_blocks[..contributions.len()],
                )?;
            }
        }
        return Ok(components);
    }

    let mut segment_scratch = Vec::new();
    for contribution in contributions {
        let expanded_coding_set = contribution
            .expanded_ht_coding_sets
            .as_deref()
            .and_then(<[HtCodeBlockCodingSet]>::last)
            .copied();
        let coding_passes = expanded_coding_set.map_or(contribution.coding_passes, |coding_set| {
            coding_set.coding_passes
        });
        if !(1..=3).contains(&coding_passes) {
            return Err(unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::HtBlockDecode,
                "benchmark-oriented HTJ2K decode accepts up to three coding passes per HT set",
            ));
        }
        let active_dimensions =
            ht::HtCodeBlockDimensions::new(contribution.width, contribution.height)
                .map_err(|_| CodestreamError::SizeOverflow)?;
        let code_block_segment =
            code_block_segment_for_decode(payload, contribution, &mut segment_scratch)?;
        let (segment, cleanup_len, missing_most_significant_bitplanes) =
            if let Some(coding_set) = expanded_coding_set {
                let coding_set_end = coding_set
                    .byte_offset
                    .checked_add(coding_set.byte_len)
                    .ok_or(CodestreamError::SizeOverflow)?;
                let segment = code_block_segment
                    .get(coding_set.byte_offset..coding_set_end)
                    .ok_or_else(|| {
                        invalid(
                            None,
                            Some(Marker::Sod),
                            "HT coding-set range exceeds code-block bytes",
                        )
                    })?;
                (
                    segment,
                    coding_set.cleanup_byte_len,
                    coding_set.missing_most_significant_bitplanes,
                )
            } else {
                if !contribution.ht_coded {
                    return Err(unsupported(
                        None,
                        Some(Marker::Sod),
                        UnsupportedConstruct::HtBlockDecode,
                        "HT packet contribution has no independently decodable coding set",
                    ));
                }
                (
                    code_block_segment,
                    contribution
                        .coding_segments
                        .first()
                        .map_or(code_block_segment.len(), |cleanup| cleanup.byte_len),
                    contribution.missing_most_significant_bitplanes,
                )
            };
        let cleanup_segment = segment.get(..cleanup_len).ok_or_else(|| {
            invalid(
                None,
                Some(Marker::Sod),
                "HT packet cleanup segment length exceeds code-block bytes",
            )
        })?;
        let segment_layout =
            ht::HtCleanupPassSegmentLayout::from_cleanup_pass_bytes(cleanup_segment)
                .map_err(ht_cleanup_pass_segment_layout_error)?;
        let code_block_input = HtCodestreamCodeBlockInput {
            candidate,
            active_dimensions,
            missing_most_significant_bitplanes,
            coding_passes,
            segment_layout,
            segment,
        };
        let coefficient_count = active_dimensions.coefficient_count();
        if workspace.coefficients.len() < coefficient_count {
            workspace.coefficients.resize(coefficient_count, 0);
        }
        let (decoded, _) = workspace.block.decode_code_block_input_into_with_progress(
            code_block_input,
            &mut workspace.coefficients[..coefficient_count],
        )?;
        if decoded.is_none() {
            return Err(unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::HtBlockDecode,
                "HT cleanup code-block dispatch did not produce coefficients",
            ));
        }
        let component_index = usize::from(contribution.component_index);
        let component_parameters = codestream
            .siz
            .components
            .get(component_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let component = components
            .get_mut(component_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let transfer = Some(transfer);
        if component_parameters.signed {
            place_signed_ht_code_block_samples(
                &mut component.samples,
                stride,
                component_parameters.bits_per_sample,
                contribution,
                &workspace.coefficients[..coefficient_count],
                transfer,
            )?;
        } else {
            place_ht_code_block_samples(
                &mut component.samples,
                stride,
                component_parameters.bits_per_sample,
                contribution,
                &workspace.coefficients[..coefficient_count],
                transfer,
            )?;
        }
    }

    Ok(components)
}

#[cfg(feature = "std")]
#[inline(never)]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_lossless_decomp_components(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    codestream: &Codestream,
    coding_style: CodingStyleMarker,
    tile_rect: TileRect,
    stride: usize,
    plane_len: usize,
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Vec<DecodedComponent>> {
    let component_count = usize::from(codestream.siz.component_count());
    let planes = workspace
        .mct_planes
        .get_mut(..component_count)
        .ok_or(CodestreamError::SizeOverflow)?;
    for plane in planes.iter_mut() {
        plane.resize(plane_len, 0);
        plane.fill(0);
    }
    let mut segment_scratch = Vec::new();

    for contribution in contributions {
        let expanded_coding_set = contribution
            .expanded_ht_coding_sets
            .as_deref()
            .and_then(<[HtCodeBlockCodingSet]>::last)
            .copied();
        let coding_passes = expanded_coding_set.map_or(contribution.coding_passes, |coding_set| {
            coding_set.coding_passes
        });
        if !(1..=3).contains(&coding_passes) {
            return Err(unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::HtBlockDecode,
                "benchmark-oriented HTJ2K decode accepts up to three coding passes per HT set",
            ));
        }
        let active_dimensions =
            ht::HtCodeBlockDimensions::new(contribution.width, contribution.height)
                .map_err(|_| CodestreamError::SizeOverflow)?;
        let code_block_segment =
            code_block_segment_for_decode(payload, contribution, &mut segment_scratch)?;
        let (segment, cleanup_len, missing_most_significant_bitplanes) =
            if let Some(coding_set) = expanded_coding_set {
                let coding_set_end = coding_set
                    .byte_offset
                    .checked_add(coding_set.byte_len)
                    .ok_or(CodestreamError::SizeOverflow)?;
                let segment = code_block_segment
                    .get(coding_set.byte_offset..coding_set_end)
                    .ok_or_else(|| {
                        invalid(
                            None,
                            Some(Marker::Sod),
                            "HT coding-set range exceeds code-block bytes",
                        )
                    })?;
                (
                    segment,
                    coding_set.cleanup_byte_len,
                    coding_set.missing_most_significant_bitplanes,
                )
            } else {
                if !contribution.ht_coded {
                    return Err(unsupported(
                        None,
                        Some(Marker::Sod),
                        UnsupportedConstruct::HtBlockDecode,
                        "HT packet contribution has no independently decodable coding set",
                    ));
                }
                (
                    code_block_segment,
                    contribution
                        .coding_segments
                        .first()
                        .map_or(code_block_segment.len(), |cleanup| cleanup.byte_len),
                    contribution.missing_most_significant_bitplanes,
                )
            };
        let cleanup_segment = segment.get(..cleanup_len).ok_or_else(|| {
            invalid(
                None,
                Some(Marker::Sod),
                "HT packet cleanup segment length exceeds code-block bytes",
            )
        })?;
        let segment_layout =
            ht::HtCleanupPassSegmentLayout::from_cleanup_pass_bytes(cleanup_segment)
                .map_err(ht_cleanup_pass_segment_layout_error)?;
        let code_block_input = HtCodestreamCodeBlockInput {
            candidate,
            active_dimensions,
            missing_most_significant_bitplanes,
            coding_passes,
            segment_layout,
            segment,
        };
        let coefficient_count = active_dimensions.coefficient_count();
        if workspace.coefficients.len() < coefficient_count {
            workspace.coefficients.resize(coefficient_count, 0);
        }
        let (decoded, _) = workspace.block.decode_code_block_input_into_with_progress(
            code_block_input,
            &mut workspace.coefficients[..coefficient_count],
        )?;
        if decoded.is_none() {
            return Err(unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::HtBlockDecode,
                "HT cleanup code-block dispatch did not produce coefficients",
            ));
        }
        let plane = planes
            .get_mut(usize::from(contribution.component_index))
            .ok_or(CodestreamError::SizeOverflow)?;
        place_ht_code_block_coefficients(
            plane,
            stride,
            contribution,
            &workspace.coefficients[..coefficient_count],
            Some(ht_reversible_code_block_transfer_for_contribution(
                transfer,
                contribution,
            )?),
        )?;
    }

    inverse_reversible_5_3_component_planes(planes, stride, tile_rect, coding_style, None)?;

    if coding_style.multiple_component_transform {
        let [red, green, blue] = &mut workspace.mct_planes;
        transform::inverse_reversible_color_transform_bounded(red, green, blue).map_err(|_| {
            unsupported(
                None,
                None,
                UnsupportedConstruct::Transform,
                "inverse reversible color transform failed for benchmark-oriented HTJ2K decode",
            )
        })?;
    }

    codestream
        .siz
        .components
        .iter()
        .enumerate()
        .map(|(component_index, component)| {
            let plane = workspace
                .mct_planes
                .get(component_index)
                .ok_or(CodestreamError::SizeOverflow)?;
            component_sample_slice_to_bytes(component.bits_per_sample, component.signed, plane)
                .map(|samples| DecodedComponent { samples })
        })
        .collect()
}

#[cfg(feature = "std")]
#[inline(never)]
fn decode_htj2k_lossless_no_decomp_mct_components(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    component_format: ComponentParameters,
    stride: usize,
    plane_len: usize,
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Vec<DecodedComponent>> {
    for plane in &mut workspace.mct_planes {
        plane.resize(plane_len, 0);
        plane.fill(0);
    }

    #[cfg(feature = "parallel")]
    if let Some(axis) = select_ht_parallel_decode_axis(3, contributions.len(), plane_len) {
        match axis {
            HtParallelDecodeAxis::Components => {
                ensure_ht_parallel_workers(&mut workspace.parallel_workers, 3);
                decode_htj2k_no_decomp_mct_planes_parallel(
                    candidate,
                    payload,
                    contributions,
                    transfer,
                    stride,
                    &mut workspace.mct_planes,
                    &mut workspace.parallel_workers[..3],
                )?;
            }
            HtParallelDecodeAxis::CodeBlocks => {
                let worker_count = rayon::current_num_threads().min(contributions.len());
                ensure_ht_parallel_workers(&mut workspace.parallel_workers, worker_count);
                ensure_ht_parallel_decoded_blocks(
                    &mut workspace.parallel_decoded_blocks,
                    contributions.len(),
                );
                decode_htj2k_no_decomp_mct_code_blocks_parallel(
                    candidate,
                    payload,
                    contributions,
                    transfer,
                    stride,
                    &mut workspace.mct_planes,
                    &mut workspace.parallel_workers[..worker_count],
                    &mut workspace.parallel_decoded_blocks[..contributions.len()],
                )?;
            }
        }
        return finish_htj2k_no_decomp_mct_components(component_format, workspace);
    }

    let mut segment_scratch = Vec::new();

    for contribution in contributions {
        let expanded_coding_set = contribution
            .expanded_ht_coding_sets
            .as_deref()
            .and_then(<[HtCodeBlockCodingSet]>::last)
            .copied();
        let coding_passes = expanded_coding_set.map_or(contribution.coding_passes, |coding_set| {
            coding_set.coding_passes
        });
        if !(1..=3).contains(&coding_passes) {
            return Err(unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::HtBlockDecode,
                "benchmark-oriented HTJ2K decode accepts up to three coding passes per HT set",
            ));
        }
        let active_dimensions =
            ht::HtCodeBlockDimensions::new(contribution.width, contribution.height)
                .map_err(|_| CodestreamError::SizeOverflow)?;
        let code_block_segment =
            code_block_segment_for_decode(payload, contribution, &mut segment_scratch)?;
        let (segment, cleanup_len, missing_most_significant_bitplanes) =
            if let Some(coding_set) = expanded_coding_set {
                let coding_set_end = coding_set
                    .byte_offset
                    .checked_add(coding_set.byte_len)
                    .ok_or(CodestreamError::SizeOverflow)?;
                let segment = code_block_segment
                    .get(coding_set.byte_offset..coding_set_end)
                    .ok_or_else(|| {
                        invalid(
                            None,
                            Some(Marker::Sod),
                            "HT coding-set range exceeds code-block bytes",
                        )
                    })?;
                (
                    segment,
                    coding_set.cleanup_byte_len,
                    coding_set.missing_most_significant_bitplanes,
                )
            } else {
                if !contribution.ht_coded {
                    return Err(unsupported(
                        None,
                        Some(Marker::Sod),
                        UnsupportedConstruct::HtBlockDecode,
                        "HT packet contribution has no independently decodable coding set",
                    ));
                }
                (
                    code_block_segment,
                    contribution
                        .coding_segments
                        .first()
                        .map_or(code_block_segment.len(), |cleanup| cleanup.byte_len),
                    contribution.missing_most_significant_bitplanes,
                )
            };
        let cleanup_segment = segment.get(..cleanup_len).ok_or_else(|| {
            invalid(
                None,
                Some(Marker::Sod),
                "HT packet cleanup segment length exceeds code-block bytes",
            )
        })?;
        let segment_layout =
            ht::HtCleanupPassSegmentLayout::from_cleanup_pass_bytes(cleanup_segment)
                .map_err(ht_cleanup_pass_segment_layout_error)?;
        let code_block_input = HtCodestreamCodeBlockInput {
            candidate,
            active_dimensions,
            missing_most_significant_bitplanes,
            coding_passes,
            segment_layout,
            segment,
        };
        let coefficient_count = active_dimensions.coefficient_count();
        if workspace.coefficients.len() < coefficient_count {
            workspace.coefficients.resize(coefficient_count, 0);
        }
        let (decoded, _) = workspace.block.decode_code_block_input_into_with_progress(
            code_block_input,
            &mut workspace.coefficients[..coefficient_count],
        )?;
        if decoded.is_none() {
            return Err(unsupported(
                None,
                Some(Marker::Sod),
                UnsupportedConstruct::HtBlockDecode,
                "HT cleanup code-block dispatch did not produce coefficients",
            ));
        }
        let component_index = usize::from(contribution.component_index);
        let plane = workspace
            .mct_planes
            .get_mut(component_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        place_ht_code_block_coefficients(
            plane,
            stride,
            contribution,
            &workspace.coefficients[..coefficient_count],
            Some(transfer),
        )?;
    }

    finish_htj2k_no_decomp_mct_components(component_format, workspace)
}

#[cfg(feature = "std")]
fn finish_htj2k_no_decomp_mct_components(
    component_format: ComponentParameters,
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Vec<DecodedComponent>> {
    if component_format.bits_per_sample == 8 && !component_format.signed {
        let [y, db, dr] = &workspace.mct_planes;
        return rgb_u8_inverse_rct_plane_slices_to_bytes(y, db, dr).map(|components| {
            components
                .into_iter()
                .map(|samples| DecodedComponent { samples })
                .collect()
        });
    }

    let [red, green, blue] = &mut workspace.mct_planes;
    transform::inverse_reversible_color_transform_bounded(red, green, blue).map_err(|_| {
        unsupported(
            None,
            None,
            UnsupportedConstruct::Transform,
            "inverse reversible color transform failed for benchmark-oriented HTJ2K decode",
        )
    })?;
    [red.as_slice(), green.as_slice(), blue.as_slice()]
        .into_iter()
        .map(|plane| {
            component_sample_slice_to_bytes(
                component_format.bits_per_sample,
                component_format.signed,
                plane,
            )
            .map(|samples| DecodedComponent { samples })
        })
        .collect()
}

#[cfg(all(feature = "std", feature = "parallel"))]
const MIN_PARALLEL_HT_PLANE_SAMPLES: usize = 64 * 1024;

#[cfg(all(feature = "std", feature = "parallel"))]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum HtParallelDecodeAxis {
    Components,
    CodeBlocks,
}

#[cfg(all(feature = "std", feature = "parallel"))]
fn select_ht_parallel_decode_axis(
    component_count: usize,
    contribution_count: usize,
    plane_len: usize,
) -> Option<HtParallelDecodeAxis> {
    if rayon::current_thread_index().is_some()
        || rayon::current_num_threads() <= 1
        || !ht_parallel_work_eligible(contribution_count, plane_len)
    {
        return None;
    }
    Some(ht_parallel_axis_for_worker_count(
        component_count,
        rayon::current_num_threads(),
    ))
}

#[cfg(all(feature = "std", feature = "parallel"))]
fn ht_parallel_axis_for_worker_count(
    component_count: usize,
    worker_count: usize,
) -> HtParallelDecodeAxis {
    if component_count >= 3 && worker_count <= component_count {
        HtParallelDecodeAxis::Components
    } else {
        HtParallelDecodeAxis::CodeBlocks
    }
}

#[cfg(all(feature = "std", feature = "parallel"))]
fn ht_parallel_work_eligible(contribution_count: usize, plane_len: usize) -> bool {
    contribution_count >= 3 * MIN_PARALLEL_CODE_BLOCKS && plane_len >= MIN_PARALLEL_HT_PLANE_SAMPLES
}

#[cfg(all(feature = "std", feature = "parallel"))]
fn ensure_ht_parallel_workers(workers: &mut Vec<HtParallelDecodeWorker>, worker_count: usize) {
    workers.resize_with(worker_count, HtParallelDecodeWorker::default);
}

#[cfg(all(feature = "std", feature = "parallel"))]
fn ensure_ht_parallel_decoded_blocks(
    decoded: &mut Vec<HtParallelDecodedCodeBlock>,
    contribution_count: usize,
) {
    decoded.resize_with(contribution_count, HtParallelDecodedCodeBlock::default);
}
#[cfg(all(feature = "std", feature = "parallel"))]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_no_decomp_components_parallel(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    stride: usize,
    component_parameters: &[ComponentParameters],
    components: &mut [DecodedComponent],
    workers: &mut [HtParallelDecodeWorker],
) -> Result<()> {
    use rayon::prelude::*;

    components
        .par_iter_mut()
        .zip(workers.par_iter_mut())
        .enumerate()
        .try_for_each(|(component_index, (component, worker))| {
            let parameters = component_parameters
                .get(component_index)
                .ok_or(CodestreamError::SizeOverflow)?;
            decode_htj2k_component_parallel(
                candidate,
                payload,
                contributions,
                transfer,
                component_index,
                worker,
                |contribution, coefficients, transfer| {
                    if parameters.signed {
                        place_signed_ht_code_block_samples(
                            &mut component.samples,
                            stride,
                            parameters.bits_per_sample,
                            contribution,
                            coefficients,
                            transfer,
                        )
                    } else {
                        place_ht_code_block_samples(
                            &mut component.samples,
                            stride,
                            parameters.bits_per_sample,
                            contribution,
                            coefficients,
                            transfer,
                        )
                    }
                },
            )
        })
}

#[cfg(all(feature = "std", feature = "parallel"))]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_component_parallel(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    component_index: usize,
    worker: &mut HtParallelDecodeWorker,
    mut place: impl FnMut(
        &PacketCodeBlockContribution,
        &[i32],
        Option<HtReversibleCodeBlockTransfer>,
    ) -> Result<()>,
) -> Result<()> {
    let HtParallelDecodeWorker {
        block,
        coefficients,
        segment,
    } = worker;
    for contribution in contributions
        .iter()
        .filter(|contribution| usize::from(contribution.component_index) == component_index)
    {
        let transfer = decode_htj2k_contribution_parallel(
            candidate,
            payload,
            contribution,
            transfer,
            block,
            segment,
            coefficients,
        )?;
        place(
            contribution,
            &coefficients[..active_ht_coefficient_count(contribution)?],
            transfer,
        )?;
    }
    Ok(())
}

#[cfg(all(feature = "std", feature = "parallel"))]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_contribution_parallel(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contribution: &PacketCodeBlockContribution,
    transfer: HtReversibleCodeBlockTransfer,
    block: &mut HtCodestreamBlockDecodeWorkspace,
    segment_scratch: &mut Vec<u8>,
    coefficients: &mut Vec<i32>,
) -> Result<Option<HtReversibleCodeBlockTransfer>> {
    let expanded_coding_set = contribution
        .expanded_ht_coding_sets
        .as_deref()
        .and_then(<[HtCodeBlockCodingSet]>::last)
        .copied();
    let coding_passes = expanded_coding_set.map_or(contribution.coding_passes, |coding_set| {
        coding_set.coding_passes
    });
    if !(1..=3).contains(&coding_passes) {
        return Err(unsupported(
            None,
            Some(Marker::Sod),
            UnsupportedConstruct::HtBlockDecode,
            "benchmark-oriented HTJ2K decode accepts up to three coding passes per HT set",
        ));
    }
    let active_dimensions = ht::HtCodeBlockDimensions::new(contribution.width, contribution.height)
        .map_err(|_| CodestreamError::SizeOverflow)?;
    let code_block_segment = code_block_segment_for_decode(payload, contribution, segment_scratch)?;
    let (segment, cleanup_len, missing_most_significant_bitplanes) =
        if let Some(coding_set) = expanded_coding_set {
            let coding_set_end = coding_set
                .byte_offset
                .checked_add(coding_set.byte_len)
                .ok_or(CodestreamError::SizeOverflow)?;
            let segment = code_block_segment
                .get(coding_set.byte_offset..coding_set_end)
                .ok_or_else(|| {
                    invalid(
                        None,
                        Some(Marker::Sod),
                        "HT coding-set range exceeds code-block bytes",
                    )
                })?;
            (
                segment,
                coding_set.cleanup_byte_len,
                coding_set.missing_most_significant_bitplanes,
            )
        } else {
            if !contribution.ht_coded {
                return Err(unsupported(
                    None,
                    Some(Marker::Sod),
                    UnsupportedConstruct::HtBlockDecode,
                    "HT packet contribution has no independently decodable coding set",
                ));
            }
            (
                code_block_segment,
                contribution
                    .coding_segments
                    .first()
                    .map_or(code_block_segment.len(), |cleanup| cleanup.byte_len),
                contribution.missing_most_significant_bitplanes,
            )
        };
    let cleanup_segment = segment.get(..cleanup_len).ok_or_else(|| {
        invalid(
            None,
            Some(Marker::Sod),
            "HT packet cleanup segment length exceeds code-block bytes",
        )
    })?;
    let segment_layout = ht::HtCleanupPassSegmentLayout::from_cleanup_pass_bytes(cleanup_segment)
        .map_err(ht_cleanup_pass_segment_layout_error)?;
    let code_block_input = HtCodestreamCodeBlockInput {
        candidate,
        active_dimensions,
        missing_most_significant_bitplanes,
        coding_passes,
        segment_layout,
        segment,
    };
    let coefficient_count = active_dimensions.coefficient_count();
    if coefficients.len() < coefficient_count {
        coefficients.resize(coefficient_count, 0);
    }
    let (decoded, dispatch_progress) = block.decode_code_block_input_into_with_progress(
        code_block_input,
        &mut coefficients[..coefficient_count],
    )?;
    if decoded.is_none() {
        return Err(unsupported(
            None,
            Some(Marker::Sod),
            UnsupportedConstruct::HtBlockDecode,
            "HT cleanup code-block dispatch did not produce coefficients",
        ));
    }
    Ok(Some(transfer))
}

#[cfg(all(feature = "std", feature = "parallel"))]
fn active_ht_coefficient_count(contribution: &PacketCodeBlockContribution) -> Result<usize> {
    usize::from(contribution.width)
        .checked_mul(usize::from(contribution.height))
        .ok_or(CodestreamError::SizeOverflow)
}

#[cfg(all(feature = "std", feature = "parallel"))]
fn decode_htj2k_blocks_to_coefficients_parallel(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    workers: &mut [HtParallelDecodeWorker],
    decoded: &mut [HtParallelDecodedCodeBlock],
) -> Result<()> {
    use rayon::prelude::*;

    if contributions.is_empty() || workers.is_empty() || decoded.len() < contributions.len() {
        return Err(CodestreamError::SizeOverflow);
    }
    let worker_count = workers.len().min(contributions.len());
    let chunk_size = contributions.len() / worker_count
        + usize::from(!contributions.len().is_multiple_of(worker_count));

    decoded[..contributions.len()]
        .par_chunks_mut(chunk_size)
        .zip(workers[..worker_count].par_iter_mut())
        .enumerate()
        .try_for_each(|(chunk_index, (decoded_chunk, worker))| {
            let contribution_start = chunk_index
                .checked_mul(chunk_size)
                .ok_or(CodestreamError::SizeOverflow)?;
            let HtParallelDecodeWorker { block, segment, .. } = worker;
            for (chunk_offset, output) in decoded_chunk.iter_mut().enumerate() {
                let contribution_index = contribution_start
                    .checked_add(chunk_offset)
                    .ok_or(CodestreamError::SizeOverflow)?;
                let contribution = contributions
                    .get(contribution_index)
                    .ok_or(CodestreamError::SizeOverflow)?;
                output.contribution_index = contribution_index;
                output.transfer = decode_htj2k_contribution_parallel(
                    candidate,
                    payload,
                    contribution,
                    transfer,
                    block,
                    segment,
                    &mut output.coefficients,
                )?;
            }
            Ok(())
        })
}

#[cfg(all(feature = "std", feature = "parallel"))]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_no_decomp_code_blocks_parallel(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    stride: usize,
    component_parameters: &[ComponentParameters],
    components: &mut [DecodedComponent],
    workers: &mut [HtParallelDecodeWorker],
    decoded: &mut [HtParallelDecodedCodeBlock],
) -> Result<()> {
    decode_htj2k_blocks_to_coefficients_parallel(
        candidate,
        payload,
        contributions,
        transfer,
        workers,
        decoded,
    )?;
    for output in decoded.iter().take(contributions.len()) {
        let contribution = contributions
            .get(output.contribution_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let component_index = usize::from(contribution.component_index);
        let parameters = component_parameters
            .get(component_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let component = components
            .get_mut(component_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let coefficient_count = active_ht_coefficient_count(contribution)?;
        if parameters.signed {
            place_signed_ht_code_block_samples(
                &mut component.samples,
                stride,
                parameters.bits_per_sample,
                contribution,
                &output.coefficients[..coefficient_count],
                output.transfer,
            )?;
        } else {
            place_ht_code_block_samples(
                &mut component.samples,
                stride,
                parameters.bits_per_sample,
                contribution,
                &output.coefficients[..coefficient_count],
                output.transfer,
            )?;
        }
    }
    Ok(())
}

#[cfg(all(feature = "std", feature = "parallel"))]
#[allow(clippy::too_many_arguments)]
fn decode_htj2k_no_decomp_mct_code_blocks_parallel(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    stride: usize,
    planes: &mut [Vec<i32>; 3],
    workers: &mut [HtParallelDecodeWorker],
    decoded: &mut [HtParallelDecodedCodeBlock],
) -> Result<()> {
    decode_htj2k_blocks_to_coefficients_parallel(
        candidate,
        payload,
        contributions,
        transfer,
        workers,
        decoded,
    )?;
    for output in decoded.iter().take(contributions.len()) {
        let contribution = contributions
            .get(output.contribution_index)
            .ok_or(CodestreamError::SizeOverflow)?;
        let plane = planes
            .get_mut(usize::from(contribution.component_index))
            .ok_or(CodestreamError::SizeOverflow)?;
        let coefficient_count = active_ht_coefficient_count(contribution)?;
        place_ht_code_block_coefficients(
            plane,
            stride,
            contribution,
            &output.coefficients[..coefficient_count],
            output.transfer,
        )?;
    }
    Ok(())
}

#[cfg(all(feature = "std", feature = "parallel"))]
fn decode_htj2k_no_decomp_mct_planes_parallel(
    candidate: HtCodestreamDecodeCandidate,
    payload: &[u8],
    contributions: &[PacketCodeBlockContribution],
    transfer: HtReversibleCodeBlockTransfer,
    stride: usize,
    planes: &mut [Vec<i32>; 3],
    workers: &mut [HtParallelDecodeWorker],
) -> Result<()> {
    use rayon::prelude::*;

    planes
        .par_iter_mut()
        .zip(workers.par_iter_mut())
        .enumerate()
        .try_for_each(|(component_index, (plane, worker))| {
            decode_htj2k_component_parallel(
                candidate,
                payload,
                contributions,
                transfer,
                component_index,
                worker,
                |contribution, coefficients, transfer| {
                    place_ht_code_block_coefficients(
                        plane,
                        stride,
                        contribution,
                        coefficients,
                        transfer,
                    )
                },
            )
        })
}
/// Decode the benchmark-oriented lossless HTJ2K profile with an ephemeral
/// workspace.
#[cfg(feature = "std")]
pub fn decode_htj2k_lossless_owned(input: &[u8]) -> Result<Option<DecodedImage>> {
    let mut workspace = HtCodestreamDecodeWorkspace::new();
    decode_htj2k_lossless_owned_with_workspace(input, &mut workspace)
}

/// Return whether marker and packet state fits the algorithmic lossless HTJ2K
/// profile accepted by [`decode_htj2k_lossless_owned`].
#[cfg(feature = "std")]
pub fn is_htj2k_lossless_profile(input: &[u8], codestream: &Codestream) -> bool {
    if codestream.kind != CodestreamKind::Htj2k {
        return false;
    }
    let Some(Ok(_candidate)) = ht_decode_candidate(codestream) else {
        return false;
    };
    let Some(coding_style) = codestream.coding_style else {
        return false;
    };
    if coding_style.decomposition_levels > 1
        || (coding_style.decomposition_levels == 1
            && (codestream.siz.image_origin_x != 0
                || codestream.siz.image_origin_y != 0
                || codestream.siz.tile_origin_x != 0
                || codestream.siz.tile_origin_y != 0))
        || (coding_style.multiple_component_transform
            && ht_reversible_mct_component_format(codestream).is_none())
        || coding_style.code_block_style & !0x40 != 0
    {
        return false;
    }
    let Ok(Some(_transfer)) = ht_reversible_code_block_transfer(input, codestream) else {
        return false;
    };
    let Ok(tile_rects) = tile_rects(codestream) else {
        return false;
    };
    if tile_rects.is_empty() || (tile_rects.len() > 1 && coding_style.decomposition_levels != 0) {
        return false;
    }
    if tile_rects.len() > 1 && validate_one_tile_part_per_tile(codestream).is_err() {
        return false;
    }
    tile_rects.into_iter().all(|tile_rect| {
        let Some(tile_part) = codestream
            .tiles
            .iter()
            .find(|tile| tile.tile_index == tile_rect.tile_index)
        else {
            return false;
        };
        let Ok(payload) = tile_payload(input, tile_part) else {
            return false;
        };
        let Ok(contributions) =
            parse_default_precinct_lrcp_packets(input, codestream, tile_rect, payload)
        else {
            return false;
        };
        ht_contributions_have_supported_final_sets(&contributions)
    })
}

#[cfg(feature = "std")]
fn ht_contributions_have_supported_final_sets(
    contributions: &[PacketCodeBlockContribution],
) -> bool {
    contributions.iter().all(|contribution| {
        contribution.ht_coded
            && (1..=3).contains(
                &contribution
                    .expanded_ht_coding_sets
                    .as_deref()
                    .and_then(<[HtCodeBlockCodingSet]>::last)
                    .map_or(contribution.coding_passes, |coding_set| {
                        coding_set.coding_passes
                    }),
            )
    })
}

/// Decode the zero-decomposition subset with caller-retained workspace.
///
/// This compatibility entry point preserves the original profile boundary;
/// use [`decode_htj2k_lossless_owned_with_workspace`] for reversible DWT1.
#[cfg(feature = "std")]
pub fn decode_htj2k_lossless_no_decomp_owned_with_workspace(
    input: &[u8],
    workspace: &mut HtCodestreamDecodeWorkspace,
) -> Result<Option<DecodedImage>> {
    let codestream = parse(input)?;
    if codestream.kind == CodestreamKind::Htj2k
        && codestream
            .coding_style
            .is_some_and(|style| style.decomposition_levels != 0)
    {
        return Err(unsupported(
            None,
            Some(Marker::Cod),
            UnsupportedConstruct::WaveletTransform,
            "zero-decomposition HTJ2K compatibility decode does not accept wavelet decomposition",
        ));
    }
    decode_htj2k_lossless_owned_with_workspace(input, workspace)
}

/// Decode the zero-decomposition compatibility subset with ephemeral
/// workspace.
#[cfg(feature = "std")]
pub fn decode_htj2k_lossless_no_decomp_owned(input: &[u8]) -> Result<Option<DecodedImage>> {
    let mut workspace = HtCodestreamDecodeWorkspace::new();
    decode_htj2k_lossless_no_decomp_owned_with_workspace(input, &mut workspace)
}

/// Return whether marker and packet state fits the zero-decomposition
/// compatibility profile.
#[cfg(feature = "std")]
pub fn is_htj2k_lossless_no_decomp_profile(input: &[u8], codestream: &Codestream) -> bool {
    codestream
        .coding_style
        .is_some_and(|style| style.decomposition_levels == 0)
        && is_htj2k_lossless_profile(input, codestream)
}

fn ht_marker_state(codestream: &Codestream) -> Option<ht::HtMarkerState> {
    let coding_style = codestream.coding_style;
    let first_component = codestream.siz.components.first()?;
    Some(ht::HtMarkerState {
        has_cap_marker: codestream.capability.is_some(),
        components: codestream.siz.component_count(),
        sample_precision_bits: first_component.bits_per_sample,
        all_components_same_sample_format: codestream.siz.components.iter().all(|component| {
            component.bits_per_sample == first_component.bits_per_sample
                && component.signed == first_component.signed
        }),
        all_components_unit_sampled: codestream.siz.components.iter().all(|component| {
            component.horizontal_separation == 1 && component.vertical_separation == 1
        }),
        single_tile: codestream.siz.tile_count_x().ok()? == 1
            && codestream.siz.tile_count_y().ok()? == 1,
        has_tile_part: !codestream.tiles.is_empty(),
        packet_progression_supported: coding_style
            .is_some_and(|style| default_precinct_layer_count_supported(style.layers)),
        reversible_transform: coding_style
            .map(|style| style.transform == WaveletTransform::Reversible53)
            .unwrap_or(false),
        sop_markers: coding_style.map(|style| style.sop_markers).unwrap_or(false),
        eph_markers: coding_style.map(|style| style.eph_markers).unwrap_or(false),
        precincts_declared: coding_style
            .map(|style| {
                tile_rects(codestream).map_or(true, |tiles| {
                    tiles.iter().any(|tile| {
                        !coding_style_has_single_precinct(style, tile.width, tile.height)
                    })
                })
            })
            .unwrap_or(false),
        code_block_width: coding_style.and_then(|style| {
            ht_code_block_dimension_from_exponent(style.code_block_width_exponent)
        }),
        code_block_height: coding_style.and_then(|style| {
            ht_code_block_dimension_from_exponent(style.code_block_height_exponent)
        }),
    })
}

fn ht_code_block_dimension_from_exponent(exponent: u8) -> Option<u16> {
    let dimension = 1_u32.checked_shl(u32::from(exponent))?;
    u16::try_from(dimension).ok()
}

fn ht_construct_from_reason(reason: ht::HtUnsupportedReason) -> UnsupportedConstruct {
    match reason {
        ht::HtUnsupportedReason::MissingCapabilityMarker
        | ht::HtUnsupportedReason::PacketMarkers
        | ht::HtUnsupportedReason::Precincts
        | ht::HtUnsupportedReason::CodeBlockDimensions => UnsupportedConstruct::MarkerSegment,
        ht::HtUnsupportedReason::ComponentCount => UnsupportedConstruct::ComponentCount,
        ht::HtUnsupportedReason::SamplePrecision => UnsupportedConstruct::SamplePrecision,
        ht::HtUnsupportedReason::ComponentSampling => UnsupportedConstruct::ComponentSampling,
        ht::HtUnsupportedReason::MultipleTiles => UnsupportedConstruct::MultipleTiles,
        ht::HtUnsupportedReason::MissingTilePart => UnsupportedConstruct::MarkerSegment,
        ht::HtUnsupportedReason::ProgressionOrder => UnsupportedConstruct::ProgressionOrder,
        ht::HtUnsupportedReason::WaveletTransform => UnsupportedConstruct::WaveletTransform,
        ht::HtUnsupportedReason::BlockDecodeNotImplemented => UnsupportedConstruct::HtBlockDecode,
    }
}

fn parse_siz(segment: &[u8], marker_offset: usize) -> Result<SizMarker> {
    if segment.len() < 36 {
        return Err(invalid(
            Some(marker_offset),
            Some(Marker::Siz),
            "SIZ marker payload is too short",
        ));
    }

    let components = read_u16(segment, 34)? as usize;
    let expected_len = 36usize
        .checked_add(
            components
                .checked_mul(3)
                .ok_or(CodestreamError::SizeOverflow)?,
        )
        .ok_or(CodestreamError::SizeOverflow)?;
    if segment.len() != expected_len {
        return Err(invalid(
            Some(marker_offset),
            Some(Marker::Siz),
            "SIZ marker length must match component count",
        ));
    }

    let mut component_parameters = Vec::with_capacity(components);
    for component in 0..components {
        let offset = 36 + component * 3;
        let ssiz = segment[offset];
        component_parameters.push(ComponentParameters {
            bits_per_sample: (ssiz & 0x7f) + 1,
            signed: (ssiz & 0x80) != 0,
            horizontal_separation: segment[offset + 1],
            vertical_separation: segment[offset + 2],
        });
    }

    Ok(SizMarker {
        capabilities: read_u16(segment, 0)?,
        reference_grid_width: read_u32(segment, 2)?,
        reference_grid_height: read_u32(segment, 6)?,
        image_origin_x: read_u32(segment, 10)?,
        image_origin_y: read_u32(segment, 14)?,
        tile_width: read_u32(segment, 18)?,
        tile_height: read_u32(segment, 22)?,
        tile_origin_x: read_u32(segment, 26)?,
        tile_origin_y: read_u32(segment, 30)?,
        components: component_parameters,
    })
}

fn parse_cod(segment: &[u8], marker_offset: usize) -> Result<CodingStyleMarker> {
    if segment.len() < 10 {
        return Err(invalid(
            Some(marker_offset),
            Some(Marker::Cod),
            "COD marker payload is too short",
        ));
    }

    let scod = segment[0];
    let progression_order = match segment[1] {
        0 => ProgressionOrder::Lrcp,
        1 => ProgressionOrder::Rlcp,
        2 => ProgressionOrder::Rpcl,
        3 => ProgressionOrder::Pcrl,
        4 => ProgressionOrder::Cprl,
        _ => {
            return Err(unsupported(
                Some(marker_offset),
                Some(Marker::Cod),
                UnsupportedConstruct::ProgressionOrder,
                "COD marker declares an unknown progression order",
            ));
        }
    };
    let transform = match segment[9] {
        0 => WaveletTransform::Irreversible97,
        1 => WaveletTransform::Reversible53,
        _ => {
            return Err(unsupported(
                Some(marker_offset),
                Some(Marker::Cod),
                UnsupportedConstruct::WaveletTransform,
                "COD marker declares an unknown wavelet transform",
            ));
        }
    };
    let code_block_width_exponent = segment[6]
        .checked_add(2)
        .ok_or(CodestreamError::SizeOverflow)?;
    let code_block_height_exponent = segment[7]
        .checked_add(2)
        .ok_or(CodestreamError::SizeOverflow)?;
    let precincts_declared = (scod & 0x01) != 0;
    let mut precinct_exponents = [0_u8; 33];
    let precinct = if precincts_declared {
        let precinct_count = usize::from(segment[5])
            .checked_add(1)
            .ok_or(CodestreamError::SizeOverflow)?;
        if precinct_count > precinct_exponents.len() {
            return Err(unsupported(
                Some(marker_offset),
                Some(Marker::Cod),
                UnsupportedConstruct::WaveletTransform,
                "COD marker declares more than 32 wavelet decomposition levels",
            ));
        }
        let declared = segment.get(10..10 + precinct_count).ok_or_else(|| {
            invalid(
                Some(marker_offset),
                Some(Marker::Cod),
                "COD marker omits one or more declared precinct exponents",
            )
        })?;
        precinct_exponents[..precinct_count].copy_from_slice(declared);
        declared.first().copied()
    } else {
        None
    };

    Ok(CodingStyleMarker {
        entropy_coder: EntropyCoder::ClassicTier1,
        sop_markers: (scod & 0x02) != 0,
        eph_markers: (scod & 0x04) != 0,
        precincts_declared,
        precinct_width_exponent: precinct.map(|value| value & 0x0f),
        precinct_height_exponent: precinct.map(|value| value >> 4),
        precinct_exponents,
        progression_order,
        layers: read_u16(segment, 2)?,
        multiple_component_transform: segment[4] != 0,
        decomposition_levels: segment[5],
        code_block_width_exponent,
        code_block_height_exponent,
        code_block_style: segment[8],
        transform,
    })
}

fn parse_cap(segment: &[u8], marker_offset: usize) -> Result<CapabilityMarker> {
    if segment.len() < 4 {
        return Err(invalid(
            Some(marker_offset),
            Some(Marker::Cap),
            "CAP marker payload must contain one or more four-byte capability words",
        ));
    }

    let mut pcaps = Vec::new();
    let mut offset = if segment.len().is_multiple_of(4) {
        0
    } else if segment.len() >= 6 && (segment.len() - 2).is_multiple_of(4) {
        2
    } else {
        return Err(invalid(
            Some(marker_offset),
            Some(Marker::Cap),
            "CAP marker payload must contain one or more four-byte capability words",
        ));
    };
    while offset < segment.len() {
        pcaps.push(read_u32(segment, offset)?);
        offset += 4;
    }

    Ok(CapabilityMarker { pcaps })
}

fn retain_tile_part_header_markers(
    input: &[u8],
    mut offset: usize,
    markers: &mut Vec<MarkerSegment>,
) -> Result<usize> {
    loop {
        let marker_offset = offset;
        let marker = read_marker(input, marker_offset)?;
        offset = offset.checked_add(2).ok_or(CodestreamError::SizeOverflow)?;

        if marker == Marker::Sod {
            markers.push(MarkerSegment {
                marker,
                offset: marker_offset,
                data_offset: offset,
                data_len: 0,
            });
            return Ok(offset);
        }

        if !marker.has_segment() {
            if marker.is_reserved_parameterless() {
                markers.push(MarkerSegment {
                    marker,
                    offset: marker_offset,
                    data_offset: offset,
                    data_len: 0,
                });
                continue;
            }
            return Err(invalid(
                Some(marker_offset),
                Some(marker),
                "tile-part header must terminate with SOD before packet data",
            ));
        }

        let segment_len = read_u16(input, offset)? as usize;
        if segment_len < 2 {
            return Err(invalid(
                Some(marker_offset),
                Some(marker),
                "marker segment length must include the two-byte length field",
            ));
        }
        let data_offset = offset.checked_add(2).ok_or(CodestreamError::SizeOverflow)?;
        let data_len = segment_len - 2;
        require(input, data_offset, data_len)?;
        markers.push(MarkerSegment {
            marker,
            offset: marker_offset,
            data_offset,
            data_len,
        });
        offset = data_offset
            .checked_add(data_len)
            .ok_or(CodestreamError::SizeOverflow)?;
    }
}

fn parse_sot(segment: &[u8], marker_offset: usize) -> Result<TilePartState> {
    if segment.len() != 8 {
        return Err(invalid(
            Some(marker_offset),
            Some(Marker::Sot),
            "SOT marker payload must be exactly eight bytes",
        ));
    }

    let tile_part_length = match read_u32(segment, 2)? {
        0 => None,
        value => Some(value),
    };
    let tile_part_count = match segment[7] {
        0 => None,
        value => Some(value),
    };

    Ok(TilePartState {
        tile_index: read_u16(segment, 0)?,
        tile_part_length,
        tile_part_index: segment[6],
        tile_part_count,
        payload_offset: None,
        payload_len: None,
    })
}

fn tile_payload_len(
    input: &[u8],
    sot_marker_offset: usize,
    payload_offset: usize,
    tile_part_length: Option<u32>,
) -> Result<usize> {
    if let Some(tile_part_length) = tile_part_length {
        let tile_part_end = sot_marker_offset
            .checked_add(
                usize::try_from(tile_part_length).map_err(|_| CodestreamError::SizeOverflow)?,
            )
            .ok_or(CodestreamError::SizeOverflow)?;
        if tile_part_end < payload_offset {
            return Err(invalid(
                Some(sot_marker_offset),
                Some(Marker::Sot),
                "SOT tile-part length ends before SOD payload",
            ));
        }
        require(input, payload_offset, tile_part_end - payload_offset)?;
        return Ok(tile_part_end - payload_offset);
    }

    let eoc_offset = find_marker(input, payload_offset, Marker::Eoc).ok_or_else(|| {
        invalid(
            Some(payload_offset),
            Some(Marker::Sod),
            "open-ended tile-part payload must terminate with EOC",
        )
    })?;
    Ok(eoc_offset - payload_offset)
}

fn validate_siz(siz: &SizMarker) -> Result<()> {
    if siz.reference_grid_width == 0 || siz.reference_grid_height == 0 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "reference grid dimensions must be non-zero",
        ));
    }
    if siz.image_origin_x >= siz.reference_grid_width
        || siz.image_origin_y >= siz.reference_grid_height
    {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "image origin must be inside the reference grid",
        ));
    }
    if siz.tile_width == 0 || siz.tile_height == 0 {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "tile dimensions must be non-zero",
        ));
    }
    if siz.tile_origin_x > siz.image_origin_x || siz.tile_origin_y > siz.image_origin_y {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "tile origin must not exceed image origin",
        ));
    }
    if siz.components.is_empty() {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "component count must be non-zero",
        ));
    }
    if siz
        .components
        .iter()
        .any(|component| component.horizontal_separation == 0 || component.vertical_separation == 0)
    {
        return Err(invalid(
            None,
            Some(Marker::Siz),
            "component sampling separations must be non-zero",
        ));
    }

    Ok(())
}

fn read_marker(input: &[u8], offset: usize) -> Result<Marker> {
    let code = read_u16(input, offset)?;
    if code & 0xff00 != 0xff00 {
        return Err(invalid(Some(offset), None, "expected a marker prefix byte"));
    }
    Ok(Marker::from_code(code))
}

fn checked_slice(input: &[u8], offset: usize, len: usize) -> Result<&[u8]> {
    let end = offset
        .checked_add(len)
        .ok_or(CodestreamError::SizeOverflow)?;
    input
        .get(offset..end)
        .ok_or(CodestreamError::TruncatedInput {
            offset,
            needed: len,
            remaining: input.len().saturating_sub(offset),
        })
}

fn find_marker(input: &[u8], start: usize, marker: Marker) -> Option<usize> {
    let needle = marker.code().to_be_bytes();
    input
        .get(start..)?
        .windows(2)
        .position(|bytes| bytes == needle)
        .map(|relative| start + relative)
}

fn require(input: &[u8], offset: usize, needed: usize) -> Result<()> {
    checked_slice(input, offset, needed).map(|_| ())
}

fn read_u16(input: &[u8], offset: usize) -> Result<u16> {
    Ok(u16::from_be_bytes(
        checked_slice(input, offset, 2)?
            .try_into()
            .map_err(|_| CodestreamError::SizeOverflow)?,
    ))
}

fn read_u32(input: &[u8], offset: usize) -> Result<u32> {
    Ok(u32::from_be_bytes(
        checked_slice(input, offset, 4)?
            .try_into()
            .map_err(|_| CodestreamError::SizeOverflow)?,
    ))
}

fn ceil_div(numerator: u32, denominator: u32) -> Result<u32> {
    if denominator == 0 {
        return Err(CodestreamError::SizeOverflow);
    }
    Ok(numerator.div_ceil(denominator))
}

fn invalid(
    offset: Option<usize>,
    marker: Option<Marker>,
    message: &'static str,
) -> CodestreamError {
    CodestreamError::InvalidMarker {
        offset,
        marker,
        message,
    }
}

fn unsupported(
    offset: Option<usize>,
    marker: Option<Marker>,
    construct: UnsupportedConstruct,
    message: &'static str,
) -> CodestreamError {
    CodestreamError::Unsupported {
        offset,
        marker,
        construct,
        message,
    }
}
